struct fenwick {
  int N;
  vector<int> bit;

  fenwick(int n = 1e5) {
    N = n + 5;
    bit.assign(N, 0);
  }

  void resize(int n) {
    N = n + 5;
    bit.assign(N, 0);
  }

  void update(int x, int val) {
    while (x < N) {
      bit[x] += val;
      x += x&-x;
    }
  }

  int query(int x) {
    int ret=0;
    while (x > 0) {
      ret += bit[x];
      x -= x&-x;
    }
    return ret;
  }
};

