using namespace std;

typedef long long ll;

ll merge_cnt(vector<ll> &a) {
    int n = a.size();
    if (n <= 1) { return 0; }

    ll cnt = 0;
    vector<ll> b(a.begin(), a.begin()+n/2);
    vector<ll> c(a.begin()+n/2, a.end());

    cnt += merge_cnt(b);
    cnt += merge_cnt(c);

    int ai = 0, bi = 0, ci = 0;
    // merge の処理
    while (ai < n) {
        if ( bi < b.size() && (ci == c.size() || b[bi] >= c[ci]) ) {
            a[ai++] = b[bi++];
        } else {
            cnt += n/2 - bi;
            a[ai++] = c[ci++];
        }
    }
    return cnt;
}

bool judge(vector<ll> &a, ll x) {
    ll n = a.size();
    ll sum_v = 0;
    vector<ll> s = {0};

    for (auto &e: a) {
        int t = (e <= x) ? 1 : -1;
        sum_v += t;
        s.push_back( sum_v );
    }

    return merge_cnt(s) > n*(n+1)/2/2;
}

int main() {
    int n; cin >> n;

    vector<ll> a(n);

    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    ll high = 1e18, low = 0;

    while (low < high) {
        ll mid = ( high + low ) / 2;

        if ( judge(a, mid) ) {
            high = mid;
        } else {
            low = mid+1;
        }
    }

    cout << high << endl;

    return 0;
}

