    }
  }
  return cnt;
}

ll inversionNumber(int l, int r) {
  if(r - l <= 1) return 0;

  int m;
  ll v1, v2, v3;
  m = (l + r) / 2;
  v1 = inversionNumber(l, m);
  v2 = inversionNumber(m, r);
  v3 = merge(l, m, r);
  return v1 + v2 + v3;
}

