    int mid = (lb + ub) >> 1;
    vector<int> b(n);
    REP(i, n) b[i] = a[i] <= mid ? 1 : -1;
    BIT0based<int> bit(n * 2 + 1);
    int now = n;
    REP(i, n) {
      now += b[i];
      bit.add(now, 1);
    }
    now = n;
    ll cnt = 0;
    REP(i, n) {
      cnt += bit.sum(now + 1, n * 2 + 1);
      now += b[i];
      bit.add(now, -1);
    }
    // cout << mid << ' ' << cnt << '\n';
    (cnt <= pat / 2 ? lb : ub) = mid;
  }
  cout << ub << '\n';
  return 0;
}

