int mergesort(int l,int r){
	if(l==r)return 0;
	int mid=l+r>>1;
	int ret=mergesort(l,mid);
	ret+=mergesort(mid+1,r);
	for(int i=l;i<=(l+r)/2;i++)ll[i]=pre[i];
	for(int i=(l+r)/2+1;i<=r;i++)rr[i]=pre[i];
	int pos=l,lpos=l,rpos=mid+1;
	while(lpos!=mid+1||rpos!=r+1){
		if(lpos==mid+1){pre[pos++]=rr[rpos++];continue;}
		if(rpos==r+1){pre[pos++]=ll[lpos++];continue;}
		if(ll[lpos]<=rr[rpos]){
			ret+=(r+1-rpos);
			pre[pos++]=ll[lpos++];
		}else{
			pre[pos++]=rr[rpos++];
		}
	}
	return ret;
}
