bool good(int c){
  for(int i=0;i<n;i++){
    if (a[i] >= c) p[i] = 1;
    else p[i] = -1;
  }
  for(int i=0;i<2*MAXN;i++) csum[i] = 0;

  int cs = MAXN;
  csum[cs] = 1;
  int ctot = 1;
  long long res = 0;
  for(int i=0;i<n;i++){
    if(p[i] == -1){
      ctot -= csum[cs];
      cs--;
    }else{
      ctot += csum[cs+1];
      cs++;
    }
    res += ctot;
    csum[cs]++;
    ctot++;
  }
  return res * 2 >= (n*((long long)n+1))/2;
}

