bool check(int x){
    //bitを初期化
    for (int i = 0; i<200001; i++) bit[i] = 0;
    //x以上とx未満を1と−1に置き換え
    vector<int> a3(N);
    for (int i = 0; i<N; i++){
        if (a2[i]>=x) a3[i] = 1;
        else a3[i] = -1;
    }
    //累積和
    //BITでは0以下の数を扱えないので、10^5を足しておけばよい
    vector<long long> acc(N+1);
    for (int i = 0; i<N+1; i++) acc[i] = pow(10,5);
    for (int i = 0; i<N; i++) acc[i+1] = a3[i] + acc[i];

    int ans = 0;
    for (int i = 0; i<N+1; i++){
        ans += sum(acc[i]);
        add(acc[i],1);
    }
    //ansがNの半数より大きいならtrue
    if (ans*2 >= N*(N+1)/2) return true;
    else return false;
}

