template <typename T> struct BIT {
  int n;
  vector<T> bit;
  // 1-indexed
  BIT(int n_) : n(n_ + 1), bit(n + 1, 0) {}

  T sum(int i) {
    T s(0);
    for (int x = i; x > 0; x -= (x & -x))
      s += bit[x];
    return s;
  }

  void add(int i, T a) {
    if (i == 0)
      return;
    for (int x = i; x <= n; x += (x & -x))
      bit[x] += a;
  }

  // [l, r)
  T query(int l, int r) { return sum(r - 1) - sum(l - 1); }

  int lower_bound(int w) {
    if (w <= 0)
      return 0;
    int x = 0, r = 1;
    while (r < n)
      r <<= 1;
    for (int k = r; k > 0; k >>= 1) {
      if (x + k <= n && bit[x + k] < w) {
        w -= bit[x + k];
        x += k;
      }
    }
    return x + 1;
  }

  // 0-indexed
  T sum0(int i) { return sum(i + 1); }
  void add0(int i, T a) { add(i + 1, a); }
  T query0(int l, int r) { return sum(r) - sum(l); }
};

void solver() {
  i64 N = input();
  vector<i32> v(N);
  cin >> v;

  auto c = v;
  whole(sort, c);
  c.erase(whole(unique, c), c.end());

  i32 ok = 0, ng = c.size();
  while (ng - ok > 1) {
    i32 mid = (ok + ng) / 2;
    i32 a = c[mid];

    vector<i32> r(N + 1);
    r[0] = N;
    range(i, 1, N + 1) {
      r[i] = (v[i - 1] >= a ? 1 : -1);
      r[i] += r[i - 1];
    }

    BIT<i64> bit(3 * N);
    i64 cnt = 0;
    range(i, 0, N + 1) {
      cnt += bit.sum(r[i]);
      bit.add(r[i], 1);
    }

    if (cnt >= (N * (N - 1) + 3) / 4) {
      ok = mid;
    } else {
      ng = mid;
    }
  }

  cout << c[ok] << endl;
}

signed main(int argc, char *argv[]) { solver(); }

