void postavi(int t, int l, int r)
{
    seg[t]=0;
    if(l==r) return;
    int mid=(l+r)/2;
    postavi(2*t,l,mid);
    postavi(2*t+1,mid+1,r);
}

void update(int t, int l,int r, int x)
{
    seg[t]++;
    if(l==r) return;
    int mid=(l+r)/2;
    if(x<=mid) update(2*t,l,mid,x);
    else update(2*t+1,mid+1,r,x);
}

ll sum(int t, int l, int r, int L, int R)
{
    if(l>R || L>r)
        return 0;
    if(l>=L && r<=R)
        return seg[t];
    int mid=(l+r)/2;
    return sum(2*t,l,mid,L,R)+sum(2*t+1,mid+1,r,L,R);
}

ll cnt(int br)
{
    ll sol=0;
    for(int i=0;i<n;i++)
        if(a[i]>=br) b[i]=1;
        else b[i]=-1;
    for(int i=1;i<n;i++)
        b[i]+=b[i-1];
    postavi(1,1,maxn);
    update(1,1,maxn,k);
    for(int i=0;i<n;i++)
    {
        sol+=sum(1,1,maxn,1,b[i]+k);
        update(1,1,maxn,b[i]+k);
        if(a[i]>=br && i>0) sol++;
    }
    return sol;
}


