ll calc(ll in) {
  ll res = 0;
  memset(sum, 0, sizeof sum);
  memset(num, 0, sizeof num);
  for (int i = 1; i <= n; i++) {
    if (a[i] >= in)
      sum[i] = sum[i - 1] + 1;
    else
      sum[i] = sum[i - 1] - 1;
  }
