  num[N] = 1;
  for (int i = 1; i <= n; i++) {
    if (sum[i] > sum[i - 1])
      pre += num[sum[i] + N] + 1;
    else
      pre -= num[sum[i - 1] + N] - 1;
    num[sum[i] + N]++;
    res += pre;
  }
  return res;
}

