using namespace std;


class FenwickTree {
public:
    const unsigned long long n;
    std::vector<long long> v;

    FenwickTree(unsigned long long n) : n(n) {
        this->v.assign(n + 1, 0);
    }

    // sum(v[0, i))
    long long sum(int i) {
        assert(0 <= i && i <= this->n);

        long long s = 0;
        i -= 1;
        while (i >= 0) {
            s += this->v[i];
            i = (i & (i + 1)) - 1;
        }
        return s;
    }

    // sum(v[left, right))
    long long sum(int left, int right) {
        assert(left <= right);
        return this->sum(right) - this->sum(left);
    }

    // v[i] += x(0-origin)
    void add(int i, long long x) {
        assert(i < this->n);

        while (i < this->n) {
            this->v.at(i) += x;
            i |= i + 1;
        }
    }
};



bool ok(LL x, const vector<LL> A) {

    LL N = A.size();
    vector<LL> dp(N + 1, 0);
    FOR(i, 0, N) {
        LL a = A[i] >= x ? 1 : -1;
        dp[i + 1] = dp[i] + a;
    }

    FenwickTree ft(300000);
    LL base = 100000;

    long long num = 0;
    for (int i = 0; i < dp.size(); ++i) {
        LL v = base + dp[i];
        num += ft.sum(v + 1);
        ft.add(v, 1);
    }

    LL a = N * (N - 1) / 2 + N;
    return num >= ceil(a, 2LL);

}

