		sortedA[i] = A[i];
	}
	sort(sortedA.begin(), sortedA.end());
	int ub = N;
	int lb = 0;
	BIT bit;

	long long border = ((N * (N + 1) / 2) + 1) / 2;
	while (ub - lb > 1) {
		int mid = (ub + lb) / 2;
		int midn = sortedA[mid];
		bit.init(2 * N + 1);
		int sum = 0;
		bit.add(sum + N, 1);
		long long result = 0;
		for (i = 0; i < N; i++) {
			sum += A[i] >= midn ? 1 : -1;
			result += bit.sum(sum + N);
			bit.add(sum + N, 1);
		}
		if (result >= border) {
			lb = mid;
		}
		else {
			ub = mid;
		}
	}
	cout << sortedA[lb] << endl;
	return 0;
}

