template<class T>
long long inversion(vector<T> &a) {
  int n = a.size();
  if (n <= 1)return 0;
  ll cnt = 0;
  vector<T> b(a.begin(), a.begin() + n / 2);
  vector<T> c(a.begin() + n / 2, a.end());

  cnt += inversion(b);
  cnt += inversion(c);

  int ai = 0, bi = 0, ci = 0;

  while (ai < n) {
    if (bi < b.size() && (ci == c.size() || b[bi] <= c[ci])) {
      a[ai] = b[bi];
      bi++;
    }
    else {
      cnt += n / 2 - bi;
      a[ai] = c[ci];
      ci++;
    }
    ai++;
  }
  return cnt;
}

long long count(vector<int> a, int k) {
    vector<int> b(N);
    vector<int> c(N + 1);
    vector<int> d(N + 1);
    rep(i, N) {
        if (a[i] <= k) b[i] = 1;
        else           b[i] = 0;
        c[i + 1] = c[i] + b[i];
        d[i + 1] = 2 * c[i + 1] - i;
    }
    c[0] = 0;
    d[0] = 0;
    repr(i, 1, N + 1){
        c[i] = c[i - 1] + b[i - 1];
        d[i] = 2 * c[i] - i;
    }
    reverse(all(d));
    return inversion(d);
}


