//bitを足す時はLSBが小さい方から大きい方へ
void add(int a, int w){
    for (int x = a; x<200001; x += x & -x) bit[x] += w;
}
//和を求める時は、LSBが大きい方から小さい方へ
int sum(int a){
    int ret = 0;
    for (int x = a; x>0; x -= x & -x) ret += bit[x];
    return ret;
