//x以上の要素がaの半数より多く存在するときture
bool check(int x){
    //bitを初期化
    for (int i = 0; i<200001; i++) bit[i] = 0;
    //x以上とx未満を1と−1に置き換え
    vector<int> a3(N);
    for (int i = 0; i<N; i++){
        if (a2[i]>=x) a3[i] = 1;
        else a3[i] = -1;
    }
    //累積和
    //BITでは0以下の数を扱えないので、はじめに10^5を足しておけばよい
    vector<int> acc(N+1);
    acc[0] = 100000;
    for (int i = 1; i<N+1; i++) acc[i] = 0;
    for (int i = 0; i<N; i++) acc[i+1] = a3[i] + acc[i];

    long long ans = 0;
    for (int i = 0; i<N+1; i++){
        ans += sum(acc[i]);
        add(acc[i],1);
    }
    //ansがNの半数より大きいならtrue
    if (ans*2 >= (long long)N*(N+1)/2) return true;
    else return false;
}

