#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
const int N = 100010;

LL tr[N << 1];
int a[N], n, s[N], tmp[N];
void update(int i, LL x) { for (; i <= n + N; i += i & -i) tr[i] += x; }
LL query(int i, LL ret = 0) { for (; i; i -= i & -i) ret += tr[i]; return ret; }

LL check(int num)
{
    LL ans = 0;
    memset(tr,0,sizeof tr);
    for (int i = 1; i <= n; i++)
    {
        if (a[i] < num) s[i] = s[i - 1] - 1;
        if (a[i] >= num) s[i] = s[i - 1] + 1;
        update(s[i] + N, 1);
        ans += query(s[i] + N);
    }
    return ans;
}

int main()
{
    LL ans;
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> a[i];
    memcpy(tmp, a, sizeof a);
    sort(tmp + 1, tmp + n + 1);
    int cnt = unique(tmp + 1, tmp + n + 1) - tmp - 1;
    LL k = ((LL)n * (n + 1 ) / 2)/2 + 1;
    for (int l = 1, r = cnt, mid = l + r >> 1; l <= r; mid = l + r >> 1)
    {
        if (check(tmp[mid]) >= k) ans = tmp[mid], l = mid + 1;
        else r = mid - 1;
    }
    cout << ans << endl;
    return 0;
}

