ll inversion(vector<int> d){

    BIT<ll> bit(d.size() *2);
    ll ans = 0;
    REP(i,d.size()){
        ans += i - bit.sum(d[i] + d.size());
        bit.add(d[i]+d.size(), 1);
    }
    //bit.print();

    return ans;
}

ll count(vector<int> a, int m){
    vector<int> b(a.size());
    vector<int> c(a.size()+1,0);
    vector<int> d(a.size()+1,0);

    REP(i,a.size()){
        if(a[i]<=m) b[i] = 1;
        else b[i] = 0;

        c[i+1] = c[i] + b[i];
        d[i+1] = 2*c[i+1] - (i+1);
    }

    reverse(ALL(d));
    return inversion(d);
}

