	for (int i = 1; i <= N; i++) { 
		int op; 
		if (a[i] > mid) op = 1; 
		if (a[i] <= mid) op = -1; 
		s[i] = s[i - 1] + op; 
	} 
	long long res = 0; 
	MAX = N << 2; 
	int T = N << 1; 
	for (int i = 1; i <= N; i++) { 
		int pos = s[i] + T; 
		res += sum(MAX) - sum(pos); 
		add(pos, 1); 
	} 
	memset(c, 0, sizeof(c)); 
	return res >= goal_rank; 
} 
bool cheque(int mid) { 
	static int s[MAX_N]; 
	for (int i = 1; i <= N; i++) { 
		int op; 
		if (a[i] > mid) op = 1; 
		if (a[i] < mid) op = -1; 
		if (a[i] == mid) op = 0; 
		s[i] = s[i - 1] + op; 
	} 
	long long res = 0; 
	MAX = N << 2; 
	int T = N << 1;
	add(T, 1); 
	for (int i = 1; i <= N; i++) { 
		int pos = s[i] + T; 
		res += sum(MAX) - sum(pos); 
		add(pos, 1); 
	} 
	memset(c, 0, sizeof(c)); 
	return res >= goal_rank; 
} 

