using namespace std;

const ll siz = 1e5 + 10;
const ll mod = 1e9 + 7;
const ll MAXX = 1e18; 

ll n;
map<ll, bool> check;

//input
vector<ll> hold;
vector<ll> alternate;
vector<ll> dis;

//tree
ll tree[4 * siz];

void update(ll pos) {
	for (ll i = pos; i <= 2 * siz; i += i & -i) {
		//cerr << pos << '\n';
		tree[i]++;
	}
}

ll get(ll pos) {
	ll ans = 0;
	for (ll i = pos; i; i -= i & -i) {
		ans += tree[i];
	}
	return ans;
}

void setAlte(ll num) {
	for (ll i = 1; i <= n; i++) {
		if (hold[i] < num) {
			alternate[i] = 0;
		}
		else {
			alternate[i] = 1;
		}
	}
	for (ll i = 1; i <= n; i++) {
		alternate[i] += alternate[i - 1];
	}
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);
	//freopen("INP.txt", "r", stdin);
	//freopen("OUT.txt", "w", stdout);
	cin >> n;
	hold.resize(n + 1);
	alternate.resize(n + 1);
	for (ll i = 1; i <= n; i++) {
		cin >> hold[i];
		if (!check[hold[i]]) {
			check[hold[i]] = true;
			dis.push_back(hold[i]);
		}
	}
	ll tar = n * (n + 1) / 2;
	tar /= 2;
	dis.push_back(0);
	sort(dis.begin(), dis.end());
	ll le = 1, ri = dis.size() - 1;
	ll ans = 0;
	while (le <= ri) {
		//cerr << le << ' ' << ri << '\n';
		ll mid = (le + ri) / 2;
		ll num = dis[mid];
		setAlte(num);
		update(siz);
		ll cnt = 0;
		for (ll i = 1; i <= n; i++) {
			cnt += get(2 * alternate[i] - i + siz);
			update(2 * alternate[i] - i + siz);	
		}
		if (cnt >= tar) {
			ans = max(ans, num);
			le = mid + 1;
		}
		else {
			ri = mid - 1;
		}
		memset(tree, 0, sizeof(tree));
	}
	cout << ans << '\n';
	return 0; 	
}

