        return;
    int mid = (l+r)/2;
    merge(a,l,mid);
    merge(a,mid+1,r);
    int i=l,j=mid+1,index=l;
    while (i<=mid&&j<=r){
        if(a[i]>a[j]){
            c[index++]=a[j];
            ans+=mid-i+1;
            j++;
        } else{
            c[index++]=a[i];
            i++;
        }
