struct BIT {
    vector<LL> bit;
    int M;

    BIT(int M) : bit(vector<LL>(M + 1, 0LL)), M(M) {}

    LL sum(int i) {
        if (!i) return 0;
        return bit[i] + sum(i - (i & -i));
    }

    void add(int i, LL x) {
        if (i > M) return;
        bit[i] += x;
        add(i + (i & -i), x);
    }
};


