	void init(long long n_input) {
		n = n_input + 1;
		dat.resize(n + 1);
		for (int i = 0; i <= n; i++) dat[i] = 0;
	}

	long long sum(long long i) {
		long long s = 0;
		while (i >= 0) {
			s += dat[i];
			i = (i & (i + 1)) - 1;
		}
		return s;
	}

	void add(long long i, long long x) {
		while (i <= n) {
			dat[i] += x;
			i |= i + 1;
		}
	}
};

