#include<bits/stdc++.h>
#define lson root<<1
#define rson root<<1|1
using namespace std;

int n;
int a[200010];
int sum[200010];

struct node
{
	int l, r, sum;
}tr[1600080];

int push_up(int root)
{
	tr[root].sum = tr[lson].sum + tr[rson].sum;
}

int build(int root, int l, int r)
{
	if (l == r)
	{
		tr[root].sum = 0;
		tr[root].l = l;
		tr[root].r = r;
		return 0;
	}
	tr[root].l = l;
	tr[root].r = r;
	int mid = (l + r) >> 1;
	build(lson, l, mid);
	build(rson, mid + 1, r);
	push_up(root);
}

int update(int root, int pos)
{
	if (pos == tr[root].l&&pos == tr[root].r)
	{
		tr[root].sum++;
		return 0;
	}
	int mid = (tr[root].l + tr[root].r) >> 1;
	if (pos <= mid)
	{
		update(lson, pos);
	}
	else
	{
		update(rson, pos);
	}
