int main(){
  cin>>N;
  for(int i=0;i<N;i++){
    cin>>m[i];
    t[i]=m[i];
  }
  sort(t,t+N);
  int a=0,b=N;
  while(a<b){
    int c=(a+b)/2;
    int d=t[c];
    vector<pair<int,int>>v(N);
    vector<int>dp(IDX*2);
    for(int i=0;i<N;i++){
      if(m[i]<d)v[i].first=-1;
      else v[i].first=1;
      if(i) v[i].first += v[i-1].first;
      v[i].second=i;
    }
    sort(v.begin(),v.end());
    long long sum = 0LL;
    for(auto& p:v){
      int idx = p.second + IDX;
      while(idx){
        dp[idx]++;
        idx/=2;
      }
      dp[0]=dp[1];
      int from = IDX;
      idx = p.second + IDX;
      while(from<=idx){
        if(idx%2==0){
          sum += dp[idx];
          idx--;
        } else {
          idx/=2;
          from/=2;
        }
      }
    }
    if(sum<N*(N+1)/2/2){
      b = c;
    } else {
      ans = max(ans, d);
      a = c + 1;
    }
  }
