	num mid = (l + r) >> 1, pos = l, i = l, j = mid + 1;

	calc(l, mid);

	calc(mid + 1, r);

	while (i <= mid || j <= r) {

		if (j > r || (i <= mid && pre[i] <= pre[j])) {

			b[pos++] = pre[i++];

		} else {

