#define BIG_NUM 2000000000
#define HUGE_NUM 1000000000000000000
#define MOD 1000000007
#define EPS 0.000000001
using namespace std;


#define SIZE 100005

ll N;
ll BIT[SIZE];
ll A[SIZE];
ll table[SIZE];

void add(ll loc,ll value){

	BIT[loc] += value;

	loc += loc & -loc;

	while(loc <= (N+1)){
		BIT[loc] += value;
		loc += loc & -loc;
	}
}

ll getSum(ll loc){

	ll sum = BIT[loc];

	loc -= loc & -loc;

	while(loc > 0){
		sum += BIT[loc];
		loc -= loc & -loc;
	}
	return sum;
}

int main(){

	scanf("%lld",&N);

	ll minimum = BIG_NUM,maximum = -BIG_NUM;

	for(ll i = 1; i <= N; i++){

		scanf("%lld",&A[i]);
		minimum = min(minimum,A[i]);
		maximum = max(maximum,A[i]);
	}

	ll all = N*(N+1)/2;
	ll half;
	if(all%2 == 0){

		half = all/2;
	}else{

		half = all/2+1;
	}

	ll left = minimum,right = maximum,mid = (left+right)/2;
	ll ans;

	while(left <= right){

		table[0] = 0;
		minimum = 0;

		for(ll i = 1; i <= N; i++){
			if(A[i] < mid){
				table[i] = -1;
			}else{

				table[i] = 1;
			}
			table[i] += table[i-1];
			minimum = min(minimum,table[i]);
		}

		for(ll i = 0; i <= N+1; i++)BIT[i] = 0;

		ll tmp = 0;

		//自分の左にある、自分以下の数を数える
		for(ll i = 0; i <= N; i++){

			ll loc = table[i]-minimum+1; //BITなので、最小値を1にする

			tmp += getSum(loc);
			add(loc,1);
		}

		if(tmp >= half){

			ans = mid;
			left = mid+1;
		}else{

			right = mid-1;
		}
		mid = (left+right)/2;
	}

	printf("%lld\n",ans);

	return 0;
}

