template <class T>
struct FenwickTree {
    int n;
    std::vector<T> x;
    FenwickTree(int _n = 0) : n(_n), x(n + 1, 0) {}
    int size() const { return n; }
    T Sum(int r) const {
        T S = 0;
        for (r = r - 1; r >= 0; r = (r & (r + 1)) - 1) S += x[r];
        return S;
    }
    T Sum(int l, int r) const { return Sum(r) - Sum(l); }
    void Add(int k, const T &a) {
        for (; k < n; k |= k + 1) x[k] += a;
    }
    void Set(int k, const T &a) { Add(k, a - Sum(k, k + 1)); }
};


class ProblemD {
public:
    ProblemD(int _n) : n(_n), a(_n + 1), s(_n + 1, 0) {}
    void Input() { for (int i = 1; i <= n; ++i) cin >> a[i]; }

    int Solve() {
        if (n == 1) return a[1];

        const int lim = ceil(n * (n + 1) / 4.0);

        int lb = 0, ub = *max_element(a.begin(), a.end()) + 1;
        while (ub - lb > 1) {
//            cout << "lb = " << lb << ", ub = " << ub << endl;
            int mid = 0.5 * (lb + ub);
            ll res = Check(mid);
//            cout << "x = " << mid << ", num = " << res << ", lim = " << lim << endl;

            if (lim <= res) lb = mid;
            else ub = mid;
        }

        return lb;
    }

private:
    int n;
    vector<int> a;
    vector<ll> s;

    ll Check(const int x) {
        for (int i = 1; i <= n; ++i)
            s[i] = (x <= a[i] ? 1 : -1);
        for (int i = 1; i <= n; ++i)
            s[i] += s[i - 1];
        ll min_e = abs(*min_element(s.begin(), s.end()));
        for (int i = 0; i <= n; ++i) s[i] += min_e;
        for (int i = 1; i <= n; ++i) s[i] += s[i - 1];

        // cout << "a = ";
        // for (int i = 0; i <= n; ++i) cout << a[i] << ", ";
        // cout << endl;
        // cout << "s = ";
        // for (int i = 0; i <= n; ++i) cout << s[i] << ", ";
        // cout << endl;
        // cout << "s = ";
        // for (int i = 0; i <= n; ++i) cout << s[i] << ", ";
        // cout << endl;
        // cout << endl;

        const ll max_e = *max_element(s.begin(), s.end());
        ll res = 0;
        FenwickTree<ll> tree(max_e);


        for (int i = n; 0 <= i; --i) {
            tree.Add(s[i], 1);
            res += tree.Sum(s[i], max_e + 1);
        }

        return res;
    }
};

