struct BIT {
private:
	vector<T> data;
	int maxid;

public:
	BIT(int n);
	BIT();
	void init(int n);

	void add(int idx, T val);

	// sum up to idx (close-end)
	T sum(int idx);

	// sum for [l, r) (1-indexed)
	T sum(int left, int right);

	T operator[](int i);
};

