bool check(int x)
{
	BIT<ll> bit(2 * n);
	ll n_sect = 0;
	int sum = 0;

	bit.add(n, 1);

	REP(i, n)
	{
		sum += (va[i] <= x) ? 1 : -1;
		n_sect += bit.sum(sum + n);
		bit.add(sum + n, 1);
	}

	return n_sect >= n_totsect / 2;
}

