ll merge_cnt(vector<ll> &a) {
  ll n = a.size();
  if (n <= 1) {
    return 0;
  }

  ll cnt = 0;
  vl b(a.begin(), a.begin() + n / 2);
  vl c(a.begin() + n / 2, a.end());

  cnt += merge_cnt(b);
  cnt += merge_cnt(c);

  ll ai = 0, bi = 0, ci = 0;
  // merge の処理
  while (ai < n) {
    if (bi < b.size() && (ci == c.size() || b[bi] <= c[ci])) {
      a[ai++] = b[bi++];
    } else {
      cnt += n / 2 - bi;
      a[ai++] = c[ci++];
    }
  }
  return cnt;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  ll N;
  cin >> N;
  vl A(N, 0);
  REP(i, N) cin >> A[i];
  auto B = A;
  sort(ALL(B), REV(ll));

  ll left = -1;
  ll right = N;

  while (right - left > 1) {
    ll mid = left + (right - left) / 2;
    ll x = B[mid];
    vl S(N, 0);
    REP(i, N) {
      if (i == 0)
        S[0] = (A[0] >= x) ? 1 : -1;
      else
        S[i] = S[i - 1] + ((A[i] >= x) ? 1 : -1);
    }
    ll ans = merge_cnt(S);
    if (ans <= (N + 1) * N / 4)
      right = mid;
    else
      left = mid;
  }
  cout << B[right] << endl;
  return 0;
}

