			b[i] = (a[i]>=x?1:-1);
		V rui(n+1,0);
		REP(i,n)
			rui[i+1]=rui[i]+b[i];
		int diff = *min_element(ALL(rui));
		ll k = 0;
		REP(i,n){
			k += bit.sum(0, rui[i] - diff + 1);
			bit.add(rui[i] - diff, 1);
		}

		return 1LL * (n - 1) * n / 4 >= k;
	};
