		A[0]=0;//v[0]>=m?1:-1;
		for(i=1;i<=N;i++)A[i]=A[i-1]+(v[i-1]>=m?1:-1);
		return 2*merge_and_count(0,N+1)>=((long long)(N+1)*(N+0))/2;
	}));
