bool check(ll mid) {
  //二分探索の目標値。 #{ m[i] | x <= m[i]} = objective となる最大の x を探す
  const ll comb = (N + 1) * N / 2;
  const ll objective = (comb + 1) / 2;

  vector<ll> s(N + 1);
  s[0] = 0;

  for (int i = 0; i < N; i++) {
    ll inc = A[i] < mid ? -1 : 1;
    s[i + 1] = s[i] + inc;
  }

  BIT<ll> bit(2 * N + 3);

  ll invs = 0;
  for (int i = 0; i <= N; i++) {
    ll idx = s[i] + N + 1;
    invs += bit.sum(idx);
    bit.add(idx, 1);
  }

  return invs >= objective;
}


