void q_sort (vector<int> &a, int l, int r) {
    if (l + 1 >= r) {
        return;
    }
    int x = a[rand() % (r - l) + l];
    int i = l;
    int j = l;
    for (int k = l; k < r; k++) {
        if (a[k] == x) {
            swap(a[k], a[j]);
            j++;
        }
        if (a[k] < x) {
            swap(a[i], a[k]);
            if (i != j) {
                swap(a[k], a[j]);
            }
            i++;
            j++;
        }
    }
    if (f < i) {
        q_sort(a, l, i);
    } else {
        q_sort(a, j, r);
    }
}

