struct FCType {
        bool cached;
        bool ret;
};

FCType f_cache[100005];
BIT bitree(300005, 0LL);

bool f(const V<ll> &alist, ll x, ll n, ll select_patterns, ll border)
{
        if (f_cache[x].cached) return f_cache[x].ret;

        V<int> binlist;
        rep (i, n) {
                int b = ((x <= alist[i]) ? 1 : -1);
                binlist.pb(b);
        }

        V<int> binsumlist;
        binsumlist.pb(0);
        int binsum = 0;
        rep (i, n) {
                binsum += binlist[i];
                binsumlist.pb(binsum);
        }

        bitree.init(0LL);

        ll sum = 0LL;
        rep (i, n+1) {
                // min(binsumlist[i]) == -n
                // BIT is 1-origin
                ll tree_idx = binsumlist[i] + n + 1LL;
                sum += bitree.sum(tree_idx);
                bitree.add(tree_idx, 1LL);
        }

        f_cache[x].ret = (sum >= border);
        f_cache[x].cached = true;
        return f_cache[x].ret;

}

int _main()
{
        ll n;
        llin(n);

        V<ll> alist;
        llina(alist, n);

        V<ll> sorted_alist(alist);
        sort(sorted_alist);

        memset(f_cache, 0, sizeof(f_cache));

        ll select_patterns = (n * (n + 1LL)) / 2LL;

        // count >= border --> true
        ll border;
        if (select_patterns & 1LL) border = select_patterns / 2LL + 1LL;
        else border = select_patterns / 2LL;

        int sorted_left = 0;
        int sorted_right = n-1;
        int sorted_idx = (sorted_left + sorted_right) / 2;
        ll ans = 0LL;

        for ( ; sorted_left <= sorted_right;
              sorted_idx = (sorted_left + sorted_right) / 2) {
                ll x = sorted_alist[sorted_idx];
                if (f(alist, x, n, select_patterns, border)) {
                        sorted_left = sorted_idx + 1;
                        ans = max(ans, x);
                }
                else {
                        sorted_right = sorted_idx - 1;
                }
        }

        cout << ans;

        return 0;
}

