int inv_merge(vector<int>& A, int i, int j, vector<int>& T) // [i, j)
{
    if (j - i <= 1) return 0;
    int cnt = 0;
    int m = (i+j)/2;
    cnt += inv_merge(A, i, m, T);
    cnt += inv_merge(A, m, j, T);
    copy(&A[i], &A[j], &T[i]);
    int a = i, b = m, p = i;
