struct BIT {
	ll M;
	std::vector<ll> bit;
	BIT(ll n) {
		init(n);
	}
	void init(ll n) {
		M = n;
		bit.resize(M + 1);
		fill(bit.begin(), bit.end(), 0);
	}
	ll sum(ll i) {
		ll s = 0;
		while (i > 0) {
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}
