using namespace std;

// merge [left, mid) and [mid, right)
template <typename T>
long long merge(std::vector<T> &A, std::size_t left, std::size_t mid, std::size_t right) {
    std::vector<T> L(mid - left), R(right - mid);
    for(std::size_t i = 0; i < L.size(); ++i) L[i] = A[left + i];
    for(std::size_t j = 0; j < R.size(); ++j) R[j] = A[mid + j];

    long long inversion = 0;
    std::size_t pos = left;
    std::size_t posL = 0, posR = 0;

    while(pos < right) {
        if(posL == L.size() || posR == R.size()) break;
        if(L[posL] > R[posR]) {
            inversion += L.size() - posL;
            A[pos++] = R[posR++];
        } else {
            A[pos++] = L[posL++];
        }
    }
    if(posL == L.size()) {
        while(posR < R.size()) A[pos++] = R[posR++];
    } else {
        while(posL < L.size()) A[pos++] = L[posL++];
    }

    return inversion;
}

template <typename T>
long long inversion_number(std::vector<T> &A, std::size_t left, std::size_t right) {
    if(right - left < 2) return 0;
    int mid = (left + right) / 2;  // divide
    long long inversion          // conquer
        = inversion_number<T>(A, left, mid) + inversion_number<T>(A, mid, right);
    inversion += merge<T>(A, left, mid, right);  // merge
    return inversion;
}


