// k以下が半分以上ある数列の個数
ll count(int k) {
	vector<int> _a(N + 1, 0);
	for (int i = 1; i <= N; ++i)
		_a[i] = a[i - 1] <= k ? 1 : -1;
	for (int i = 1; i <= N; ++i)
		_a[i] += _a[i - 1];
	ll inv_num = inversion_number(_a);
	return (ll)N * (N + 1LL) / 2 - inv_num;
}

