// Binary Indexed Tree モジュール (0-indexed)
template<typename T>
class BIT {
private:
    vector<T> val;
public:
    ll n;

    BIT(ll _n) : val(_n + 1, 0), n(_n) {}

    BIT(vector<T> arr) : val(arr.size() + 1, 0), n(arr.size()) {
        rep(i, n) add(i, arr[i]);
    }

    // a[i] に v を足す O(logN)
    void add(const ll _i, const T _v) {
        for (ll i = _i + 1; i <= n; i += i & (-i)) {
            val[i] += _v;
        }
    }

    // [0, _i) の和を求める O(logN)
    T get(ll i) const {
        T ans = 0;
        for (; i > 0; i ^= i & (-i)) {
            ans += val[i];
        }
        return ans;
    }

    // [l, r) の和を求める o(N)
    T sum(const ll l, const ll r) {
        return get(r) - get(l);
    }
};

size_t inversion(vector<ll> &x0) {

    vector<ll> x = x0;
    const int n = x0.size();

    // 座圧
    vector<ll> unq = x;
    sort(unq.begin(), unq.end());
    unq.erase(unique(unq.begin(), unq.end()), unq.end());
    map<ll, int> sahz;
    for (size_t i = 0; i < unq.size(); i++) sahz[unq[i]] = i;
    for (size_t i = 0; i < x.size(); i++) x[i] = sahz[x[i]];

    // BITで転倒数を求める
    size_t ans = 0;
    BIT<int> bit(n);
    for (int i = 0; i < n; i++) {
        ans += bit.sum(x[i] + 1, n);
        bit.add(x[i], 1);
    }

    return ans;

}


