struct node
{
    int l, r, sum;
} tree[N * 16 + 100];

void push(int num)
{
    tree[num].sum = tree[2 * num].sum + tree[2 * num + 1].sum;
}

void build(int left, int right, int num)
{
    tree[num].l = left;
    tree[num].r = right;
    if (left == right)
    {
        tree[num].sum = 0;
        return;
    }
    build(left, (left + right) / 2, num * 2);
    build((left + right) / 2 + 1, right, 2 * num + 1);
    push(num);
}

void up(int now, int x)
{

    if (tree[now].l == x && tree[now].r == x)
    {
        tree[now].sum++;
        return;
    }
    int mid = (tree[now].l + tree[now].r) / 2;
    if (x <= mid)
        up(2 * now, x);
    else if (x > mid)
        up(2 * now + 1, x);
    tree[now].sum++;
    //cout << tree[now].l << " " << tree[now].r << " " << tree[now].sum << endl;
}

int find(int now, int left, int right)
{

    if (tree[now].l >= left && tree[now].r <= right)
    {

        return tree[now].sum;
    }
    int mid = (tree[now].l + tree[now].r) / 2;
    //
    if (right <= mid)
        return find(2 * now, left, right);
    else if (left > mid)
        return find(2 * now + 1, left, right);
    else
    {
        return find(2 * now, left, mid) + find(2 * now + 1, mid + 1, right);
    }
}

bool check(int x)
{
