    build(1, N, 1);
    long long ans = 0;

    for (int i = 0; i <= n; i++)
    {
        ans += find(1, 1, sum[i] - 1);
        up(1, sum[i]);
    }
    //cout << x << " " << ans << endl;
    return ans >= 1ll * n * (n + 1) / 4+1;
}

