struct item
{
	int key, prior, sz;
	item *l, *r;
	item() {}
	item(int key) : key(key), prior(rand()), l(NULL), r(NULL) {}
};
typedef item * pitem;
int sz(pitem t)
{
	return t ? t -> sz : 0;
}
void up_sz(pitem t)
{
	if(t)
		t->sz = sz(t->l) + 1 + sz(t->r);
}
void merge(pitem &t, pitem l, pitem r)
{
	if(!l || !r) t = l ? l : r;
	else if(r -> prior > l->prior)
		merge(r->l, l, r->l) ,t = r;
	else
		merge(l->r, l->r, r), t = l;
	up_sz(t);
}
void split(pitem t, pitem &l, pitem &r, int val)
{
	if(!t) l = r = NULL;
	else if(val > t->key)
		split(t->r, t->r, r, val), l = t;
	else
		split(t->l, l, t->l, val), r = t; 
	up_sz(t);
}
void erase(pitem t)
{
	if(t)
	{
		erase(t->l);
		erase(t->r);
		delete t;
	}
}
