    void add (size_t i, long long x);
    long long sum(size_t i) const;
};

binary_indexed_tree::binary_indexed_tree(size_t n) {
    size = n;
    a = new long long[n]();
}

binary_indexed_tree::~binary_indexed_tree() {
    delete [] a;
}

void binary_indexed_tree::add(size_t i, long long x) {
    for (int j = i; j < size; j |= j + 1) {
        a[j] += x;
    }
}

long long binary_indexed_tree::sum(size_t i) const {
    long long result = 0;
    for (int j = i - 1; j >= 0; j = (j & (j + 1)) - 1) {
        result += a[j];
    }
    return result;
}

template <class Iterator>
unsigned long long inversion_number(Iterator first, Iterator last) {
    using T = typename iterator_traits<Iterator>::value_type;
    size_t size = distance(first, last);
    pair<T, int> *a = new pair<T, int>[size];
    for (int i = 0; i < size; ++i) {
        a[i] = pair<T, int>(*(first + i), i);
    }
    sort(a, a + size);
    int *b = new int[size];
    for (int i = 0; i < size; ++i) {
        b[a[i].second] = i;
    }
    unsigned long long result = 0;
    binary_indexed_tree bit(size);
    for (int *it = b + size - 1; it >= b; --it) {
        result += bit.sum(*it);
        bit.add(*it, 1);
    }
    delete [] a;
    delete [] b;
    return result;
}

template <class Pred>
ll partition_point_ll(ll first, ll last, Pred p) {
    ll count = last - first;
    while (count > 0) {
        ll step = count / 2;
        ll mid = first + step;
        if (p(mid)) {
            first = mid + 1;
            count -= step + 1;
        } else {
            count = step;
        }
    }
    return first;
}



const int A_MAX = 1000000000;

ll solve(const vector<int> &a) {
    ll N = a.size();
    function<bool(int)> f = [&](int x) {
        vector<int> S(N + 1);
        S[0] = 0;
        REP(i, N) {
            if (a[i] >= x) {
                S[i + 1] = S[i] + 1;
            } else {
                S[i + 1] = S[i] - 1;
            }
        }
        ll M = (ll)N * (N + 1) / 2;
        ll C = M - inversion_number(all(S));
        return C >= (M + 1) / 2;
    };
    return partition_point_ll(0, A_MAX + 1, f) - 1;
}

