    cin >> n;
    vector<long> a(n);
    for (auto &ai:a)
        cin >> ai;
    map<long, int> zip;
    vector<long> unzip;
    int k = compress(a, zip, unzip);
    int l = -1, r = k-1;
    while (r - l > 1) {
        int m = (l + r + 1) / 2,
            med = unzip[m];
        int rui = n;
        BIT<int> bit(2*n+1);
        bit.add(n, 1);
        long score = 0;
        // cerr << med << '\n' << rui;
        for (auto &ai:a) {
            if (ai > med) rui--;
            else rui++;
            bit.add(rui, 1);
            score += bit.sum(rui);
            // cerr << ' ' << rui;
        }
        // cerr << '\n' << score << '\n' << '\n';
        if (score >= (n * (n+1) / 2) / 2 + 1) r = m;
        else l = m;
    }
    cout << unzip[r] << '\n';
    return 0;
}

