template<typename Monoid>
struct SegmentTree{
    using F = function<Monoid(Monoid, Monoid)>;

    int sz;
    vector<Monoid> seg;

    const F f;      // モノイドに対して二項演算を行う関数オブジェクト
    const Monoid M1;

    SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1){
        sz = 1;
        while(sz < n)   sz <<= 1;
        seg.assign(2 * sz, M1);
    }

    void set(int k, const Monoid &x){
        seg[k + sz] = x;
    }

    void build(){
        for(int k = sz - 1; k > 0; --k){
            seg[k] = f(seg[k << 1], seg[k << 1 | 1]);
        }
    }

    void update(int k, const Monoid &x){
        k += sz;
        seg[k] = x;
        while(k >>= 1){
            seg[k] = f(seg[k << 1], seg[k << 1 | 1]);
        }
    }

    Monoid query(int a, int b){
        Monoid L = M1, R = M1;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1){
            if(a & 1)   L = f(L, seg[a++]);
            if(b & 1)   R = f(seg[--b], R);
        }
        return f(L, R);
    }

    Monoid operator[](const int &k) const{
        return seg[k + sz];
    }
};

bool check(int x){
    vector<P> sum(n + 1);
    sum[0] = P(0, 0);
    for(int i = 0; i < n; ++i){
        sum[i + 1].first = sum[i].first + ((a[i] >= x) ? 1 : -1);
        sum[i + 1].second = i + 1;
    }
    sort(sum.begin(), sum.end(), greater<P>());
    SegmentTree<int> seg(n + 1, [](int a, int b){return a + b;}, 0);
    ll cnt = 0;
    for(int i = 0; i <= n; ++i){
        int pos = sum[i].second;
        cnt += seg.query(pos, n + 1);
        seg.update(pos, seg[pos] + 1);
    }
    ll comparision = (ll)n * (n + 1) / 2;
    comparision = (comparision + 1) / 2;
    return cnt < comparision;
}

