struct BIT{
    public:
    vector<lint> bit;
    lint n;
    BIT(lint _n){
        n=_n;
        bit.resize(n+1,0);
    }
    lint sum(lint i){
        if(!i)return 0;
        return bit[i]+sum(i-(i&-i));
    }
    void add(lint i,lint x){
        if(i>n)return;
        bit[i]+=x;
        add(i+(i&-i),x);
    }
    static lint inversion(vector<lint> v){
        lint tmp=min(v);
        rep(i,v.size())v[i]-=tmp-1;
        BIT b(max(v));
        lint ans = 0;
        rep(i,v.size()){
            ans+=i-b.sum(v[i]);
            b.add(v[i],1);
        }
        return ans;
    }
};
