vi32 merge(vi32 &v, int l, int r) {
  vi32 ret;
  if (l + 1 == r) {
    ret.push_back(v[l]);
    return ret;
  }
  vi32 a = merge(v, l, (l + r) / 2);
  vi32 b = merge(v, (l + r) / 2, r);
  int ai = 0, bi = 0;
  rep(i, r - l) {
    if (bi == b.size()) {
      ret.push_back(a[ai++]);
      cnt += bi;
    } else if (ai == a.size()) {
      ret.push_back(b[bi++]);
    } else {
      if (a[ai] < b[bi]) {
        ret.push_back(a[ai++]);
        cnt += bi;
      } else {
        ret.push_back(b[bi++]);
      }
    }
  }
  return ret;
}

bool check(int md) {
  vi32 v(n + 1);
  rep(i, n) {
    if (a[i] >= md) v[i] = 1;
    else v[i] = -1;
  }
  rep(i, n - 1) {
    v[i + 1] += v[i];
  }
  cnt = 0;
  merge(v, 0, n);
  i32 len = (i64) n * (n + 1) / 2;
  return (len + 2) / 2 <= len - cnt;
}

