template <typename _Ty>
class BIT {
private:
    size_t m_n;
    std::vector<_Ty> m_vec;

public:
    BIT(size_t num) : m_n(num), m_vec(m_n + 1) {}

    // i 番目の要素に a を足す
    void add(size_t i, const _Ty& a) {
        for (++i; i <= m_n; i += i & (-i)) {
            m_vec[i] += a;
        }
    }

    // 区間[0, i)の総和を求める
    _Ty sum(size_t i) const {
        _Ty res = 0;
        for (++i; i >= 1; i -= i & (-i)) {
            res += m_vec[i];
        }
        return res;
    }

    // 区間[i, j)の総和を求める
    _Ty sum(size_t i, size_t j) const {
        return sum(j) - sum(i);
    }

    size_t size() const noexcept {
        return m_n;
    }

    void assign(const _Ty& a) {
        std::fill(m_vec.begin(), m_vec.end(), a);
    }
};

ll N, M;

bool check(int x, const Vl& a) {
    static Vl S(N + 1);
    static BIT<ll> bit(N * 2 + 1);

    S.assign(N + 1, 0);
    bit.assign(0);

    for (int i = 0; i < N; ++i) {
        S[i + 1] = S[i] + ((a[i] >= x) ? 1 : -1);
    }

    ll cnt = 0;
    for (int j = 0; j <= N; ++j) {
        cnt += bit.sum(S[j] + N);
        bit.add(S[j] + N, 1);
    }

    if (cnt >= (M + 1) / 2) {
        return true;
    }
    else {
        return false;
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N;

    M = N * (N - 1) / 2 + N;

    Vl a(N);
    for (int i = 0; i < N; ++i) {
        cin >> a[i];
    }

    int left = 1, right = 1000000001;
    while (right - left > 1) {
        int mid = (left + right) / 2;
        if (check(mid, a)) {
            left = mid;
        }
        else {
            right = mid;
        }
    }

    cout << left << endl;

    return 0;
}

