int b[MAXN];
ll tot;

void insert(int x,int l,int r,int pos)
{
	t[x]++;
	if(l==r) return;
	int mid=(l+r)>>1;
	if(pos<=mid) insert(x<<1,l,mid,pos);
	else insert(x<<1|1,mid+1,r,pos);
}

int query(int x,int l,int r,int ql,int qr)
{
	if(ql<=l&&r<=qr) return t[x];
	int mid=(l+r)>>1,ret=0;
	if(ql<=mid) ret+=query(x<<1,l,mid,ql,qr);
	if(qr>mid) ret+=query(x<<1|1,mid+1,r,ql,qr);
	return ret;
}

bool check(int x)
{
	for(int i=1;i<=n;i++) b[i]=(a[i]>=x?1:-1);
	memset(t,0,sizeof t);
	ll S=0,Res=0;
	for(int i=1;i<=n;i++)
	{
		S+=b[i];
		Res+=query(1,1,OFFSET<<1,1,S+OFFSET);
		insert(1,1,OFFSET<<1,S+OFFSET);
	}
	return Res>=tot/2;
}

int main()
{
	scanf("%d",&n);tot=1ll*n*(n-1)/2;
	for(int i=1;i<=n;i++) scanf("%d",&a[i]);
	if(n==1) return printf("%d\n",a[1]),0;
	int L=1,R=1E9+10,Ans=0;
	while(L<=R)
	{
		int mid=(L+R)>>1;
		if(check(mid)) Ans=mid,L=mid+1;
		else R=mid-1;
	}
	assert(Ans);
	printf("%d\n",Ans);
}

