int inv_merge(vector<int>& A, vector<int>& T, int i, int j) // [i, j)
{
    if (j - i <= 1) return 0;
    int cnt = 0;
    int m = (i+j)/2;
    cnt += inv_merge(A, T, i, m);
    cnt += inv_merge(A, T, m, j);
    copy(&A[i], &A[j], &T[i]);
    int a = i, b = m, p = i;
    while (a < m && b < j) {
        if (T[a] <= T[b]) {
            A[p++] = T[a++];
        } else {
            A[p++] = T[b++];
            cnt += m - a;
        }
    }
    if (a < m) copy(&T[a], &T[m], &A[p]);
    if (b < j) copy(&T[b], &T[j], &A[p]);
    return cnt;
}

int inv(const vector<int>& A) // #{(Ai,Aj)|i<j&&Ai>Aj}
{
    vector<int> B(A), T(A);
    return inv_merge(B, T, 0, B.size());
}

bool ge(const vector<int>& A, int n) // median >= n
{
    vector<int> B(A.size());
    B[0] = A[0] >= n ? 1 : -1;
    for (int i = 1; i < A.size(); i++) {
        B[i] = (A[i] >= n ? 1 : -1) + B[i-1];
    }
    int solo = count_if(A.begin(), A.end(), [=](int x) { return x < n; });
    int total = A.size()*(A.size()+1)/2;
    return inv(B) + solo <= total / 2;
}

