long long solve() {
  long long l = 0, r = ls.size() - 1, now = ls[0];
  while(r - l > 0) {
    if(r - l == 1) {
      if(isans(ls[r]))
        now = ls[r];
      else
        now = ls[l];
      break;
    }
    else {
      now = ls[(r + l) / 2];
      if(isans(now))
        l = (r + l) / 2;
      else
        r = (r + l) / 2;
    }
  }
  return now;
}
// yes 1,no 0
bool isans(long long now) {
  BIT<long long> bits = BIT<long long>(1 + n),
                 inv = BIT<long long>(3 * n);
  long long ans = 0;
  // calculate cumlative number(1 or -1 progression)
  for(int i = 0; i <= n; ++i) {
    if(i == 0 || a[i - 1] >= now)
      bits.add(i + 1, 1);
    else
      bits.add(i + 1, -1);
  }
  // avoid runtime error
  bits.add(1, n);
  // calculate inversion number
  for(int i = 1; i <= n + 1; ++i) {
    ans += inv.calcsum(bits.calcsum(i));
    inv.add(bits.calcsum(i), 1);
  }
  // cout << now << " " << ans << " " << req << endl;
  if(ans >= req)
    return 1;
  else
    return 0;
}

