class BinaryIndexedTree{//BIT 加算と区間和 内部1-indexed
  public:
  ll pnum;
  V elements;
  BinaryIndexedTree(ll n){pnum=n+1;elements=V(pnum,0);}
  void add(ll pos,ll val){ //0-indexedで呼び出す
	++pos;
    for(ll x=pos;x<pnum;x+=x&-x)elements[x]+=val;
  }
  ll sum(ll pos){ //1-indexedで呼び出される
    ll ret=0;
    for(ll x=pos;x>0;x-=x&-x)ret+=elements[x];
    return ret;
  }
  ll sum(ll st,ll en){
    return sum(en)-sum(st);//0-indexedの半開区間 [0,3)なら0,1,2
  }
};

