struct AddT {
	vector<UL> V;
	UL N;
	AddT(UL sz) {
		N = 1; while (N < sz) N <<= 1;
		V.resize(N * 2 - 1);
	}
	void add(UL p) {
		p = p + N - 1;
		V[p]++;
		while (p != 0) { p = (p - 1) >> 1; V[p]++; }
	}
	UL query(UL r, UL a = -1, UL b = -1, UL p = -1) {
		if (p == -1) { a = 0; b = N; p = 0; }
		if (b <= r) return V[p];
		if (r <= a) return 0;
		return query(r, a, (a + b) >> 1, (p << 1) + 1) +
			query(r, (a + b) >> 1, b, (p << 1) + 2);
	}
};

struct Problem {

	UL N;
	vector<UL> A;

	ULL Solve2(UL K) {
		vector<int> S(N + 1);
		rep(i, N) if (A[i] > K) S[i + 1] = -1; else S[i + 1] = 1;
		rep(i, N) S[i + 1] += S[i];
		ULL ans = 0;
		AddT Q(2 * N + 1);
		rep(i, N + 1) {
			int s = S[i] + N + 1;
			ans += Q.query(s);
			Q.add(s);
		}
		return ans;
	}

	void Solve() {
		cin >> N;
		ULL NN = (ULL)N * (N + 1) / 2;
		A.resize(N); rep(i, N) cin >> A[i];
		UL l = 0, r = 1000000001;
		while (l + 1 < r) {
			UL m = (l + r) >> 1;
			if (Solve2(m) <= NN / 2) l = m;
			else r = m;
		}
		cout << r << endl;
	}

	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
