void sort_uniq(vector<ll> &v ){
  sort(v.begin(),v.end());
  v.erase(unique(v.begin(),v.end()), v.end());
}

vector<ll> Cumulative_sum(const vector<ll> &v, int x){
  int i;
  vector<ll> ret(N+1);
  ret[0] = 0;
  REP(i,N){
    ret[i+1] = ret[i];
    if(v[i] >= x) ret[i+1] += 1;
    else ret[i+1] -= 1;
  }
  return ret;
}

class BIT{
  public:
  vector<ll> bit; 
  BIT(const vector<ll> &v){
    //bit[0]は，無視
    //BITの外側では0index
    bit.resize(v.size()+1,0);
  }

  //iにwをたす
  void add(int i, int w){
    for(int x = i+1; x<=bit.size(); x += x&-x) bit[x] += w;
  }

  ll sum(int i){
    ll ret = 0;
    for(int x = i+1; x>0 ; x -= x&-x) ret+=bit[x];
    return ret;
  }
};

ll n_fall(vector<ll> S){
  int i;
  map<ll,int> f;
  vector<ll> v = S;
  sort_uniq(v);
  REP(i,v.size()){
    if(!f.count(v[i])) f[v[i]] = i;
  }
  BIT b = BIT(v);
  ll ret = 0;
  REP(i,S.size()){
    ll t_i = b.sum(f[S[i]]);
    b.add(f[S[i]],1);
    ret += i - t_i;
  }
  return ret;
}

