void merge_sort(int s,int t){
	if(s>=t) return;
	int mid=(s+t)>>1;
	merge_sort(s,mid);
	merge_sort(mid+1,t);
	int i=s,j=mid+1,k=s;
	while(i<=mid&&j<=t){
		if(a[i]>a[j]){
			tot+=mid-i;
			b[k]=a[j];
			j++;k++;
		}
		else {
			b[k]=a[i];
