        node.resize(2 * width - 1, unit);
        for (size_t i = 0; i < elems.size(); i++) {
            node[i + width - 1] = elems[i];
        }
        for (size_t i = width - 2; i != numeric_limits<size_t>::max(); i--) {
            node[i] = op(node[2 * i + 1], node[2 * i + 2]);
        }
    }
    void update(ll idx, Monoid elem) {
        idx += width - 1;
        node[idx] = elem;
        while (idx >= 1) {
            idx = (idx - 1) / 2;
            node[idx] = op(node[2 * idx + 1], node[2 * idx + 2]);
        }
    }
    Monoid query_core(ll a, ll b, ll root, ll left, ll right) const {
        assert(0 <= a && b <= width);
        if (right <= a || b <= left) {
            return unit;
        }
        if (a <= left && right <= b) {
            return node[root];
        }
        ll mid = (left + right) / 2;
        Monoid ans_l = query_core(a, b, 2 * root + 1, left, mid);
        Monoid ans_r = query_core(a, b, 2 * root + 2, mid, right);
        return op(ans_l, ans_r);
    }
    Monoid query(ll a, ll b) const {
        assert(0 <= a && b <= width);
        return query_core(a, b, 0, 0, width);
    }
    Monoid operator[](size_t idx) { return query(idx, idx + 1); }
};

int main() {
    ll N;
    cin >> N;
    vector<ll> As(N);
    rep(i,0,N) {
        cin >> As[i];
    }
    ll left = 0;
    ll right = *max_element(As.begin(), As.end());
    auto count_median_leq = [N, &As](ll k) {
        struct SumVal {
            ll idx;
            ll sum;
        };
        vector<SumVal> sums(N+1);
        rep(n,1,N+1) {
            sums[n].idx = n;
            sums[n].sum = sums[n-1].sum;
            if (As[n-1] <= k) {
                sums[n].sum++;
            } else {
                sums[n].sum--;
            }
        }
        sort(sums.begin(), sums.end(), [](SumVal& lhs, SumVal& rhs){
            return lhs.sum < rhs.sum || (lhs.sum == rhs.sum && lhs.idx > rhs.idx);
        });
        SegmentTree<ll> tree(vector<ll>(N+1), [](ll lhs, ll rhs){
            return lhs + rhs;
        }, 0);
        ll cnt = 0;
        rrep(i,N+1,0) {
            cnt += tree.query(sums[i].idx, N+1);
            tree.update(sums[i].idx, 1);
        }
        return cnt;
    };
    ll range_cnt = (N * (N+1)) / 2;
    while (right - left >= 2) {
        ll mid = (left + right) / 2;
        ll cnt = count_median_leq(mid);
        if (cnt >= range_cnt / 2 + 1) {
            right = mid;
        } else {
            left = mid;
        }
    }
    cout << right << endl;
}

