    p_ii sum[N+1]; sum[0] = make_pair(0,0);
    rep(i,N) {
      int tmp = sum[i].second;
      tmp += (a[i]>=m) ? 1 : -1;
      sum[i+1] = make_pair(i+1, tmp);
    }
    sort(sum, sum+N+1, [](const p_ii &x, const p_ii &y) {return x.second<y.second;});
    rep(i,N+1) sum[i].second = i;
    sort(sum, sum+N+1, [](const p_ii &x, const p_ii &y) {return x.first<y.first;});

    SegTree tree(N+1);
    ll count = 0;
    rep(i,N+1) {
      count += tree.query(0,sum[i].second);
      tree.update(sum[i].second,1);
    }
    // rep(i,N+1) cout << sum[i].second << "-"; cout << endl;
    // cout << count << " " << l << " " << m << " " << r << endl; cout << endl;
    if (count>=(choice+1)/2) l = m;
