//配列の最大値を求める
long max_of_array(long *a){
  long m=0;
  for(int i=0;i<n;i++){
    if(a[i] > m) m = a[i];
  }
  return m;
}

//2つのパーツをマージしてソートし，その際計算したS_l <= S_rを満たすものの数を返す
long long merge(int *s, int left, int mid, int right){
  int ne = right - left + 1;
  int tmp[ne], i_tmp=0, i_left=left, i_right=mid+1;
  long count = 0;
  for(; i_left <= mid && i_right <= right; i_tmp++){
    if(s[i_left] > s[i_right]){
      tmp[i_tmp] = s[i_left];
      i_left++;
    }else{
      tmp[i_tmp] = s[i_right];
      count+=mid-i_left+1; //countに左側のリストに残っている要素数を足していくとS_l <= S_rを満たすものの個数になる
      i_right++;
    }
  }
  for(; i_left <= mid; i_tmp++, i_left++) tmp[i_tmp] = s[i_left];
  for(; i_right <= right; i_tmp++, i_right++) tmp[i_tmp] = s[i_right];

  for(int i=left;i<=right;i++) s[i] = tmp[i-left];

  return count;
}

//(l,r)のうち，S_l <= S_r を満たすものの数を求める．再帰的に実装した．
long long calc_combination(int *s, int left, int right){
  if(left < right) {
    int mid = (right + left) / 2;
    return calc_combination(s, left, mid) 
      + calc_combination(s, mid+1, right)
      + merge(s,left,mid,right);
  }else{
    return 0;
  }
}

int sgn(long x, long y){
  return x < y ? -1 : 1;
}

bool check(long c){
  int s[n]; //累積和の配列
  long s1 = 0;
  s[0]=sgn(a[0],c);
  for(int i=1;i<n;i++){
    s[i] = s[i-1] + sgn(a[i],c);
    s1 += sgn(a[i],c) < 0 ? 0 : 1; //(#1)
    //(#1)公式解説pdfの方法だと，l=rの場合が考慮されていないので，ACにならない．m_l,rの要素数が１の時も考慮しなければならない．
  }
  long long cb = calc_combination(s,0,n-1) + s1;
  return cb >= n*((long long)n+1)/4;
}

