struct BIT {
    vector<ll> bit;
    int N;

    BIT(int N) : bit(vector<ll>(N + 1, 0)), N(N) {}

    // return sum in [0, `i`] in log(n)
    ll sum(int i) {
        if (!i) return 0;
        return bit[i] + sum(i - (i & -i));
    }

    // add `x` at `i`
    void add(int i, ll x) {
        if (i > N) return;
        bit[i] += x;
        add(i + (i & -i), x);
    }
};

int main() {
    int n;
    cin >> n;
    vector<ll> a(n);
    rep(i, n) cin >> a[i];

    ll l = 1, r = 1e9 + 7;
    ll threshold = n * (n + 1) / 2;
    threshold = (threshold + 1) / 2;
    while (r - l > 1) {
        ll mid = l + (r - l) / 2;
        ll score = 0;
        BIT fwt(20020);

        // to prevent a negative index
        ll pref_sum = 1e5;
        // the pref_sum of an empty array is always 0
        fwt.add(pref_sum, 1);

        rep(i, n) {
            pref_sum += (mid <= a[i] ? 1 : -1);
            score += fwt.sum(pref_sum);
            fwt.add(pref_sum, 1);
        }
        if (score >= threshold) {
            l = mid;
        } else {
            r = mid;
        }
    }
    cout << l << endl;
}

