// a<x    num(a)<=N/2
bool check(int x){
    int K=(N*(N+1)/2)/2;

    for(int i=0;i<N;i++){
        S[i+1]=S[i];
        if(A[i]<x)S[i+1]++;
        else S[i+1]--;
    }///S[1]....S[n]に, 1, -1変換した上での累積和

    vector<int>vs;
    rep(i,N+1)vs.push_back(S[i]);
    sort(all(vs));vs.erase(unique(all(vs)),vs.end());
    rep(i,N+1)S[i]=(int)(lower_bound(all(vs),S[i])-vs.begin());

    //// 各累積和の値について、それがソート後に何番目にあるかに変換

    int cnt=0;
    BinaryIndexedTree bit(N+114);

    rep(i,N){
