class BinaryIndexedTree {
 public:
  static const int MAX_N = (int)(2e5 + 100);

  ll arr[MAX_N];
  int n;

  BinaryIndexedTree(int n) {
    this->n = n;
    init();
  }

  void init() {
    for (int i = 0; i < n; ++i) arr[i] = 0LL;
  }

  ll sum(int i) {
    ll s = 0LL;
    while (i > 0) {
      s += arr[i];
      i -= i & -i;
    }
    return s;
  }

  void add(int i, ll x) {
    while (i <= n) {
      arr[i] += x;
      i += i & -i;
    }
  }
};
