template<class T>
struct BIT {
    ll n;
    vector<T> bit;

    // bit_i is 1-indexed
    // 各要素の初期値は 0
    BIT(ll num) : bit(num+1, 0) { n = num; }

    // a_i += w
    void add(ll i, T w) {
        for (ll x = i; x <= n; x += x & -x) {
            bit[x] += w;
        }
    }
    // [1, i] の和を計算.
    T sum(ll i) {
        T ret = 0;
        for (ll x = i; x > 0; x -= x & -x) {
            ret += bit[x];
        }
        return ret;
    }

    // [a,b)の和を計算
    T sum(ll a, ll b) {
        return sum(b-1) - sum(a-1);

    }

    // bit[i] の最大値を w に更新
    void add_max(ll i,T w) {
        for (ll x = i; x <= n; x += x & -x) {
            chmax(bit[x],w);
        }
    }

    // [1,i]の最大値を計算.
    T max(ll i) {
        T ret=0;
        for (ll x = i; x > 0; x -= x & -x) {
            chmax(ret,bit[x]);
        }
        return ret;
    }


    // v1 + v2 + ⋯ + vx >= w となる最小の x を求める
    // w 番目に小さい要素を見つけるset
    ll lowerBound(ll w) {
        if(w <= 0) return 0;
        ll x = 0;
        ll k = 1;
        while(k * 2 <= n) k*=2;
        for(; k > 0; k /= 2){
            if(x + k <= n && bit[x + k] < w){
                w -= bit[x + k];
                x += k;
            }
        }
        return x + 1;
    }

    // debug 
    void print() {
        for (ll i = 1; i < n+1 ; i++) {
            cout<<sum(i,i+1)<<", ";
        }
        cout<<endl;
    }

};






