    sort(a_aux_cumsum_ind, a_aux_cumsum_ind + N + 1);
    reverse(a_aux_cumsum_ind, a_aux_cumsum_ind + N + 1);

    SqrtDecomposition sq(N + 1);
    long long less_no = 0;
    for(int i = 0; i < N + 1; i++){
      int ind = a_aux_cumsum_ind[i].second;
      less_no += sq.getSum(0, ind);
      sq.add(ind, 1);
    }
    //cout << sorted_a[mid] << " " << less_no << endl;
    if(less_no < ((long long) N * (long long) (N + 1) / 2) / 2 + 1){
      left = mid;
    } else {
