		CoordComp() {}
		template<class T> CoordComp(const vector<T> &vals) : i2v(vals.size()) {
			copy(begin(vals), end(vals), begin(i2v));
			sort(begin(i2v), end(i2v));
			UNIQUE(i2v);
			int n = i2v.size();
			rep(i, n) v2i[i2v[i]] = i;
		}
