namespace FenwickTree {
	int f[2*N+5];
	int lowbit(int x) {
		return x&-x;
	}

	void update(int x, int k) {
		while(x <= 2*n) {
			f[x] += k;
			x += lowbit(x);
		}
	}

	int query(int x) {
		int ret = 0;
		while(x) {
			ret += f[x];
			x -= lowbit(x);
		}
		return ret;
	}
}

