	int w, id;
}b[N+5];

bool check(int x) {
	//show(a[x]);
	int w = a[x];
	long long res = 0;
	memset(FenwickTree::f, 0, sizeof FenwickTree::f);
	for(int i = 0; i <= n; i++)
		sum[i] = a[i] >= w ? 1 : -1;
	for(int i = 1; i <= n; i++) {
		sum[i] += sum[i-1];
	}
	for(int i = 1; i <= n; i++) {
		FenwickTree::update(sum[i]+n+1, 1);
		res += i-FenwickTree::query(sum[i]+n+1);
	}
	return res < total/2+1;
}

