ll merge_count(vector<int> &a){
	int n=a.size();
	if(n<=1) return 0;

	ll cnt=0;
	vector<int> b(a.begin(),a.begin()+n/2);
	vector<int> c(a.begin()+n/2,a.end());

	cnt+=merge_count(b);
	cnt+=merge_count(c);
