int max_of_array(int *a){
  int m=0;
  for(int i=0;i<n;i++){
    if(a[i] > m) m = a[i];
  }
  return m;
}

//2つのパーツをマージしてソートし，その際計算したS_l <= S_rを満たすものの数を返す
int merge(int *s, int left, int mid, int right){
  int ne = right - left + 1;
  int tmp[ne], count = 0, i_tmp=0, i_left=left, i_right=mid+1;
  for(; i_left <= mid && i_right <= right; i_tmp++){
    if(s[i_left] <= s[i_right]){
      tmp[i_tmp] = s[i_left];
      count++;
      i_left++;
    }else{
      tmp[i_tmp] = s[i_right];
      i_right++;
    }
  }
  for(; i_left <= mid; i_tmp++, i_left++) tmp[i_tmp] = s[i_left];
  for(; i_right <= right; i_tmp++, i_right++) tmp[i_tmp] = s[i_right]; 

  for(int i=left;i<=right;i++){
    s[i] = tmp[i-left];
  }

  return count;
}

//(l,r)のうち，S_l <= S_r を満たすものの数を求める．再帰的に実装した．
int calc_combination(int *s, int left, int right){
  if(left < right) {
    int mid = (right + left) / 2;
    return calc_combination(s, left, mid) 
      + calc_combination(s, mid+1, right)
      + merge(s,left,mid,right);
  }else{
    return 0;
  }
}

