    seg[k] = seg[k*2+1] + seg[k*2+2];
  }
}
ll query(ll a, ll b, ll l, ll r, ll k){
  if(r<=a || b <= l) return 0;
  if(a<=l && r<=b) return seg[k];
  else{
    ll le = query(a, b, l, (l+r)/2, k*2+1);
    ll ri = query(a, b, (l+r)/2, r, k*2+2);
    return le + ri;
  }
}
