const bool LEFT = false;
const bool RIGHT = true;
bool judgeLR(int x);// 左に属するか右に属するかを判断する関数。下で定義する。

int nibutanL(int size) {// LEFTグループに属するうち最も右側のindexを得る
	int L = -1;
	int R = size;
	while (abs(R - L) > 1) {
		int mid = (L + R) / 2;
		if (judgeLR(mid) == RIGHT) R = mid;
		else L = mid;
	}
	return L;
}
int nibutanR(int size) {//RIGHTグループに属するうち最も左側のindexを得る
	return nibutanL(size) + 1;
}

const int N_MAX = 200000;
ll bit[N_MAX];

int sum(int i) {
	int s = 0;
	while (i > 0) {
		s += bit[i];
		i -= i & -i;
	}
	return s;
}
void add(int i, int x) {
	while (i <= N_MAX - 1) {
		bit[i] += x;
		i += i & -i;
	}
}

bool judgeLR(int x) {
	ll M = (ll)N * (ll)(N + 1) / 2;
	M = (M + 1) / 2;

	int offset = 1;
	for (int i = 0; i < N; i++) {
		if (A[i] >= x) {
			B[i] = 1;
		}
		else {
			B[i] = -1;
		}
		if (i > 0) {
			B[i] += B[i - 1];
		}

		offset = min(offset, B[i]);
	}

	for (int i = 0; i < N_MAX; i++) {
		bit[i] = 0;
	}

	ll ans = 0;
	add(0 - (offset - 1), 1);
	for (int i = 0; i < N; i++) {
		B[i] -= (offset - 1);
		ans += (ll)sum(B[i]);
		add(B[i], 1);
	}

	if (ans >= M) { return LEFT; }
	else { return RIGHT; }
}

