typedef long long ll;

struct BIT {
    vector<ll> x;
    BIT(ll n) : x(n, 0) {}
    ll sum(ll i){
        ll s = 0;
        while(i > 0){
            s += x.at(i - 1);
            i -= i & (-i);
        }
        return s;
    }
    void add(ll i, ll v){
        i += 1;
        while(i <= x.size()){
            x.at(i - 1) += v;
            i += i & (-i);
        }
    }
};

ll calc_inversion_number(const vector<ll>& x){
    ll maxv = *max_element(x.begin(), x.end());
    ll minv = *min_element(x.begin(), x.end());
    ll n = maxv - minv + 1;
    BIT bit(n);
    ll ret = 0;
    for(int i = 0; i < x.size(); ++i){
        ret += i - bit.sum(x.at(i) - minv + 1);
        bit.add(x.at(i) - minv, 1);
    }
    return ret;
}

