    // for(ll bi : b){ cerr << bi << " "; }
    // cerr << endl;

    vector<ll> c(n + 1, 0);
    for(int i = 1; i <= n; ++i){
        c.at(i) = c.at(i - 1) + b.at(i - 1);
    }

    // cerr << "c = ";
    // for(ll ci : c){ cerr << ci << " "; }
    // cerr << endl;

