        sum = num = cnt = 0;
        BIT<int> BT(2 * n + 10);
        const int upper = n;
        BT.add(upper);
        REP(i, n){
            num = (a[i] >= mid ? 1 : -1);
            sum += num;
            cnt += BT.sum(0, sum + upper + 1);
            BT.add(sum + upper);
        }
        return cnt < (n + 1) * n / 4;
    };
    while(abs(ok - ng) > 1){
        int mid = (ok + ng) / 2;
        if(judge(mid)) ng = mid;
        else ok = mid;
    }
    print(ok);
}

