using namespace std;
const int N = 2e5 + 10;
int n, a[N + 100], sum[N + 100];
long long cnt;
struct node
{
    int l, r, sum;
} tree[N * 8 + 10];

void push(int num)
{
    tree[num].sum = tree[2 * num].sum + tree[2 * num + 1].sum;
}

void build(int left, int right, int num)
{
    tree[num].l = left;
    tree[num].r = right;
    if (left == right)
    {
        tree[num].sum = 0;
        return;
    }
    build(left, (left + right) / 2, num * 2);
    build((left + right) / 2 + 1, right, 2 * num + 1);
}

void up(int now, int x)
{

    if (tree[now].l == x && tree[now].r == x)
    {
        tree[now].sum++;
        return;
    }
    int mid = (tree[now].l + tree[now].r) / 2;
    if (x <= mid)
        up(2 * now, x);
    else if (x > mid)
        up(2 * now + 1, x);
    tree[now].sum++;
    //cout << tree[now].l << " " << tree[now].r << " " << tree[now].sum << endl;
}

int find(int now, int left, int right)
{

    if (tree[now].l >= left && tree[now].r <= right)
    {

        return tree[now].sum;
    }
    int mid = (tree[now].l + tree[now].r) / 2;
    //
    if (right <= mid)
        return find(2 * now, left, right);
    else if (left > mid)
        return find(2 * now + 1, left, right);
    else
    {
        return find(2 * now, left, mid) + find(2 * now + 1, mid + 1, right);
    }
}

bool check(int x)
{
    sum[0] = 0;
    for (int i = 0; i <= 4 * N + 5; i++)
        tree[i].sum = 0;
    for (int i = 1; i <= n; i++)
    {
        if (a[i] > x)
            sum[i] = sum[i - 1] - 1;
        else
            sum[i] = sum[i - 1] + 1;
    }
    for (int i = 0; i <= n; i++)
        sum[i] += n + 1;
    build(1, N, 1);
    long long ans = 0;

    for (int i = 0; i <= n; i++)
    {
        ans += find(1, 1, sum[i] - 1);
        up(1, sum[i]);
    }
    //cout << x << " " << ans << endl;
    return ans >= cnt / 2 + 1;
}

int main()
{
    scanf("%d", &n);
    int l = 0;
    int r = 1e9 + 10;
    for (int i = 1; i <= n; i++)
    {
