ll Msort(int le, int ri)//计算中位数大于等于mid的[l, r]对数，具体过程类似逆序对
{
    if (le == ri)
        return (sum[le]-sum[le-1] >= 0);
    int mid = (le+ri)>>1;
    ll ret = 0;
    ret += Msort(le, mid);
    ret += Msort(mid+1, ri);
    int i = le, j = mid+1, k = le;
    while (i <= mid && j <= r){
        if (sum[i] <= sum[j]){
            tmp[k++] = sum[i++];
            ret += ri-j+1;
        }
        else
            tmp[k++] = sum[j++];
    }
    while (i <= mid)
        tmp[k++] = sum[i++];
    while (j <= r)
        tmp[k++] = sum[j++];
    for (int i = le; i <= ri; i++)
        sum[i] = tmp[i];
    return ret;
}

bool Check(int mid)
{
    sum[0] = 0;
    for (int i = 1; i <= n; i++){
        sum[i] = sum[i-1];
        if (a[i] >= mid) sum[i]++;
        else sum[i]--;
    }
    if (Msort(1, n) >= lim) return true;
    return false;
}

