template<typename T>
class BIT{
public:
    vector<T> bit;
    int size;
    BIT(int size):
        bit(vector<T>(size+1,0)),size(size){}

    T sum(int i){
        if(!i) return 0;
        return bit[i]+sum(i-(i&(-i)));
    }

    void add(int i,T x){
        if(i>size)return;
        bit[i]+=x;
        add(i+(i&(-i)),x); 
    }   
};

ll inversion(const vector<ll> &v){
    int N = v.size();
    vector<ll> w(N);
    REP(i,N) w[i]=v[i];
    sort(all(w));
    w.erase(unique(all(w)),w.end());
    vector<ll> v2(N);
    REP(i,N) {
        v2[i] = lower_bound(all(w),v[i]) - w.begin();
    }
    BIT<ll> bit(w.size()+1);
    ll res = 0;
    REP(i,N) {
        res += bit.sum(v2[i]+1);
        bit.add(v2[i]+1,1);
    }
    return res;
}

bool check(ll K, const vector<ll> &v){
    ll N = v.size();
    vector<ll> w(N+1,0);
    REP(i,N) w[i+1] = (v[i]>=K ? 1:-1);
    REP(i,N) w[i+1] += w[i];
    return 2*inversion(w) >= N*(N+1)/2;
}

