ll merge(int *sums, int l, int m, int r) {
  ll count = 0;
  int arr[r - l];
  int i = 0;
  int x = l, y = m;
  while (x <= m || y <= r) {
    if (y <= r && (x > m || sums[x] > sums[y])) {
      arr[i] = sums[y];
      y++;
    } else if (x <= m) {
      arr[i] = sums[x];
      x++;
      count++;
    }
    i++;
  }
  for (i = 0; l <= r; l++, i++) {
    sums[l] = arr[i];
  }
  return count;
}

ll msort(int *sums, int l, int r) {
  if (l == r) {
    return 0;
  }
  int m = l + (r - l) / 2;
  return msort(sums, l, m) + msort(sums, m + 1, r) + merge(sums, l, m + 1, r);
}

