  int b[200001];
public:
  BIT(int n){
    bit_size = n;
  }
  void reset(){
    memset(b, 0, bit_size * sizeof(*b));
  }
  int sum(int x){
    int ret = 0;
    for ( ;x > 0; x -= x & -x)
      ret += b[x];
    return ret;
  }
  void add(int x,int n){
    for( ;x <= bit_size; x+= x & -x)
      b[x] += n;
  }
};

