long long merge_sort(int l,int r){
	if (l == r) return 0;
	int mid = (l+r)/2;
	long long ret = merge_sort(l,mid) + merge_sort(mid+1,r);
	int i = l;
	int j = mid+1;
	int p = l;
	while (i <= mid || j <= r) {
		if (i <= mid && (j > r || s[i] <= s[j])){
			b[p++] = a[i++];
		}else{
			b[p++] = a[j++];
			ret += mid-i+1;
		}
	}
	for (int i = l; i <= r; i++) s[i] = b[i];
	return ret;
}

