  if (l + 1 == r) {
    ret.push_back(v[l]);
    return ret;
  }
  vi64 a = merge(v, l, (l + r) / 2);
  vi64 b = merge(v, (l + r) / 2, r);
  int ai = 0, bi = 0;
  rep(i, r - l) {
    if (bi == b.size()) {
      ret.push_back(a[ai++]);
      cnt += bi;
    } else if (ai == a.size()) {
      ret.push_back(b[bi++]);
    } else {
      if (a[ai] <= b[bi]) {
        ret.push_back(a[ai++]);
        cnt += bi;
      } else {
        ret.push_back(b[bi++]);
      }
    }
  }
  return ret;
}

bool check(int md) {
  vi64 v(n);
  cnt = 0;
  rep(i, n) {
    if (a[i] >= md) v[i] = 1;
    else { v[i] = -1; cnt++; }
  }
  rep(i, n - 1) {
    v[i + 1] += v[i];
  }
  merge(v, 0, n);
  return ((u64) n * (n + 1) / 4) >= cnt;
}

