const int MAXN = 1.1e5;
int N;
int A[MAXN];

int bit[MAXN*2];
void reset() {
	for (int i = 0; i <= 2*N; i++) {
		bit[i] = 0;
	}
}
int query(int a) {
	assert(a <= 2 * N);
	int res = 0;
	for (; a; a -= a & (-a)) {
		res += bit[a];
	}
	return res;
}
void update(int a) {
	assert(a <= 2 * N);
	a++;
	for (; a <= 2 * N; a += a & (-a)) {
		bit[a] ++;
	}
}

ll go(ll v) {
	// we want to count # sequences where median is < v
	// # sequences where (#<v) is > (#>=v)
	ll res = 0;
	int pref = N;
	reset();
	update(pref);
	for (int i = 0; i < N; i++) {
		if (A[i] < v) {
			pref ++;
		} else {
			pref --;
		}
		assert(pref >= 0);
		res += query(pref);
		update(pref);
	}
	return res;
}

