int p[N];
int c[2 * N + 5];

int lowbit(int k) {return k & (-k);}

void Add(int k)
{
    for (int i = k; i <= 2 * N; i += lowbit(i))
        c[i]++;
}

long long Find(int k)
{
    long long sum = 0;
    for (int i = k; i != 0; i -= lowbit(i))
        sum += c[i];
    return sum;
}

long long Calc(int num)
{
    long long ans = 0;
    int sum = 0;
    memset(c, 0, sizeof(c));
    for (int i = 1; i <= n; i++)
    {
        if (a[i] >= num)
        {
            Add(-sum + N);
            sum++;
        }
        else
        {
            Add(-sum + N);
            sum--;
        }
        ans += Find(-sum - 1 + N);
    }
    return ans;
}

