template<typename T = int> vector<T> Zalgo( const string &S ) {
	T N = (T)S.size();
	vector<T> res(N);
	res[0] = N;
	T i = 1, j = 0;
	while ( i < N ) {
		while (i+j < N && S[j] == S[i+j]) ++j;
		res[i] = j;
		if ( j == 0 ) { ++i; continue; }
		int k = 1;
		while ( i + k < N && k + res[k] < j ) res[i + k] = res[k], ++k;
		i += k, j -= k;
	}
	return ( res );
}

void replace( string &s, string t, string r ) {
	string::size_type p = 0;
	while ( ( p = s.find( t, p ) ) != string::npos ) {
		s.replace( p, t.length(), r );
		p += r.length();
	}
}

template<typename T =ll> class BIT {
public:
	BIT( T n ) {
		size = n;
		v.resize( n + 1, 0 );
	}

	T sum( T idx ) {
		T sum = 0;
		while ( idx > 0 ) {
			sum += v[idx];
			idx -= idx & -idx;
		}
		return ( sum );
	}

	T sum( T idx1, T idx2 ) {
		return ( sum( idx2 - 1 ) - sum( idx1 - 1 ) );
	}

	void add( T idx, T val ) {
		while ( idx <= size ) {
			v[idx] += val;
			idx += idx & -idx;
		}
	}

private:
	T size;
	vector<T> v;
};

bool solve( const vector<ll> &a, ll size, ll mid )
{
	BIT<ll> b( size * 2 + 10 );
	ll sum = 0, ans = 0, pad = size + 1;
	b.add( sum + pad, 1 );
	rep( i, size )
	{
		ll val;
		if ( a[i] <= mid ) val = 1;
		else val = -1;
		sum += val;
		ans += b.sum( 1, sum + pad );
		b.add( sum + pad, 1 );
	}

	return ( ans > ( ( size * ( size + 1 ) ) / 2 ) / 2 );
}

