template<typename T>
class SegmentTree {
private:
    int N;
    vector<T> v;
    vector<tuple<int, int, T>> heap;
    function<T(T, T)> merge;

    T init(int l, LL r, int i) {
        if(l == r) {
            return 0;
        }
        if(r - l == 1) {
            T value = v[l];
            heap[i] = make_tuple(l, r, value);
            return value;
        }
        T value = merge(init(l, (l + r)/2, i*2), init((l + r)/2, r, i*2 + 1));
        heap[i] = make_tuple(l, r, value);
        return value;
    }

public:
    SegmentTree() {}

    SegmentTree(vector<T> s, function<T(T, T)> f) {
        merge = f;
        int n = s.size();
        for(N = 1;N < n;N *= 2);
        heap.resize(2*N, make_tuple(0, 0, 0));
        v.resize(N, 0);
        copy(ALL(s), v.begin());
        init(0, N, 1);
    }

    SegmentTree(vector<T> s) : SegmentTree(s, [](T x, T y){return x + y;}) {}

    void update(int index, T value) {
        int l = 0;
        int r = N;
        int i = 1;
        for(;1 < r - l;) {
            int mid = (l + r)/2;
            if(index < mid) {
                r = mid;
                i *= 2;
            }else{
                l = mid;
                i = i*2 + 1;
            }
        }
        heap[i] = tie(l, r, value);

        for(i /= 2;0 < i;i /= 2) {
            int l, r;
            tie(l, r, ignore) = heap[i];
            T v = merge(get<2>(heap[i*2]), get<2>(heap[i*2 + 1]));
            heap[i] = tie(l, r, v);
        }
    }

    T segment(int l, int r, int i=1) {
        int left, right;
        T value;
        tie(left, right, value) = heap[i];
        int mid = (left + right)/2;

        if(l == r) {
            return 0;
        }
        if(left == right) {
            return 0;
        }
        if(left == l && right == r) {
            return value;
        }
        if(r < mid) {
            return segment(l, r, i*2);
        }
        if(mid <= l) {
            return segment(l, r, i*2 + 1);
        }
        return merge(segment(l, mid, i*2), segment(mid, r, i*2 + 1));
    }
};

template<typename T=int, typename E=T>
class LazySegmentTree {
public:
    int N;
    vector<pair<int, int>> domain;
    vector<T> values;
    vector<E> lazy;
    vector<bool> updated;
    function<T(T, T)> merge;
    function<T(T, E)> apply;
    function<E(E, E)> join;
    function<E(E, int)> exp;

    T init(int l, int r, int i, vector<T> &s) {
        domain[i] = make_pair(l, r);
        int mid = (l + r)/2;
        if(r - l == 1) {
            return values[i] = s[l];
        }

        return values[i] = merge(init(l, mid, i*2, s), init(mid, r, i*2 + 1, s));
    }

    void eval(int i=1) {
        if(!updated[i]) {
            return;
        }
        updated[i] = false;

        int l, r;
        tie(l, r) = domain[i];

        if(i < N) {
            lazy[i*2] = join(lazy[i*2], lazy[i]);
            lazy[i*2 + 1] = join(lazy[i*2 + 1], lazy[i]);
            updated[i*2] = updated[i*2 + 1] = true;
        }
        E x = exp(lazy[i], r - l);
        values[i] = apply(values[i], x);
    }

    LazySegmentTree() {}
    LazySegmentTree(vector<T> s, function<T(T, T)> merge, function<T(T, E)> apply, function<E(E, E)> join, function<E(E, int)> exp) {
        int n = s.size();
        for(N = 1;N < n;N *= 2);

        domain.resize(2*N);
        values.resize(2*N);
        lazy.resize(2*N);
        updated.resize(2*N, false);

        this->merge = merge;
        this->apply = apply;
        this->join = join;
        this->exp = exp;

        init(0, N, 1, s);
    }
    LazySegmentTree(vector<T> s) : LazySegmentTree(s, [](T x, T y){return x + y;}, [](T x, E y){return y;}, [](E x, E y){return y;}, [](E x, int y){return x;}) {}

    T segment(int l, int r, int i=1) {
        eval(i);

        int left, right;
        tie(left, right) = domain[i];
        int mid = (left + right)/2;

        if(N <= i) {
            return values[i];
        }
        if(r <= mid) {
            return segment(l, r, i*2);
        }
        if(mid <= l) {
            return segment(l, r, i*2 + 1);
        }
        return merge(segment(l, mid, i*2), segment(mid, r, i*2 + 1));
    }

    T update(int l, int r, E x, int i=1) {
        eval(i);

        int left, right;
        tie(left, right) = domain[i];
        int mid = (left + right)/2;

        if(l == left && r == right) {
            lazy[i] = updated[i] ? join(lazy[i], x) : x;
            updated[i] = true;
            eval(i);
            return values[i];
        }
        if(r <= mid) {
            return values[i] = update(l, r, x, i*2);
        }
        if(mid <= l) {
            return values[i] = update(l, r, x, i*2 + 1);
        }
        return values[i] = merge(update(l, mid, x, i*2), update(mid, r, x, i*2 + 1));
    }
    T update(int i, E x) {
        return update(i, i + 1, x);
    }
};

bool check(LL N, vector<LL> a, LL p) {
    vector<LL> t(a);
    REP(i, N) {
        t[i] = p <= a[i] ? 1 : -1;
    }
    vector<LL> s(N + 1, 0);
    REP(i, N) {
        s[i + 1] = s[i] + t[i];
    }
    vector<LL> v(2*N + 1, 0);
    LazySegmentTree<LL> seg(v);
    LL ans = 0;
    REP(i, N + 1) {
        LL j = s[i] + N;
        ans += seg.segment(0, j + 1);
        LL y = seg.segment(j, j + 1);
        seg.update(j, y + 1);
    }
    return (N + 1)*N/4 <= ans;
}

