struct Set {
  int base;
  int r;
  map<int, int> mp;

  Set() : base(0), r(0), mp() {}

  void Add() {
    ++base;
    if (mp.count(-base)) {
      r += mp[-base];
    }
  }

  void Dec() {
    if (mp.count(-base)) {
      r -= mp[-base];
    }
    --base;
  }

  void Push(int k) {
    if (k >= 0) r++;
    k -= base;
    mp[k]++;
  }

  int Count() {
    return r;
  }
};

bool check(int x) {
