    cnt += st[odd].Count();
    //printf("%d: odd - %d even - %d\n", i, st[odd].Count(), st[even].Count());
    cnt += st[even].Count();

    swap(odd, even);
  }

  //printf("%d: need - %lld cnt - %lld\n", x, need, cnt);
  return cnt >= need;
}

