class Mean
{
public:
	map<int, int> d;
	int cnt;

	void add(int v)
	{
		d[v] = 0;
	}

	void set(int v)
	{
		if (d.count(v) == 0) {
			d[v] = 1;
		}
		else {
			d[v]++;
		}
		cnt++;
	}

	void init()
	{
		for (pair<int, int> p : d) {
			d[p.first] = 0;
		}
		cnt = 0;
	}

	int get_m()
	{
		int mi = cnt / 2 + 1;
		int sum = 0;
		for (pair<int, int> p : d) {
			sum += p.second;
			if (sum >= mi) { 
				return p.first; 
			}
		}

		return -1;
	}
};


class Puzzle
{
public:
	int N;
	vector<int> As;
	//vector<int> Ms;
