	{
		for (int l = 0; l < N; l++) {
			work.init();
			for (int r = l; r < N; r++) {
				work.set(As[r]);
				int m = work.get_m();
				ans.set(m);
			}
		}

		printf("%d", ans.get_m());
	}


};


