int n, a[100005], b[100005], p[100005], pp[100005];

int cdq(int l, int r)
{
	if (l == r) return 0;
	int mid = (l + r) / 2;
	int ret = cdq(l, mid) + cdq(mid + 1, r);
	int i = l;
	int now = l - 1;
	for (int j = mid + 1; j <= r; j++)	
	{
		while (p[i] <= p[j] && i <= mid)
		{
			pp[++now] = p[i];
			i++;
		}
		pp[++now] = p[j];
		if (i > mid) 
		{
			for (int k = j + 1; k <= r; k++) pp[++now] = p[k];
			break;
		}
		ret += (mid - i + 1);
	}
	for (int k = i; k <= mid; k++) pp[++now] = p[k];
	for (int i = l; i <= r; i++) p[i] = pp[i];
	return ret;
}

int erfen(int l, int r)
{
	memset(p, 0, sizeof(p));
	if (l == r) return l;
	int mid = (l + r) / 2;
	int rel = b[mid];
	for (int i = 1; i <= n; i++)
	{
		p[i] = p[i - 1];
		if (a[i] > rel) p[i]++;
		else p[i]--;
	}
	int num = cdq(0, n);
	if (num >= ((n + 1) * n / 2) / 2 + 1) return erfen(l, mid);
	else return erfen(mid + 1, r);
}

