using namespace std;

const int BIT_SIZE = 110000;

int bit[BIT_SIZE + 1];
void add(int pos, int val)
{
  for (pos += 1; pos <= BIT_SIZE; pos += pos & -pos) {
    bit[pos] += val;
  }
}

int get_sum(int pos)
{
  int ret = 0;
  for (pos += 1; pos; pos -= pos & -pos) {
    ret += bit[pos];
  }
  return ret;
}

pair<int, int> s[100001];
bool greater_than_or_equal_to(int m, int *a, int N)
{
  fill(bit, bit + BIT_SIZE + 1, 0);
  int tmp = 0;
  s[0] = make_pair(0, 0);
  for (int i = 1; i <= N; i++) {
    tmp += (a[i - 1] <= m ? 1 : -1);
    s[i] = make_pair(tmp, i);
  }
  sort(s, s + N + 1);

  long long tot = 0;
  for (int i = 0; i <= N;) {
    int j = i;
    while (j <= N && s[i].first == s[j].first) {
        tot += get_sum(s[j].second);
        j++;
    }
    while (i < j) {
        add(s[i].second, 1);
        i++;
    }
  }
  return tot >= (long long)N * (N + 1) / 4 + 1;
}

int main()
{
  int N;
  int a[100000];

  scanf("%d", &N);

  for (int i = 0; i < N; i++) {
    scanf("%d", a + i);
  }

  int l = 1, r = 1000000000;

  while (l != r) {
    int m = (l + r) / 2;
    if (greater_than_or_equal_to(m, a, N)) r = m;
    else l = m + 1;
  }

  printf("%d\n", l);

  return 0;
}

