const int INF = 1e+9;

/* 数列 {a_n} に対して、
 * ・ a[i] += w
 * ・ sum(r,l) = a[r]+...+a[l] を求めたい
 * って時に使える
 * cf. http://hos.ac/slides/20140319_bit.pdf
 */
template <typename T>
class BinaryIndexTree
{
    private:
        T N;
        vector<T> bit;

    public:
        BinaryIndexTree(T n): N(n), bit(n+1, 0) {}

        // += w
        void add(T i, T w) {
            // x & -x は x の最も下の立っているbitを取り出す
            for( T x = i; x <= N; x += x & -x) bit[x] += w;
        }
        // [1, i] の和を計算.
        T sum(T i) {
            T ret = 0;
            for (T x = i; x > 0; x -= x & -x) ret += bit[x];
            return ret;
        }
        // [left+1, right] の和を計算.
        T sum(T left, T right) {
            return sum(right)-sum(left);
        }
};


// num より大きい数が a からできる数列にいくつあるかを求める
// 転倒数 (i<j かつ a[i]>a[j] となる組の数) の求め方とほぼ同じ
long long check( int num, vector<int>& a )
{
    int N = a.size()-1;

    vector<int> S(N+1, 0);
    for( int i = 1; i <= N; ++i ){
        if(a[i] > num) S[i] = -1;
        else S[i] = 1;
    }
    for( int i = 1; i <= N; ++i ) S[i] += S[i-1];

    long long ret = 0;
    BinaryIndexTree<long long> bit(INF);
    for( int i = 1; i <= N; ++i ){
        ret += bit.sum(num-1);
        bit.add(S[i], 1);
    }
    return ret;
}


int main()
{
    int N;
    cin >> N;
    vector<int> a(N+1);
    for( int i = 1; i <= N; ++i ) cin >> a[i], cout << i;

    cout << "a";
    // 中央値になる値を二分探索
    // 数列 M には、中央値より大きい数がちょうど [M/2] あることを利用
    int l = 0, r = INF;
    long long want = 1LL*(N+1)*N/4 + 1;  //　自分より大きい数がこれだけあればOK
    while(l < r){
        int c = (l+r)/2;
        if( check(c, a) >= want ) r = c;
        else l = c+1;
    }
    cout << l << endl;
    return 0;
}

