void update(int b, int e, int node, int pos, int val)
{
	if(b == e){
		t[node] += val;
		return;
	}
	int mid = (b + e) / 2, l = node * 2 + 1, r = l + 1;
	if(mid < pos)
		update(mid + 1, e, r, pos, val);
	else 
		update(b, mid, l, pos, val);
	t[node] = t[l] + t[r];
}
int query(int b, int e, int node, int val)
{
	if(b == e)
		return e;
	int mid = (b + e) / 2, l = node * 2 + 1, r = l + 1;
	if(t[l] < val)
		return query(mid + 1, e, r, val - t[l]);
	return query(b, mid, l, val);
}
