  sort(B.begin(), B.end());
  long long ok = -1, ng = N;
  while(ng - ok > 1){
    long long m = (ok + ng)/2, b = B[m];
    vector<int> C(N);
    for(int i = 0; i < N; ++i){
      if(A[i] >= b) C[i] = 1;
      else C[i] = -1;
