    //cerr << "C : "; for(int i = 0; i < N; ++i) cerr << C[i] << " "; cerr << endl;
    long long inv = count_inv(C,0,N);
    for(int i = 1; i < N; ++i) assert(C[i] >= C[i-1]);
    if(inv <= N*(N-1)/4) ok = m;
    else ng = m;
  }
