//1-indexed
class BIT {
public:
    ll n;
    vector<ll> bit;
    BIT(ll n):n(n),bit(n+1,0){}

    void add(ll i,ll x){
        if(i==0) return;
        for(ll k=i;k<=n;k+=(k & -k)){
            bit[k]+=x;
        }
    }

    ll sum(ll i){
        ll s=0;
        if(i==0) return s;
        for(ll k=i;k>0;k-=(k & -k)){
            s+=bit[k];
        }
        return s;
    }

    ll lower_bound(ll x){
        if(x<=0){
            return 0;
        }else{
            ll i=0;ll r=1;
            while(r<n) r=r<<1;
            for(int len=r;len>0;len=len>>1) {
                if(i+len<n && bit[i+len]<x){
                    x-=bit[i+len];
                    i+=len;
                }
            }
            return i+1;
        }
    }
};

// 答えの中央値はv以下か
bool check(const vector<ll>& a, ll v) {
    ll n = a.size();

    // v以上のものが半数以上あるか
    // bの部分列で和が0以上になるなら半数以上
    vector<ll> b(a.size());
    rep(i, a.size()) b[i] = a[i] >= v ? 1 : -1;


    vector<ll> c(a.size());
    rep(i, a.size()) c[i] = (i == 0) ? b[i] : c[i-1] + b[i];

    // c[i] <= c[j] となるような(i,j)の組み合わせ。BITで求められる
    BIT bit(2 * a.size() + 1);

    // 中央値がv以上になるi,jの組み合わせ
    ll sum = 0;
    rep(j, a.size()) {
        sum += bit.sum(n + c[j]); // 自分より左にいて、自分以下のものの数
        bit.add(n + c[j], 1);
    }

    rep(i, n) {
        if (b[i] >= 0) sum++;
    }

    bool ok = sum >= n * (n+1) / 4;
    return ok;
}

void Main()
{
    ll n;
    cin >> n;
    vector<ll> a(n);
    rep(i, n) cin >> a[i];
    vector<ll> s = a;
    sort(all(s));

    ll left = 0, right = a.size();

    while (right - left > 1) {
        ll k = (right + left) / 2;
        if (check(a, s[k])) {
            left = k;
        }
        else { 
            right = k;
        }
    }

    put(s[left]);
}
