void ms(int l, int r)
{
	if (l == r) return;
	int m = (l + r) >> 1;
	ms(l, m);
	ms(m + 1, r);
	int x = l, y = m + 1, z = l;
	while ((x <= m) && (y <= r))
	{
		if (sum[x] < sum[y]) b[z++] = sum[x++];
		else
		{
			t2 += x - l;
			b[z++] = sum[y++];
		}
	}
	while (x <= m) b[z++] = sum[x++];
	while (y <= r)
	{
		t2 += x - l;
		b[z++] = sum[y++];
	}
	for (int i = l; i <= r; i++) sum[i] = b[i];
}

