ll merge_count(vector<int> &a){
	int n=a.size();
	if(n<=1) return 0;

	ll cnt=0;
	vector<int> b(a.begin(),a.begin()+n/2);
	vector<int> c(a.begin()+n/2,a.end());

	cnt+=merge_count(b);
	cnt+=merge_count(c);
	//この段階でbcはソート済み

	int ai=0,bi=0,ci=0;
	while(ai<n){
		if(bi<b.size() && (ci==c.size()||b[bi]<=c[ci])){
			a[ai++]=b[bi++];
	}
		else {
			cnt+=n/2-bi;
			a[ai++]=c[ci++];
		}
	}
	return cnt;
}


bool flag(int x,vector<int> v){
  int i;
  int l[N];
  for(i=0;i<N;i++) l[i]=2*(v[i]>=x)-1;
  vector<int> s;
  s.push_back(l[0]);
  for(i=1;i<N;i++) s.push_back(s[i-1]+l[i]);
  reverse(s.begin(),s.end());
  if (merge_count(s)>=N*(N+1)/4) return 1;
  else return 0;
}



