ll merge(ll *sums, ll l, ll m, ll r) {
  ll count = 0;
  ll arr[r - l];
  ll i = 0;
  ll x = l, y = m;
  while (x <= m || y <= r) {
    if (y <= r && (x > m || sums[x] >= sums[y])) {
      arr[i] = sums[y];
      y++;
    } else if (x <= m) {
      arr[i] = sums[x];
      x++;
      count++;
    }
    i++;
  }
  for (i = 0; l <= r; l++, i++) {
    sums[l] = arr[i];
  }
  return count;
}

ll msort(ll *sums, ll l, ll r) {
  if (l == r) {
    return 0;
  }
  ll m = l + (r - l) / 2;
  return msort(sums, l, m) + msort(sums, m + 1, r) + merge(sums, l, m + 1, r);
}

ll calc(ll in) {
  ll count = 0;
  ll sums[n];
  memset(sums, 0, sizeof(sums));
