using namespace std;

long long inv_merge(vector<int>& A, int i, int j, vector<int>& T) // [i, j)
{
    if (j - i <= 1) return 0;
    long long cnt = 0;
    int m = (i+j)/2;
    cnt += inv_merge(A, i, m, T);
    cnt += inv_merge(A, m, j, T);
    copy(&A[i], &A[j], &T[i]);
    int a = i, b = m, p = i;
    while (a < m && b < j) {
        if (T[a] <= T[b]) {
            A[p++] = T[a++];
        } else {
            A[p++] = T[b++];
            cnt += m - a;
        }
    }
    if (a < m) copy(&T[a], &T[m], &A[p]);
    if (b < j) copy(&T[b], &T[j], &A[p]);
    return cnt;
}

long long inv(const vector<int>& A) // #{(Ai,Aj)|i<j&&Ai>Aj}
{
    vector<int> B(A), T(A);
    return inv_merge(B, 0, B.size(), T);
}

bool ge(const vector<int>& A, int n) // median >= n
{
    vector<int> B(A.size());
    B[0] = A[0] >= n ? 1 : -1;
    for (int i = 1; i < A.size(); i++) {
        B[i] = (A[i] >= n ? 1 : -1) + B[i-1];
    }
    long long total = A.size()*(A.size()-1)/2;
    return inv(B) <= total / 2;
}

