    postavi(2*t,l,mid);
    postavi(2*t+1,mid+1,r);
}

void update(int t, int l,int r, int x)
{
    seg[t]++;
    if(l==r) return;
    int mid=(l+r)/2;
    if(x<=mid) update(2*t,l,mid,x);
    else update(2*t+1,mid+1,r,x);
}

ll sum(int t, int l, int r, int L, int R)
{
    if(l>R || L>r)
        return 0;
    if(l>=L && r<=R)
        return seg[t];
    int mid=(l+r)/2;
    return sum(2*t,l,mid,L,R)+sum(2*t+1,mid+1,r,L,R);
}

