void permutation(int index,int how_many,int numbers[],int n,int last_index){
    if(index == n)
        return; 
    if(how_many == n)
        permutation(index+1,0,numbers,n,0); 
    else{
        if(last_index < n-1){
            for(int i = 0; i <= how_many; i++){
                    temp.push_back(numbers[index+i]); 
            }
        }
        if(temp.size() > 0){
            medians.push_back(median(temp)); 
            temp.clear(); 
        }

        permutation(index,how_many+1,numbers,n,index+how_many);  
    }
}


