template <class T>
int inversion_number(vector<T> &a) {
  int n = a.size();
  if (n <= 1) return 0;
  vector<T> b(a.begin(), a.begin() + n / 2);
  vector<T> c(a.begin() + n / 2, a.end());
  int cnt = inversion_number(b) + inversion_number(c);
  int bn = b.size(), cn = c.size();
  int ai = 0, bi = 0, ci = 0;
  rep(i, n) {
    if (bi < bn && (ci == cn || b[bi] <= c[ci])) {
      a[i] = b[bi++];
    } else {
      cnt += n / 2 - bi;
      a[i] = c[ci++];
    }
  }
  return cnt;
}

void solve(int N, vi a) {
  int l = 1, r = max_of(a) + 1, s2 = N * (N + 1) / 4;
  while(l + 1 < r) {
    int m = (l + r) / 2;
    vi c(N + 1);
    rep(i, N)c[i + 1] = c[i] + (a[i] < m ? -1 : 1);
    (inversion_number(c) <= s2 ? l : r) = m;
  }
  COUT(l);
}


