  const ll comb = (N + 1) * N / 2;
  const ll objective = (comb + 1) / 2;

  vector<ll> s(N + 1);
  s[0] = 0;

  for (int i = 0; i < N; i++) {
    ll inc = A[i] < mid ? -1 : 1;
    s[i + 1] = s[i] + inc;
