    while (i <= mid && j <= r){
        if (sum[i] <= sum[j]){
            tmp[k++] = sum[i++];
            ret += ri-j+1;
        }
        else
            tmp[k++] = sum[j++];
    }
    while (i <= mid)
        tmp[k++] = sum[i++];
    while (j <= r)
        tmp[k++] = sum[j++];
    for (int o = le; o <= ri; o++)
        sum[o] = tmp[o];
    return ret;
}

