template <typename T>
struct fenwick{
  vector<T> fenw;
  int n;

  fenwick(int n): n(n){
    fenw.resize(n);
  }

  void modify(int x, T val){
    for( ; x < n; x |= (x + 1)){
      fenw[x] += val;
    }
  }

  T get(int x){
    T res {};
    for(; x >= 0; x = (x & (x + 1)) - 1){
      res += fenw[x];
    }
    return res;
  }
};

