    for (int i = 0; i < N; ++i) {
        S[i + 1] = S[i] + ((a[i] >= x) ? 1 : -1);
    }

    ll cnt = 0;
    for (int j = 0; j <= N; ++j) {
        cnt += bit.sum(S[j] + N);
