        const lint SFT = 1e6;
        fenwick_tree<lint> ft(n+SFT+3);

        // 中央値が k 以下か？　⇔　k 以下の数が N/2 より大
        repeat (i, n) {
            b[i+1] = (a[i+1] <= k) ? -1 : +1;
