class BIT {
public:
	int N;
	vll v;
	BIT(int n) {
		N = 1;
		while (N < n)	N <<= 1;
		v = vll(N + 1, 0LL);
	}
	void update(int i, ll k) {
		while (i <= N) {
			v[i] += k;
			i += -i & i;
		}
	}
	ll get(int i) {
		ll ret = 0;
		while (i > 0) {
			ret += v[i];
			i -= -i & i;
		}
		return ret;
	}
};

