			b[j] += b[j - 1];
		}
		vint comp = b;
		sort(all(comp));
		comp.erase(unique(all(comp)), comp.end());
		BIT bit(comp.size());
		ll cnt = 0;
		rrep(j, n) {
			int idx = lower_bound(all(comp), b[j]) - comp.begin() + 1;
			cnt += bit.get(idx);
			bit.update(idx, 1);
		}
		if (cnt * 4 >= (ll)n*(n + 1))	r = mid;
		else	l = mid;
	}
	cout << r << endl;
	return 0;
}

