#define SHIFT 100105

void add(long long T[], int x, long long v) {
    for (; x < MAXN; x += x&-x)
        T[x] += v;
}

long long sum(long long T[], int x) {
    long long ans = 0;
    for (; x; x -= x&-x)
        ans += T[x];
    return ans;
}

int work1(int x) {
    int ans = 0;
    for (int i = 0; i < n; i++) {
        for (int len = 1; len+i<=n; len++) {
            vector<int> v;
            for (int j = i; j < i+len; j++)
                v.pb(a[j]);
            sort(v.begin(), v.end());
//            for (int x : v)
//                cerr << x << ' ';
//            cerr << " med " << v[len/2] << '\n';
            if (v[len/2] <= x) ans++;
        }
    }
//    cerr << "work " << x << ' ' << ans << '\n';
    return ans;
}

int work(int x) {
    long long ans = 0;
    vector<pii> slots;
//    cerr << "---------\n";
//    cerr << "work " << x << '\n';

    for (int i = 0, ps = 0; i < n; i++) {
        add(f[(i%2)^1], ps+SHIFT, 1);
        slots.pb(mp((i%2)^1, ps+SHIFT));

        if (a[i] <= x)
            ps++;
        else
            ps--;


        int s1 = sum(f[(i%2)^1], ps-1 + SHIFT);
        int s2 = sum(f[(i%2)], ps-2 + SHIFT);

//        cerr << "ps " << ps << ' ' << s1 << ' ' << s2 << '\n';

        ans += s1 + s2;
    }

    for (auto op : slots)
        add(f[op.fi], op.se, -1);

    // cur - pref >= 1
    // pref <=
    // pref = cur-1

//    cerr << " ret " << ans << '\n';

    return ans;
}

void solve() {
    f[0] = T1;
    f[1] = T2;
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        sorted[i] = a[i];
    }
    sort(sorted, sorted+n);

    int hi = n, lo = -1;
    while (hi-lo>1) {
        int mi = (hi+lo)/2;
        if (work(sorted[mi]) >= ((long long)n*(n+1)/2)/2+1) hi = mi;
        else lo = mi;
    }
//    cout << hi << '\n';
    cout << sorted[hi] << '\n';
}

