using namespace std;

long long count_inv(vector<int> &C, int l, int r){
  if(r - l == 1) return 0;
  int m = (l+r)/2;
  long long ret = count_inv(C,l,m) + count_inv(C,m,r);
  vector<int> L, R;
  for(int i = l; i < r; ++i){
    if(i < m) L.push_back(C[i]);
    else R.push_back(C[i]);
  }
  int N = L.size(), M = R.size(), cur = l, j = 0;
  for(int i = 0; i < N; ++i){
    while(j < M and R[j] < L[i]) C[cur++] = R[j++];
    ret += j;
    C[cur++] = L[i];
  }
  return ret;
}

int main(){
  int N;
  cin >> N;
  vector<int> A(N);
  for(int i = 0; i < N; ++i) cin >> A[i];
  vector<int> B = A;
  sort(B.begin(), B.end());
  int ok = 0, ng = N;
  while(ng - ok > 1){
    int m = (ok + ng)/2, b = B[m];
    vector<int> C(N);
    for(int i = 0; i < N; ++i){
      if(A[i] >= b) C[i] = 1;
      else C[i] = -1;
    }
    for(int i = 1; i < N; ++i) C[i] += C[i-1];
    //cerr << "C : "; for(int i = 0; i < N; ++i) cerr << C[i] << " "; cerr << endl;
    long long inv = count_inv(C,0,N);
    if(inv <= (long long)N*(N-1)/4) ok = m;
    else ng = m;
  }
  //cerr << ok << endl;
  cout << B[ok] << endl;
  return 0;
}

