inline int build(int l,int r){
	int p=++tot;
	if(l==r) return p;
	int mid=(l+r)>>1;
	t[p].l=build(l,mid);t[p].r=build(mid+1,r);
	return p;
}

inline int update(int p,int l,int r,int k){
	int x=++tot;t[x]=t[p];t[x].cnt++;
	if(l==r) return x;
	int mid=(l+r)>>1;
	if(k<=mid) t[x].l=update(t[p].l,l,mid,k);
	else t[x].r=update(t[p].r,mid+1,r,k);
	return x;
}

inline int query(int pl,int pr,int l,int r,int k){
	if(l==r) return l;
	int sum=t[t[pr].l].cnt-t[t[pl].l].cnt,mid=(l+r)>>1;
	if(sum>=k) return query(t[pl].l,t[pr].l,l,mid,k);
	else return query(t[pl].r,t[pr].r,mid+1,r,k-sum);
}

inline void add(int p,int l,int r,int k){
	t[p].cnt++;
	if(l==r) return ;
	int mid=(l+r)>>1;
	if(k<=mid) add(t[p].l,l,mid,k);
	else add(t[p].r,mid+1,r,k);
}

