        REP(i, N) {
            s[i + 1] = s[i] + t[i];
        }
        vector<int> v(2*N + 1, 0);
        SegmentTree<int> seg(v);
        int ans = 0;
        REP(i, N + 1) {
            int j = s[i] + N;
            int y = seg.segment(j, j + 1);
            seg.update(j, y + 1);
