bool valid(int m){
    memset(C,0,sizeof(C));

    int min_val = maxn;

    _for(i,0,N){
        B[i+1] = B[i];
        if(A[i] >= m){
            B[i+1]++;
        }
        else{
            B[i+1]--;
        }
        min_val = min(min_val,B[i+1]);
    }

    if(min_val <= 0){
        int ad = -min_val + 1;
        _rep(i,1,N){
            B[i] += ad;
        }
    }

    LL ss = shun(N);
    //cout << ss <<endl;

    LL len = (N*(N+1))/2;
    return ss >= (1+len)/2;
}




