int csum[2*MAXN];

bool good (int cc)
{
    for (int i = 0; i < N; i++)
    {
        if (arr[i] >= cc)
            p[i] = 1;
        else
            p[i] = -1;
    }
    for (int i = 0; i < 2 * MAXN; i++)
        csum[i] = 0;

    int cs = MAXN;
    csum[cs] = 1;
    int ctot = 1;
    ll res = 0;
    for (int i = 0; i < N; i++)
    {
        if (p[i] == -1)
        {
            ctot -= csum[cs];
            cs--;
        }
        else
        {
            ctot += csum[cs+1];
            cs++;
        }
        res += ctot;
        csum[cs]++;
        ctot++;
    }
    //cout << cc << " " << res << "\n";
    return res * 2 >= (N * ((ll) N + 1)) / 2;
}

