class Bit {
  public:
    int n;
    vector<ll> bit;

    Bit(int nn) {
      n = nn;
      vector<ll> b(n+1, 0);
      bit = b;
    }

    ll sum(int i) {
      int s= 0;
      while(i > 0) {
	s += bit[i];
	i -= i & -i;
      }
      return s;
    }

    void add(int i, ll x) {
      while(i <= n) {
	bit[i] += x;
	i += i & -i;
      }
    }
};

ll d(int n, vector<ll> a) {
  vector<ll> b(n);
  copy(a.begin(), a.end(), b.begin());
  sort(b.begin(), b.end());

  int low = 0;
  int high = n-1;
  int offset = n+1;
  while(high - low > 1) {
    int mid = (low + high) / 2;
    vector<int> acc(n);
    acc[0] = (b[mid] >= a[0] ? 1 : -1);
    for(int i=1;i<n;i++) {
      acc[i] += acc[i-1] + (b[mid] >= a[i] ? 1 : -1);
    }
    int num = 0;
    Bit bit = Bit(2*n+100);
    for(int j=0;j<n;j++) {
      num += bit.sum(offset + acc[j]);
      bit.add(offset + acc[j], 1);
    }
    if(num > ((n*(n-1)/2) + n)/2) {
      high = mid;
    } else {
      low = mid;
    }
  }
  return b[high];
}

