ll cnter(ll x, ll y){
	map<ll,ll> BIT;
	b[0]=0;
	ll minb=b[0]; ll maxb=b[0];
	REP(i,y){
		if (a[i]<x) b[i+1]=b[i]-1;
		else b[i+1]=b[i]+1;
		minb=min(minb,b[i+1]);
		maxb=max(maxb,b[i+1]);
	}
	REP(i,y+1) b[i]+=(1-minb);
	ll ans = 0;
	REP(i,y+1){
		ll p = b[i];
		ll q = b[i];
		while(p>0){
			ans+=BIT[p];
			p-=p&-p;
		}
		while(q<maxb+2-minb){
			BIT[q]++;
			q+=q&-q;
		}
	}
	return ans;
}

