        bit.resize(n+1,0);
    }
    //1-indexed [1,x]-sum
    lint sum(lint x){
        lint res=0;
        for(lint i=x;i>0;i-=i&-i)res+=bit[i];
        return res;
    }
    //1-indexed [x,y]-sum
    lint sum(lint x,lint y){
        return sum(y)-sum(x);
    }
    //1-indexed
    void add(lint x,lint val){
        x++;
        if(x>n)return;
        for(lint i=x;i<=n;i+=i&-i)bit[i]+=val;
    }
};
lint bs(lint mn,lint mx,auto func){
    mn--;
    mx++;
	while(mx-mn>1){
		lint mid=(mn+mx)/2;
		if(!func(mid))mx=mid;
		else mn=mid;
	}
    return mn;
}

int main(){
    lint n;
    cin>>n;
    vec a(n);
    rep(i,n)cin>>a[i];
    lint k=n*(n+1)/4+1;
    auto f=[&](lint x){
        BIT bit(2*n);
        vec v(n+1,0);
        bit.add(n,1);
        lint cnt=0;
        rep(i,n){
            if(a[i]<x)v[i+1]=v[i]-1;
            else v[i+1]=v[i]+1;
            cnt+=bit.sum(v[i+1]+n+1,2*n);
            bit.add(v[i+1]+n,1);
        }
        return cnt<k;
    };
    cout<<bs(0,INF,f)<<endl;
}

