template <typename Value,typename Index>
Value quick_select(vector<Value> A,Index k) {
    Index sz = A.size();
    if (sz == 1) return A[0];
    if (sz == 2) return ( k==0 ? min(A[0],A[1]) : max(A[0],A[1])); 
    vector<Value> medians;
    for (Index i = 0;i < sz;i += 5) {
        Index subStart = i;
        Index subEnd = min(i+5,sz);
        sort((A.begin()+subStart),(A.begin()+subEnd));
        Value median = A[(subStart+subEnd)/2];
        medians.push_back(median);
    }
    Index n = medians.size();
    Value pivot = quick_select(medians,n/2);
    Index pivotIndex = 0,sameIndex = 0;
    vector<Value> small,large;
    for (Index i = 0;i < sz;i++) {
        if (A[i] < pivot) {
            pivotIndex++;
            small.push_back(A[i]);
        }
        else if (A[i] > pivot) large.push_back(A[i]);
        else sameIndex++;
    }
    if (pivotIndex <= k && k <= (pivotIndex+sameIndex-1)) return pivot;
    else if (pivotIndex < k) return quick_select(large,k-(pivotIndex+sameIndex));
    else return quick_select(small,k);
}

map<pr,char> dic;
