void dfs(LL l,LL r,LL mid) {
    if (IN(pr(l,r),dic)) return;
    else {
        dic[pr(l,r)] = 1;
        lst.push_back(mid);
    }
    LL n = (r - l);
    if (l == r) return;
    if ( (r - l + 1) % 2) {
        if (a[r] > mid) dfs(l,r-1,mid);
        else {
            VI c(a.begin()+l,a.begin()+r);
            LL md = quick_select(c,(n/2));
            dfs(l,r-1,md);
        }
        if (a[l] > mid) dfs(l+1,r,mid);
        else {
            VI d(a.begin()+l+1,a.begin()+r+1);
            LL md2 = quick_select(d,(n/2));
            dfs(l+1,r,md2);
        }
    }

    else {
        if (a[r] < mid) dfs(l,r-1,mid);
        else {
            VI c(a.begin()+l,a.begin()+r);
            LL md = quick_select(c,(n/2));
            dfs(l,r-1,md);
        }
        if (a[l] < mid) dfs(l+1,r,mid);
        else {
            VI d(a.begin()+l+1,a.begin()+r+1);
            LL md2 = quick_select(d,(n/2));
            dfs(l+1,r,md2);
        }
    }
}

