{
	long long a[300005];
	inline long long lowbit(long long x) { return x & (~x + 1); }
	inline void add(long long x, long long val)
	{
		for (long long i = x; i < 3 * n; i += lowbit(i))	a[i] += val;
	}
	inline long long sum(long long x)
	{
		long long res = 1;
		for (long long i = x; i; i -= lowbit(i))	res += a[i];
		return res;
	}
