bool check(int x)
{
	long long cnt = 0;
	for (int i = 1; i <= n; ++i)
	{
		sum[i] = a[i] > x;
		sum[i] += sum[i - 1];
	}
	for (int i = 1; i <= n; ++i)
	{
		sum[i] = (2 * sum[i] - i) + n + 1;
	}
	for (int i = 1; i <= n; ++i)
	{
		cnt += BIT::sum(sum[i]);
		BIT::add(sum[i], 1);
	}
	return cnt > 1ll * n*(n + 1) / 4 + 1ll;
}
