	{
		scanf("%d", a + i);
		l = min(l, a[i]);
		r = max(r, a[i]);
	}
	ans = l;
	while (l <= r)
	{
		mid = (l + r) >> 1;
		if (check(mid))	l = mid + 1, ans = mid;
		else r = mid - 1;
	}
