class BIT {
  public:
    void init(ll size) {
      bit.resize(size + 1, 0);
    }
    ll sum(ll i) {
      if (!i) {
        return 0;
      }
      return bit[i] + sum(i - (i & -i));
    }

    void add(ll i, ll x) {
      if (i >= (ll)bit.size()) {
        return;
      }
      bit[i] += x;
      add(i + (i&-i), x);
    }
    std::vector<ll> bit;
};

bool check(ll x) {
  for (ll i=0;i<n;i++) {
    if (a[i] >= x) {
      sum[i+1] = 1;
    } else {
      sum[i+1] = -1;
    }
  }
  for (ll i=0;i<n;i++) {
    sum[i+1] += sum[i];
  }
  ll cnt = 0;
  BIT bit;
  bit.init(2 * (n + 1));
  for (ll i=0;i<=n;i++) {
    cnt += bit.sum(sum[i] + n);
    bit.add(sum[i] + n, 1);
  }
  return cnt >= n * (n+1) / 4;
}

