// Segment-Tree
struct SegmentTree {
  int n;
  vector<ll> dat;

  SegmentTree(int _n) {
    init(_n);
  }

  void init(int _n) {
    n = 1;
    while (n < _n) n *= 2;
    dat.resize(2 * n - 1, 0);
  }

  // i番目の値にxを加算
  void add(int i, int x) {
    i += n - 1; // 葉のノード
    dat[i] += x;
    while (i > 0) { // 更新
      i = (i - 1) / 2;
      dat[i] = dat[2 * i + 1] + dat[2 * i + 2];
    }
  }

  // [a, b)の和
  // k:ノードの番号 [l, r)がkに対応づいている
  ll query(int a, int b, int k = 0, int l = 0, int r = -1) {
    if (r == -1) r = n;
    if (r <= a || b <= l) return 0;
    if (a <= l && r <= b) return dat[k];
    else {
      ll vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
      ll vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
      return vl + vr;
    }
  }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll n;
  cin >> n;

  vector<ll> a(n);
  for (int i = 0; i < n; i++) cin >> a.at(i);

  ll l = 1, r = 1e9 + 1, total = n * (n + 1) / 2, itadd = 1e5;
  while (r - l > 1) {
    ll mid = (l + r) / 2, count = 0, now = 0;
    SegmentTree st(2e5 + 1);
    st.add(0 + itadd, 1);
    for (int i = 0; i < n; i++) {
      if (a.at(i) >= mid) now++;
      else now--;
      count += st.query(0, now + 1 + itadd);
      st.add(now + itadd, 1);
    }
    if (count >= (total + 1) / 2) l = mid;
    else r = mid;
  }

  cout << l << '\n';
}

