inline int lowbit(int x) { return x & -x; } 
inline void add(int c[], int p) {
	for(; p<=m; p+=lowbit(p))
		c[p]++;
}
inline int query(int c[], int p) {
	int res = 0;
	for(; p; p^=lowbit(p))
		res += c[p];
	return res;
}

bool judge(int mid) { // judge if ans >= mid
	int i, j, k;
	int64 ans = 0;

	memset(c, 0, sizeof(c));

	sum[0][0] = n + 2;
	for(i=1; i<=n; i++) {
		j = i >> 1;
		k = i & 1;
		sum[k][j] = sum[!k][j - !k] + (a[i] < mid);
	}

	for(i=0; sum[0][i]; i++) {
		for(j=0; j<=1 and sum[j][i]; j++) {
			ans += query(c[j], sum[j][i] - i - 1);
			ans += query(c[!j], sum[j][i] - i - j);
			if(j == 1)
				ans += sum[1][i] - sum[0][i];
		}
		for(j=0; j<=1 and sum[j][i]; j++)
			add(c[j], sum[j][i] - i);
	}

	return ans < (n + 1ll) * n / 4 + 1;
}

