} seg[1<<23];

void update(int i, int x){
    i += (1<<22)-1;
    seg[i].mi = seg[i].mx = x;

    while(i > 0){
        i = (i-1)/2;
        seg[i].mi = min(seg[i*2+1].mi, seg[i*2+2].mi);
        seg[i].mx = max(seg[i*2+1].mx, seg[i*2+2].mx);
    }
}

Node query(int a, int b, int k=0, int l=0, int r = (1<<22)){
    if(r <= a || b <= l) return Node(INT_MAX, -INT_MAX);
    if(a <= l && r <= b) return seg[k];
    else{
        Node vl = query(a, b, k*2+1, l, (l+r)/2);
        Node vr = query(a, b, k*2+2, (l+r)/2, r);

        return Node(min(vl.mi, vr.mi), max(vl.mx, vr.mx));
    }
}
template<class TYPE>
struct Fenwick {
  int N;
  vector<ll> bit;

  Fenwick():N(0) {}
  Fenwick(int n) : N(n), bit(N+1, 0){}

  void add(int i, ll x){
    ++i; //0-indexedを避けるために加算
    while(i <= N){
      bit[i] += x;
      i += (i & -i);
    }
  }

  ll sum(int i){
    ll res = 0;
    while(i>0){
      res += bit[i];
      i -= (i & -i);
    }
    return res;
  }

  ll range(int i, int j){
    return sum(j) - sum(i);
  }

  ll get(int i){
    return sum(i) - sum(i-1);
  }
};
