ll se1(ll p, ll q) {
	ll re = 0;
	while (p < q) {
		if (p % 2 == 1) re += tr[p], p++;
		if (q % 2 == 0) re += tr[q], q--;
		p /= 2; q /= 2;
	}
	if (p == q) re += tr[p];
	return re;
}

void se2(ll p) {
	for (; p; p /= 2) {
		tr[p] = tr[p * 2] + tr[p * 2 + 1];
	}
}

