const int MAX = 100000;

class BIT {
public:
	BIT(int n) {
		size = n + 1;
		bit = new int[size];

		for (int i = 0; i < size; i++)bit[i] = 0;
	}
	~BIT() {
		delete[] bit;
	}

	void add(int i, int n) {
		i += 1;
		while (i < size) {
			bit[i] += n;
			i += i & -i;
		}
	}

	int sum(int i) {
		i += 1;
		int ret = 0;
		while (i) {
			ret += bit[i];
			i -= i & -i;
		}
		return ret;
	}
	int size;
	int* bit;
};

int N;
int a[MAX];

bool solve(int x) {
	long long cnt = 0;
	int sum = 0;
	BIT bit(N * 2);

	for (int i = 0; i < N; i++) {
		sum += a[i] >= x ? 1 : -1;
		cnt += bit.sum(N + sum) + (sum >= 0 ? 1 : 0);
		bit.add(N + sum, 1);
	}

	if (cnt >= ((long long)N * (N + 1) / 2) / 2)return true;
	return false;
}

int main() {
