	for (int i = 0; i < N; i++) {
		cin >> a[i];
		end = max(end, a[i] + 1);
	}

	if (N == 1)ans = a[0];
	else {
		while (begin < end) {
			int mid = (begin + end) / 2;

			if (solve(mid)) {
				ans = mid;
				begin = mid + 1;
			}
			else {
				end = mid;
			}
		}
	}

	cout << ans << endl;

	return 0;
}

