template<typename Monoid>
class SegTree {

//半開区間!!!!!!!!!!!!!!!
public:
    int p = 2;
    vector<Monoid> node;
    using Func = function<Monoid(Monoid,Monoid)>;
    Func pick; Monoid init;//操作と単位元

    SegTree(vector<Monoid> A, string type, Monoid m) {
        if (type == "min") {
            pick = [](Monoid a, Monoid b){return min(a,b);};
        } else if (type == "max") {
            pick = [](Monoid a, Monoid b){return max(a,b);};
        } else if (type == "sum") {
            pick = [](Monoid a, Monoid b){return a + b;};
        }

        init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    SegTree(vector<Monoid> A, Func f, Monoid m) {
        pick = f; init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    //1点更新
    void update(int i, Monoid v) {
        for (node[(i+=p)-1] = v; i >>= 1;) {
            node[i-1] = pick(node[i*2-1], node[i*2]);
        }
    }

    //1点加算
    void add(int i, Monoid v) {
        update(i, this[i] + v);
    }

    Monoid getval(int start,int end,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = p;
        if (r <= start || end <= l) {return init;}
        if (start <= l && r <= end) {return node[k];}
        Monoid L,R;
        L = getval(start,end,k*2+1,l,(l+r)/2);
        R = getval(start,end,k*2+2,(l+r)/2,r);
        return {pick(L,R)};
    }

    inline Monoid operator [] (int i) {
        return node[i+p-1];
    }
};

void solve() {
    int n; cin >> n;
    vector<int> A(n); rep (i, n) cin >> A[i];

    int All = n * (n + 1) / 2;
    int l = -1, r = INF;
    while (r - l > 1) {
        int mid = (r + l) / 2;
        vector<int> now(n + 1);
        int small = 0, large = 0;
        now[0] = -1;
        rep (i, n) {
            if (A[i] <= mid) now[i+1] = now[i] - 1;
            else now[i+1] = now[i] + 1;
            chmax(large, now[i+1]);
            chmin(small, now[i+1]);
        }
        SegTree<int> seg(vector<int>(large-small+1), "sum", 0);
        rep (i, n + 1) {
            now[i] -= small;
        }
        large-=small; ++large;
        int cnt = 0;
        rep (i, n + 1) {
            cnt += seg.getval(now[i]+1, large);
            seg.update(now[i], seg[now[i]]+1);
        }
        if (All/2+1 <= cnt) r = mid;
        else l = mid;
    }
    cout << r << endl;
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

