class BIT {
public:
    /* [1, n] */
    vector<long long> bit;

    BIT(int M) :
            bit(vector<long long>(M + 1, 0)) {}

    /* [1, a], a is 1-indexed */
    long long sum(int a) {
        long long res = 0;
        for (int i = a; i > 0; i -= (i & -i)) {
            res += bit[i];
        }
        return res;
    }

    /* [a, b), a and b are 1-indexed */
    long long sum(int a, int b) {
        return sum(b - 1) - sum(a - 1);
    }

    /* a is 1-indexed */
    void add(int a, long long x) {
        for (int i = a; i < bit.size(); i += (i & -i)) {
            bit[i] += x;
        }
    }
};

