bool check(ll x) {
  ll num = 0;

  for (int i = 1; i <= n; ++i) s[i] = (a[i] >= x) ? 1 : -1;
  for (int i = 1; i <= n; ++i) num += (s[i] == 1) ? 1 : 0; // for singleton
  for (int i = 1; i <= n; ++i) s[i] += s[i - 1];

  bit.init();

  for (int i = 1; i <= n; ++i) {
    num += bit.sum(s[i] + MAX_N);
    bit.add(s[i] + MAX_N, 1);
  }

  ll whole = (((ll)(n) + 1) * (ll)(n)) / 2;
  ll target =  (whole - 1 + 2) / 2;

  return (num >= target);
}

