struct BIT {
    vector< int > bit;
    int M;

    BIT(int M) : bit(vector< int >(M + 1, 0)), M(M) {}

    int sum(int i) {
        if (!i) return 0;
        return bit[i] + sum(i - (i & -i));
    }

    void add(int i, int x) {
        if (i > M) return;
        bit[i] += x;
        add(i + (i & -i), x);
    }
};

bool check(int x) {
    // cout << "check: " << x << endl;

    int tot = 0;
    const int offset = 1e5;
    ll sum = 0;
    BIT bit(N_MAX * 2);

    bit.add(offset, 1);
    for (int i = 0; i < N; i++) {
        if (x <= a[i]) tot++;
        else tot--;

        // cout <<  "  i = " << i << ": " << bit.sum(tot + offset) << endl;
        sum += bit.sum(tot + offset);
        bit.add(tot + offset, 1);
    }

    // cout << "sum = " << sum << endl;
    return sum >= ceil((1LL * N * (N - 1) / 2 + N) / 2);
}

