{
	if (l == r) return 0;
	ll ans = 0;
	int mid = (l + r) >> 1;
	ans += merge_sort(l, mid);
	ans += merge_sort(mid + 1, r);
	int i = l, j = mid + 1, index = l;
	while (i <= mid && j <= r) {
		if (sum[i] < sum[j])
			temp[index++] = sum[i++];
		else
			temp[index++] = sum[j++], ans += (mid + 1 - i);
	}
	while (i <= mid) temp[index++] = sum[i++];
	while (j <= r) temp[index++] = sum[j++];
	for (int i = l; i <= r; i++) sum[i] = temp[i];
	return ans;
}

