template <class T> struct FenwickTree {
  vector<T> node;
  FenwickTree (int n) : node(n, 0) {}

  void add(int idx, T val){
    for (int i = idx; i < node.size(); i |= i + 1) {
      node[i] += val;
    }
  }

  void update(int idx, T val){
    add(idx, -sum(idx, idx+1));
    add(idx, val);
  }

  T sum(int idx){
    T ret = 0;
    for (int i = idx-1; i >= 0; i = (i & (i+1))-1){
      ret += node[i];
    }
    return ret;
  }

  T sum(int l, int r){
    return sum(r)-sum(l);
  }
};

ll InversionNumber(vector<int> &arr){
  ll ret = 0;
  FenwickTree<ll> inst(MAX_N);
  for (int i = 0; i < arr.size(); ++i){
    ret += inst.sum(arr[i]+1);
    inst.add(arr[i], 1);
  }
  return ret;
}


bool check(int x){
  vector<int> S(n+1);
  for (int i = 0; i < n; ++i){
    S[i+1] = (a[i]>=x) ? 1 : -1;
  }
  for (int i = 0; i < n; ++i) S[i+1] += S[i];
  int minV = S[0];
  for (int i = 0; i < n+1; ++i) minV = min(minV, S[i]);
  for (int i = 0; i < n+1; ++i) S[i] -= minV;
  for (int i = 0; i < n+1; ++i) S[i]++;

  ll inv = InversionNumber(S);
  ll num = n*(n+1)/2 + 1;
  return (num/2 <= inv) ? true : false;
}


