LL merge_sort(int l, int r) {
  if (l == r) return 0;
  int mid = (l + r) / 2;
  LL ret = merge_sort(l, mid) + merge_sort(mid + 1, r);
  int i = l, j = mid + 1, p = l;
  while (i <= mid || j <= r) {
    if (j > r || (i <= mid && s[i] <= s[j])) t[p++] = s[i++];
    else t[p++] = s[j++], ret += mid - i + 1;
  }
  For(i,l,r) s[i] = t[i];
  return ret;
}

