class Bit{ // 1-indexedに注意
    const int n; // 最大値
    std::vector<int> bit;
public:
    Bit(int nn): n(nn){
        bit.resize(n+1, 0);
    }
    // 0で再初期化
    bool clear(){
        std::fill(bit.begin(), bit.end(), 0);
        return true;
    }
    // A[idx]にvalを加算
    bool add(int idx, int val){
        if(n < idx) return false;
        for(int i = idx; i <= n; i += (i & (-i))) bit[i] += val;
        return true;
    }
    // 区間[1, 2, ..., a]の和
    int sum(int idx){
        int res = 0;
        for(int i = idx; i > 0; i -= (i & (-i))) res += bit[i];
        return res;
    }
};

