                lli cnt = 0; // l < r であって, S_l < S_r なるものを数える
                for(int i = 0; i < n; ++i){
                    if(A[i] <= v) S++; else S--;
                    cnt += BT.sum(S-1);
                    BT.add(S, 1);
                }
                // S_l < S_r なるものは MSize - cnt


        if(MSize - cnt < cnt ) ok = t;
        else ng = t;
    }
    printf("%d\n", SA[ok]);


    return 0;
}

