long long merge( int l, int r ){
	if( l == r )
		return 0;
	int mid = (l+r) / 2;
	long long res = merge(l, mid) + merge(mid+1, r);
	int i = l, j = mid+1, k = l;
	while( i <= mid || j <= r ){
		if( j > r || (i <= mid && sum[i] <= sum[j]) )
			t[k++] = sum[i++];
		else
			t[k++] = sum[j++], res += mid - i + 1;
	}
	for( int i = l; i <= r; ++i )
		sum[i] = t[i];
	return res;
}
bool check( int x ){
	for( int i = 1; i <= n; ++i )
		sum[i] = sum[i-1] + (nums[i] < x ? -1 : 1);
