const int MAX = 1e9;

template<typename T>
struct BinaryIndexedTree{
private:
  int n;
  T *data;

public:
  BinaryIndexedTree(int n = 0) : n(n){
    data = new T[n + 1];
    for(int i = 0; i <= n; i++) data[i] = 0;
  }

  bool add(int index, T x = 1){
    if(index < 0 || n <= index) return false;
    for(index++; index <= n; index += index & -index){
      data[index] += x;
    }
    return true;
  }

  T sum(int index){
    if(index < 0) index = 0;
    else if(index >= n) index = n - 1;

    T x = 0;
    for(index++; index; index -= index & -index){
      x += data[index];
    }
    return x;
  }

  ~BinaryIndexedTree(){
    delete [] data;
  }
};

int median_of_medians(vector<int>& a){
  int n = a.size();

  int ok = MAX, ng = 0;
  while(ok - ng > 1){
    int mid = (ok + ng) >> 1;

    vector<int> o(n);
    for(int i = 0; i < n; i++){
      o[i] = a[i] <= mid ? 1 : -1;
      if(i) o[i] += o[i - 1];
    }

    long long num = 0;
    BinaryIndexedTree<int> bit(2 * n + 1);
    bit.add(n);
    for(int i = 0; i < n; i++){
      num += bit.sum(o[i] + n - 1);
      bit.add(o[i] + n);
    }

    (num > (((long long)n * (n + 1) >> 1) >> 1) ? ok : ng) = mid;
  }

  return ok;
}

