template <typename T> struct BIT {
  std::vector<T> tree;
  long long int size;

  BIT(long long int n) : tree(n + 1, T()), size(n) {}

  T sum(long long k) {
    T s = 0;
    assert(0 <= k && k < size);

    for (long long int i = k + 1; i > 0; i -= i & -i) {
      s = s + tree[i];
    }
    return s;
  }

  T range(long long int start, long long int end) {
    return sum(end) - sum(start - 1);
  }

  void add(long long int k, T v) {
    assert(0 <= k && k < size);
    for (long long int i = k + 1; i <= size; i += i & -i) {
      tree[i] = tree[i] + v;
    }
  }

  void debug() {
    for (long long int i = 0; i <= size; i++) {
      std::cout << tree[i] << " ";
    }
    std::cout << std::endl;
  }
};

