typedef long long ll;

struct fenwick_tree {
    int N;
    vector<int> bit;
    fenwick_tree(int num) : bit(num + 1, 0) { N = num; }
    int Sum(int a) {
        int ret = 0;
        for (int x = a; x > 0; x -= x & -x) {
            ret += bit[x];
        }
        return ret;
    }
    void Add(int a, int w) {
        for (int x = a; x <= N; x += x & -x) {
            bit[x] += w;
        }
    }
};

ll a[100005];

bool judge(ll mid, int n) {
    int offset = n+1;
	ll num_inverse = 0;
	fenwick_tree bit(n*2+10);

	int sum_v = 0;
    bit.Add(sum_v+offset, 1);

	for (int i = 0; i < n; i++) {
		int s = (a[i] <= mid) ? 1 : -1;
		sum_v += s;
		num_inverse += (bit.Sum(sum_v-1+offset) - bit.Sum(0));
		bit.Add(sum_v+offset, 1);
	}
	if (num_inverse > (n+1)*n/2/2) {
        return true;
    } else {
        return false;
    }
}

