void process(long long d) {
	memset(cnt, 0, sizeof cnt);
	memset(dp, 0, sizeof dp);
	for (long long i = 1; i <= n; i++) {
		P[i] = (d <= Arr[i]? +1: -1);
		psum[i] = P[i] + psum[i - 1];
	}
}

long long calc(long long d) {
	long long res = 0;
	cnt[50000] = 1;

	for (long long i = 1; i <= n; i++) {
		dp[i] = dp[i - 1];
		if (P[i] == +1)
			dp[i] += cnt[50000 + psum[i - 1]];
		else
			dp[i] -= cnt[50000 + psum[i]];

		res += dp[i] + cnt[50000+ psum[i]];
		cnt[50000+ psum[i]]++;
	}

	return res;
}

