struct BIT{
    vector<int> data;

    void init(int n){
        data.assign(n+1, 0);// 1-indexed [1,n]
    }

    void add(int i, int x){
        while(i <= data.size() - 1){
            data[i] += x;
            i += (i & -i);
        }
    }

    int sum(int i){
        int s = 0;
        while(i > 0){
            s += data[i];
            i -= (i & -i);
        }
        return s;
    }
};

template<class T>
long long int inversion(const vector<T> &a){
    vector<T> b = a;
    sort(b.begin(), b.end());
    b.erase(unique(b.begin(), b.end()), b.end());

    long long int num = 0;
    BIT bit;
    bit.init(a.size());

    for(int i=0; i<a.size(); i++){
        int pos = lower_bound(b.begin(), b.end(), a[i]) - b.begin() + 1;
        num += bit.sum(a.size()) - bit.sum(pos);
        bit.add(pos,1);
    }
    return num;
}

