const ll big = 10000000;

int RS[100010], A[100010], N;
int seg[262144];
vector<pair<int,int>> RV;

int RSQ(int s, int t, int k = 1, int l = 0, int r = (1 << 17) - 1) {
	if (t < l || r < s)return 0;
	if (s <= l && r <= t) {
		return seg[k];
	}

	int lv = RSQ(s, t, k * 2, l, (l + r) / 2);
	int rv = RSQ(s, t, k * 2 + 1, (l + r) / 2 + 1, r);
	return lv + rv;
}

void upd(int x) {
	x += (1 << 17);
	seg[x]++;x /= 2;
	while (x) {
		seg[x] = seg[x * 2] + seg[x * 2 + 1];
		x /= 2;
	}
	return;
}

ll f(int x) {
	for (int i = 0;i < (1 << 18);i++)seg[i] = 0;

	for (int i = 0;i < N;i++) {
		if (A[i] < x)
			RS[i] = -1;
		else
			RS[i] = 1;
	}

	for (int i = 1;i < N;i++) {
		RS[i] += RS[i - 1];
	}

	RV[0] = { 0,0 };
	for (int i = 1;i <= N;i++)RV[i] = { RS[i - 1],i };
	sort(all(RV));
	ll cnt = 0;
	for (int i = 0;i <= N;i++) {
		upd(RV[i].second + 1);
		cnt += RSQ(0, RV[i].second);
	}
	return cnt;
}

