        tre[pos] += val;
        pos += lowbit(pos);
    }
    return;
}

long long query(int pos) {
    long long sum = 0;
    while (pos > 0) {
        sum += tre[pos];
        pos -= lowbit(pos);
    }
    return sum;
}

long long check(int val) {
    memset(tre, 0, sizeof(tre));
    long long ans = 0;
    for (int i = 1; i <= n; i++) {
        if (a[i] < val) sub[i].val = -1;
        else sub[i].val = 1;
        sub[i].val += sub[i - 1].val;
        sub[i].loc = i;
    }
    sort(sub + 1, sub + n + 1, cmp);
    for (int i = 1; i <= n; i++) {
        add(sub[i].loc, 1);
        ans += query(sub[i].loc - 1);
        if (sub[i].val >= 0) ans++;
    }
    return ans;
}

