int leaf(int n) {
  int a=1;
  while(a<n) a *= 2;
  return a;
}


struct RSQ {

  vector<int> value;

  RSQ(int n) : value(0) {
    int ct = leaf(n)*2-1;
    rep(i,0,ct) value.pb(0); // 全部0
  }

  void update(int i, int x) { // i 番目の葉の値に x を足す
    int N = (value.size()+1)/2;
    i += N - 1; // i 番目の葉のノード番号
    value[i] += x;
    while (i > 0) {
      i = (i - 1) / 2; // ノード i の親ノードの番号に変える
      value[i] = value[i * 2 + 1]+value[i * 2 + 2]; // 左右の子のsumを計算しなおす
    }
    return;
  }

  int at(int i) { //i番目の要素にアクセス
    int N = (value.size()+1)/2;
    return value[i-1+N];
  }

  int RSQ2(int a, int b, int k, int l, int r) {
    // [a, b) の区間に対するクエリについて
    // ノード k （区間 [l, r) 担当）が答える
    if (r <= a || b <= l) return 0; // 区間が被らない場合は0を返す
    if (a <= l && r <= b)
      return value[k]; // ノード k の担当範囲がクエリ区間 [a, b)に完全に含まれる
    else {
      int c1 = RSQ2(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子に値を聞く
      int c2 = RSQ2(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子に値を聞く
      return c1+c2; // 左右の子の値の sum を取る
    }
  }

  int rsum(int a,int b) {
    int N = (value.size()+1)/2;
    return RSQ2(a,b+1,0,0,N);
  }

  /*　使い方まとめ　*/

     /*

     RSQ myvec(n) // 宣言 nは必要な要素数
     myvec.update(i,k) // 配列のi番目に要素kを足す(更新ではないことに注意)
     myvec.at(i) // 配列のi番目にアクセス(0-index)
     myvec.rsum(i,j) // 配列の[i,j]の範囲の和を返す(0-index)

     */

};
int n;
Vi a;
int model;

int f(int k){
  RSQ v(200010); // 100005が基準

  int now = 100005;
  rep(i,0,n){
    if(a[i] < k) now++;
    else now--;
    v.update(now,1);
  }

  now = 100005;
  int ct = 0;

  rep(i,0,n){
    ct += v.rsum(now+1,200008);
    if(a[i] < k) {
      now++;
    }
    else {
      now--;
    }
    v.update(now,-1);
  }

  return ct;
}

bool check(int mid){ // ([...,0,0,0,"1",1,1,...])
  if(model < f(mid)) return true;
  else return false;
}

int binary(){
  int L = 0,R = 1000000010; // [L,R]の範囲内に解
  int mid = (L+R)/2;

  while(L<R){
    if(check(mid)) {
      R = mid;
    }
    else {
      L = mid+1;
    }
    mid = (L+R)/2;
  }

  return mid-1;
}

