void merge(ll a[],ll l,ll r){
	if(l==r){
		return;
	}
	ll mid=(l+r)/2;
	merge(a,l,mid);
	merge(a,mid+1,r);
	ll x=l;
	ll y=mid+1;
	ll id=l;
	while(x<=mid && y<=r){
		if(a[x]>a[y]){
			tmp[id++]=a[y];
			ans+=mid-x+1;
			y++;
		}
		else{
			tmp[id++]=a[x];
			x++;
		}
	}
	while(x<=mid){
		tmp[id++]=a[x++];
	}
	while(y<=r){
		tmp[id++]=a[y++];
	}
	for(ll i=l;i<=r;i++){
		a[i]=tmp[i];
	}
}
