#define ll long long

struct segtree{
    int size;
    vector<int> dat;
    int init = 0;

    segtree (int N) {
        size = 1;
        while (size < N) size *= 2;
        dat = vector<int>(2*size-1, init);
    }

    int op(int a, int b) {
        return a+b;
    }

    void update(int i, int x) { 
        i += size-1;
        dat[i] += x;
        while (i > 0) {
            i = (i-1)/2;
            dat[i] = op(dat[2*i+1], dat[2*i+2]);
        }
        return;
    }

    int query(int a, int b) {
        return query(a, b, 0, 0, size);
    }


    int query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return init;
        if (a <= l && r <= b) return dat[k];
        int lv, rv;
        lv = query(a, b, 2*k+1, l, (l+r)/2);
        rv = query(a, b, 2*k+2, (l+r)/2, r);
        return op(lv, rv);
    }
};


int main(){
    int N;
    cin >> N;
    vector<int> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];
    ll l = 0, r = 1e9+1;

    while (r-l > 1) {
        ll c = (l+r)/2;
        segtree st(N*2+1);
        int t = N;
        st.update(t, 1);
        ll psec = 0;
        for (int i = 0; i < N; i++) {
            if (a[i] < c) t--;
            else t++;
            psec += st.query(0, t+1);
            st.update(t, 1);
        }
        if (psec*2 >= (ll)N*(N+1)/2) l = c;
        else r = c;
    }

    cout << l << endl;
    return 0;
}

