}

int count(vector<int> a, int m){
    vector<int> b(a.size());
    vector<int> c(a.size()+1,0);
    vector<int> d(a.size()+1,0);

    REP(i,a.size()){
        if(a[i]<=m) b[i] = 1;
        else b[i] = 0;

        c[i+1] = c[i] + b[i];
        d[i+1] = 2*c[i+1] - (i+1);
    }

    reverse(ALL(d));
    return inversion(d);
}

