DWORD N;
vector<DWORD> vNumArray;
vector<DWORD> vConvArray;
vector<DWORD> vCumSum;
vector<DWORD>	vBit;

void ConvertArray(DWORD x)
{

	for (int idx = 0; idx < vConvArray.size(); idx++) {
		DWORD sum = 0;

		if (vNumArray[idx] >= x) vConvArray[idx] = 1;
		else										 vConvArray[idx] = -1;

		if (idx == 0) sum = 0;
		else					sum = vCumSum[idx - 1]; 
		vCumSum[idx] = sum + vConvArray[idx]; 
	}

}

void add(DWORD i, DWORD x)
{
	while(i <= N) {
		vBit[i] += x;
		i += i & -i; 
	}
}

DWORD sum(DWORD i)
{
	DWORD s = 0;

	while (i > 0) {
		s += vBit[i];
		i -= i & -i;
	}

	return s;
}



DWORD CalcInverse(void)
{
	DWORD inverse_num = 0;

	vBit.resize(2*N);	
	for (int i = 0; i < N; i++) {
		inverse_num += i - sum(vCumSum[i]+ 2*N);
		add(vCumSum[i] + 2*N, 1);
	}
	return inverse_num;
}

bool Judge(DWORD x) 
{
	DWORD inverse_num;
	ConvertArray(x);
	inverse_num = CalcInverse();

	return (N*(N+1)/2 - inverse_num) >= (N*(N+1)/2+1)/2;
}

DWORD BinarySearch()
{
	DWORD lb = 0, ub = INF;

	while (ub - lb > 1) {
		DWORD mid = (lb + ub) / 2;
		if (Judge(mid)) lb = mid;
		else						ub = mid;

	}

	return ub;
}

