template<typename T>
class Bit {
public:
    Bit(int n): ar(n+1) {}
    T operator [](std::size_t i) {
        T res{};
        while (i > 0) {
            res += ar[i];
            i = i & (i - 1);
        }
        return res;
    }

    void update(int i, T val) {
        while ((unsigned int)i < ar.size()) {
            ar[i] += val;
            i += i & (-i);
        }
    }
private:
    std::vector<T> ar;
};

bool valid(int x, vector<int>& vals) {
    int cur = 0;
    Bit<int> bit(vals.size() * 2 + 2);
    unsigned long long res = 0;
    for (auto val: vals) {
        if (val >= x) cur += 1;
        else cur -= 1;
        res += bit[vals.size() + 1 + cur];
        bit.update(vals.size() + 1 + cur, 1);
    }
    return res * 2 >= vals.size() * (vals.size() - 1) / 2;
}

