long long solve(long long p) {
    vector<long long> k(2*n+1);
    long long sum=n;
    k[sum]=1;
    long long add=1;
    long long res=0;
    for (int i=1;i<=n;i++) {
        if(s[i]<p) {
            add-=k[sum];
            sum--;
        }
        else {
            sum++;
            add+=k[sum];
        }
        res+=add;
        k[sum]++;
        add++;    
    }
    return res;
}

