template<typename Up, typename Eval, typename T>
class SegmentTree{
private:
    const Up up; // 更新関数
    const Eval eval; // 評価関数
    vector<T> seg;
    int sz = 1;
    T unit;
public:
    explicit SegmentTree(int n,Up&& f,Eval&& g,T unit=0)noexcept: up(std::forward<Up>(f)), eval(std::forward<Eval>(g)), unit(unit){
        while (sz < n) sz <<= 1;
        seg.resize(sz * 2, unit);
    }
    void update(int k, T v) {// k 番目の値をup(seg[k],v)にする
        k += sz - 1;
        seg[k] = up(seg[k], v);
        while (k > 0) {
            k = (k - 1) / 2;
            seg[k] = up(seg[2 * k + 1], seg[2 * k + 2]);
        }
    }
    void set(const int& k, const T& x) {//左からk番目の葉にxを代入する
        seg[sz - 1 + k] = x;
    }
    T get(const int& k) {//左からk番目の葉を得る
        return seg[sz - 1 + k];
    }
    T query(int a, int b) {//[a,b)のupの合成を求める
        int k = 0, l = 0, r = sz;
        return query(a, b, k, l, r);
    }
    T query(int a, int b, int k, int l, int r) {//[a,b)のupの合成を求める(a,b,0,0,sz)のように使う
        if (r <= a || b <= l) {
            return unit;
        }
        if (a <= l && r <= b) {
            return seg[k];
        }
        else {
            T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return up(vl, vr);
        }
    }
};

template<typename Up,typename Eval,typename T>
static inline SegmentTree<Up, Eval, T>
makeSegmentTree(int n,Up&& up,Eval&& eval,T unit=0) noexcept {
    return SegmentTree<Up,Eval,T>(n,std::forward<Up>(up),std::forward<Eval>(eval),unit);
}

template<typename T>
int64_t inversion_number(vector<T>& a) { // i<jかつa_i>a_jとなる(i,j)の数
    auto up = [](T& a,T b){
        return a + b;
    };
    auto eval = [](T& a,T b){
        return a + b;
    };
    int n = (int)a.size();
    int64_t res = 0;
    using p = pair<T,int>;
    vector<p> c(n);
    for (int i = 0; i < n; ++i) {
        c[i].first = a[i];
        c[i].second = i;
    }
    sort(c.begin(), c.end());
    //SegmentTree<decltype(up),decltype(eval),T> st(n, std::move(up),std::move(eval), 0);
    auto st = makeSegmentTree(n,up,eval,0);
    int k = 1;
    for (int i = 0; i < n; ++i) {
        st.update(c[i].second, k);
        res += st.query(c[i].second+1, n);
    }
    return res;
}


