struct FenwickTree{
    std::vector<int> data;
    int numNodes;

    FenwickTree(int n) : data(n + 1, 0), numNodes(n) {}

    void add(int k, int v){
        k += 1;
        while(k > 0){
            data[k] += v;
            k -= k & -k;
        }
    }

    int sum(int k){
        k += 1;
        int s = 0;
        while(k <= numNodes){
            s += data[k];
            k += k & -k;
        }
        return s;
    }
};

int N;
int A[100100];

bool can(int x){ // m の中央値が x 以上か判定する
    std::vector<int> B(N + 1);

    B[0] = 0;

    for(int i=1;i<=N;++i){
        if(A[i] >= x){
            B[i] = +1;
        }else{
            B[i] = -1;
        }

        B[i] += B[i - 1];
    }

    std::vector<int> C(B.begin() + 1, B.end());
    std::sort(C.begin(), C.end());
    C.erase(std::unique(C.begin(), C.end()), C.end());

    FenwickTree t[2] = {{(int)C.size()}, {(int)C.size()}};

    for(int i=1;i<=N;++i){
        t[i & 1].add(std::lower_bound(C.begin(), C.end(), B[i]) - C.begin(), +1);
    }

    ll y = 0;

    for(int i=1;i<=N;++i){
        int i1 = std::lower_bound(C.begin(), C.end(), B[i - 1] + 1) - C.begin(),
            i2 = std::lower_bound(C.begin(), C.end(), B[i - 1]) - C.begin(),
            i3 = std::lower_bound(C.begin(), C.end(), B[i]) - C.begin(),
            v1 = t[i & 1].sum(i1),
            v2 = t[!(i & 1)].sum(i2);

        y += v1;
        y += v2;

        t[i & 1].add(i3, -1);
    }

    ll m = 1ll * N * (N + 1) / 2;

    return y >= (m + 1) / 2;
}

