// Binary Indexed Tree (Fenwick Tree)
template <typename T>
struct BIT {
    int n,p;
    vector<T> d;
    BIT(int n=0) :n(n), d(n+1) {
        p = 1;
        while(p < n)p *= 2;
    }
    //更新
    void add(int i,T x=1){
        for(i++;i <= n;i += i&-i) d[i] += x;
    }
    //[0,i)の和
    T sum(int i){
        T res = 0;
        for(;i;i -= i&-i) res += d[i];
        return res;
    }
    //[l,r)の和
    T sum(int l,int r){ return sum(r) - sum(l);}
    //v0+v1+…vx>=mを満たすmin(x)を返す
    int lower_bound(T w){
        if(w <= 0) return 0;
        T x = 0;
        for ( int i=p;i;i/=2){
            if(i+x <=n &&d[i+x] < w){
                w -= d[i+x];
                x += i;
            }
        }
        return x;
    }
};

int main(){
    INT(n);
    VEC(int, a, n);
    fin(n == 1, a[0]);
    int ng = 1e9, ok = 0;
    auto judge = [&](int mid){
        int sum, num, cnt;
        sum = num = cnt = 0;
        BIT<int> BT(2 * n + 10);
        const int upper = n;
        BT.add(upper);
        REP(i, n){
            num = (a[i] >= mid ? 1 : -1);
            sum += num;
            cnt += BT.sum(0, sum + upper + 1);
            BT.add(sum + upper);
        }
        return cnt < (n + 1) * n / 4;
    };
    while(abs(ok - ng) > 1){
        int mid = (ok + ng) / 2;
        if(judge(mid)) ng = mid;
        else ok = mid;
    }
    print(ok);
}

