const ll INF=1e9+1;

struct BIT {
   vector<ll> bit;
   ll n;
   BIT(ll n=0):n(n),bit(n+1){}

   // 一点更新です
   void add(ll x, ll w) {
     for (x++; x <= n; x += x & -x) bit[x] += w;
   }

   // 1~Nまでの和を求める。
   ll sum(ll x) {
     ll ret = 0;
     for (x++; x > 0; x -= x & -x) ret += bit[x];
     return ret;
   }
 };

int main()
{
    ll n;
    cin >> n;
    vector<ll> a(n);
    rep(i,n){
        cin >> a[i];
    }
    ll le=0,ri=INF;
    while(ri-le>1){
        ll mid=(ri+le)/2;
        vector<ll> v(n),s(n);
        rep(i,n){
            if(a[i]>=mid){
                v[i]=1;
            }
            else{
                v[i]=-1;
            }
        }
        rep(i,n){
            if(i){
                s[i]=s[i-1]+v[i];
            }
            else{
                s[i]=v[i];
            }
        }
        ll total=0;
        BIT b(n+n+10);  // これまでの数字がどんな風になってるのかをメモる為のBIT
        b.add(n+1,1LL);
        for (ll i = 0; i < n; i++) {
            total += i+1- b.sum(s[i]+n+1); // BITの総和 - 自分より左側 ＝ 自分より右側
            b.add(s[i]+n+1, 1LL); // 自分の位置に1を足す
            cout << total << " ";
        }
        if((n+1)*n/2-total>=(n+1)*n/4) le=mid;
        else ri=mid;
        cout << mid << " " << total << endl;
    }
    cout << le << endl;
    return 0;
}

