template<typename T>
struct BIT {
  std::vector<T> bit;

  BIT(int n) {
    n++;
    ll i = 1;
    while(i < n) i <<= 1;
    bit.assign(++i, 0);
  }

  //Sum of [0, k]
  T sum(int k) {
    T s = 0;
    for(++k; k > 0; k -= k & -k) s += bit[k];
    return s;
  }

  void add(int k, T x) {
    for(++k; k < bit.size(); k += k & -k) bit[k] += x;
  }
};

