vector<int> shrink(vector<ll> a){
    vector<ll> val=a;
    vector<int> ret(a.size());
    sort(ALL(val));
    val.erase(unique(ALL(val)),val.end());
    rep(i,a.size()){
        int id=lower_bound(ALL(val),a[i])-val.begin();
        ret[i]=id+1;
    }
    return ret;
}

ll outen(vector<ll> a){
    vector<int> resh=shrink(a);
    ll OUTEN=0;
    BIT<int> b(1001001);
    rep(i,resh.size()){
        OUTEN+=i-b.sum(resh[i]);
        b.add(resh[i],1);
    }
    return OUTEN;
}

