class BIT {
    // ATTENTION: this tree is one-indexed
    std::vector<int> tree;
    int MAX_SIZE;

public:
    BIT(int max) : tree(max), MAX_SIZE(max) {}
    void add(int idx, int val) {
        for (int x = idx; x < MAX_SIZE; x += x & -x) tree[x] += val;
    }
    int sum(int idx) {
        int ret = 0;
        for (int x = idx; x > 0; x -= x & -x) ret += tree[x];
        return ret;
    }
};

int n;
int thre;

bool tf(vec a, int val) {
    vec v(n);
    rep (i, n)
        v[i] = (a[i] >= val) ? 1 : -1;

    For(i, 1, n - 1) v[i] = v[i - 1] + v[i];

    BIT bit(n * 4 + 1);
    int res = 0;
    bit.add(n * 2, 1);
    rep (i, n) {
        res += bit.sum(v[i] + n * 2);
        bit.add(v[i] + n * 2, 1);
    }
    return res >= thre;
}

