    }
}

bool C(int x)
{
    int bit[200010] = {0};
    int s[N + 1] = {0};
    int res = 0;
    for(int i = 0; i < N; i++){
        if(a[i] >= x){
            s[i] = 1;
            res++;
        }
        else s[i] = -1;
        if(i > 0)s[i] += s[i - 1];
    }
    for(int i = 0; i < N; i++){
        res += sum(N + 1 + s[i], bit);
        add(N + 1 + s[i], 1, bit);
    }
    return (res >= (N * (N + 1) / 2 + 1) / 2);
}

int binary(int lb, int ub)
{
    for(int i = 0; i < 64; i++){
        int mid = (ub + lb) / 2;
        //printf("lb:%lld ub:%lld mid:%lld\n", lb, ub, mid);
        if(C(mid))lb = mid;
        else ub = mid;
    }
    return lb;
}

