  int M = (N*(N+1))/2;
  int judge = M/2+1;

  int left = 0; int right = 1LL << 60;

  while( right - left > 1 ){ 

    int mid = left+(right-left)/2;

    vector<int> B(N);
    for(int i = 0; i < N; i++){ 
      if(A[i] >= mid ){ B[i] = 1;} else{ B[i] = -1;}
