    vector<int> T(N);
    for(int i = 0; i < N; i++){ T[i] = S[i];}

    sort(T.begin(),T.end()); vector<int> use(N);

    for(int i = 0; i < N; i++){ 
      int itr = lower_bound(T.begin(),T.end(),S[i])-T.begin();
