class BITree {//1-index
	int N;
	vector<LL> bit;
public:
	BITree(int n) {
		N = n;
		bit = vector<LL>(N + 1, 0);//1-index
	}
	void add(int a, LL w) {//aにwを足す
		if (a <= 0 || N < a) return;//a:[1,N]
		for (int i = a; i <= N; i += i & -i) {
			bit[i] += w;
		}
	}
	LL sum(int a) {//[1,a]の和,a:[1,N]
		/*
		1番目からa番目までの和、1-index
		*/
		LL ret = 0;
		if (a > N) a = N;
		for (int i = a; i > 0; i -= i & -i) {
			ret += bit[i];
		}
		return ret;
	}
};

bool check(LL mid) {
	vector<int> B(N,0);

	//1,-1変換
	for (int i = 0; i < N; ++i) {
		if (A[i] >= mid) {
			B[i] = 1;
		}
		else {
			B[i] = -1;
		}
	}

	//累積和
	vector<int> C(N + 1, 0);
	LL Min = 0;
	for (int i = 0; i < N; ++i) {
		C[i + 1] = C[i] + B[i];
		if (Min > C[i + 1]) {
			Min = C[i + 1];
		}
	}

	if (Min <= 0) {
		for (int i = 0; i <= N; ++i) {
			C[i] -= (Min-1);
		}
	}
	LL MAX = 0;
	for (int i = 0; i <= N; ++i) {
		if (MAX < C[i]) {
			MAX = C[i];
		}

	}

	//Cの転倒数
	LL ans = 0;
	BITree bit(MAX + 1);//
	for (int i = 0; i <= N; ++i) {
		ans += bit.sum((int)C[i]);
		bit.add((int)C[i], 1);
	}
	//ans;


	if (ans >= (N*(N+1)/4) ) {
		return true; 
	}
	return false;
}
void solve() {
	cin >> N;
	A.resize(N);
	for (int i = 0; i < N; ++i) {
		cin >> A[i];
	}
	if (N == 1) {
		cout << A[0] << endl;
		return;
	}
	if (N == 2) {
		int ret = A[0];
		if (A[0] < A[1]) {
			ret = A[1];
		}
		cout << ret << endl;
		return;
	}
	/////////////////
	LL L, R,mid;
	L = 1;
	R = INF;
	while (L + 1 < R) {
		mid = (L + R) / 2;
		if (check(mid)) {
			L = mid;
		}
		else {
			R = mid;
		}
	}
	cout << L << endl;
}

