const int N = 1e5 + 5;
ll a[N], st[N * 10], b[N], sum[N];
void upd(ll k, ll l, ll r, ll x, ll v){
        if (x > r || x < l) return;
        if (l == r){
                st[k] = st[k] + v;
                return;
        }
        ll mid = (l + r) >> 1;
        upd(k << 1, l, mid, x, v);
        upd(k << 1 | 1, mid + 1, r, x, v);
        st[k] = st[k << 1] + st[k << 1 | 1];
}
ll get(ll k, ll l, ll r, ll x, ll y){
        if (x > r || y < l) return 0;
        if (x <= l && y >= r) return st[k];
        ll mid = (l + r) >> 1;
        return get(k << 1, l, mid, x, y) + get(k << 1 | 1, mid + 1, r, x, y);
}
