bool canDoit(int *in,int base,int n) {
  long long num = ( (( (ll)n*(n+1))/2) + 1)/2;
  for(int i=1;i<=n;++i) {
    if(in[i]<base) {
      convert[i] = -1;
    } else {
      convert[i] = 1;
    }
    convert[i] += convert[i-1];
  }
  for(int i=1;i<N;++i) {
    pen[i] = 0;
  }
  for(int i=n;i;--i) {
    update(convert[i] + BASE,1);
    int x = convert[i-1] + BASE - 1;
    num -= n-i +1 - query(x);
  }
  if(num<=0) {
    return true;
  }
  return false;
}
