inline int lowbit(int x) { return x & -x; } 
inline void add(int c[], int p) {
	for(; p<=m; p+=lowbit(p))
		c[p]++;
}
inline int query(int c[], int p) {
	int res = 0;
	for(; p; p^=lowbit(p))
		res += c[p];
	return res;
}

bool judge(int mid) {
	int i, j, k;
	int64 ans = 0;

	memset(c, 0, sizeof(c));

	sum[0][0] = n + 2;
	for(i=1; i<=n; i++) {
		j = i >> 1;
		k = i & 1;
		sum[j][k] = sum[j - !k][!k] + (a[i] <= mid);
	}

	for(i=0; sum[i][0]; i++) {
		for(j=0; j<=1 and sum[i][j]; j++) {
			ans += query(c[j], sum[i][j] - i - 1);
			ans += query(c[!j], sum[i][j] - i - j);
			if(j == 1)
				ans += sum[i][1] - sum[i][0];
		}
		for(j=0; j<=1 and sum[i][j]; j++)
			add(c[j], sum[i][j] - i);
	}

	return ans >= (n + 1ll) * n / 4 + 1;
}

