void Merge(int l, int mid, int r)
{
	if(l == r) return;
	int p = l, q = mid+1, pos = l;
	while(p <= mid && q <= r){
		if(sum[p] < sum[q]) xp[pos++] = sum[p++];
		else{
			tmp += (p-l);
			xp[pos++] = sum[q++];
		}
	}
	while(p <= mid) xp[pos++] = sum[p++];
	while(q <= r) tmp += (p-l), xp[pos++] = sum[q++];
	for(int k = l; k <= r; k++)
		sum[k] = xp[k];
}

