    for(int i = 0; i < v.size(); i++)
    {
        sum += bit.sum(-v[i].se + 1);
        bit.add(-v[i].se + 1, 1);
    }

    if(N * (N + 1) / 2 < sum * 2)return true;
    return false;
}

