    hash_map<lint,lint> bit;
    lint n;
    BIT(lint n):n(n){
        //bit.resize(n+1,0);
    }
    //1-indexed [1,x]-sum
    lint sum(lint x){
        lint res=0;
        for(lint i=x;i>0;i-=i&-i)res+=bit[i];
        return res;
    }
    //1-indexed [x,y]-sum
    lint sum(lint x,lint y){
        return sum(y)-sum(x);
    }
    //1-indexed
    void add(lint x,lint val){
        x++;
        if(x>n)return;
        for(lint i=x;i<=n;i+=i&-i)bit[i]+=val;
    }
};
lint bs(lint mn,lint mx,auto func){
    mn--;
    mx++;
	while(mx-mn>1){
		lint mid=(mn+mx)/2;
		if(!func(mid))mx=mid;
		else mn=mid;
	}
    return mn;
}

