long long count_inv(vector<ll> &C, ll l, ll r){
    if(r - l == 1) return 0;
    ll m = (l+r)/2;
    long long ret = count_inv(C,l,m) + count_inv(C,m,r);
    vector<int> L, R;
    for(int i = l; i < r; ++i){
        if(i < m) L.push_back(C[i]);
        else R.push_back(C[i]);
    }
    ll N = L.size(), M = R.size(), cur = l, j = 0;
    for(int i = 0; i < N; ++i){
        while(j < M and R[j] < L[i]) C[cur++] = R[j++];
        ret += j;
        C[cur++] = L[i];
    }
    return ret;
}


