const ll MOD = 1000000007;
const ll HIGHINF = (ll)1e18;

ll merge(vll &a, ll n, ll left, ll mid, ll right) {
    ll cnt = 0;
    ll n1 = mid - left;
    ll n2 = right - mid;
    vll a1(n1 + 1), a2(n2 + 1);
    REP(i, n1) a1[i] = a[left + i];
    REP(i, n2) a2[i] = a[mid + i];
    a1[n1] = a2[n2] = HIGHINF;
    ll i = 0, j = 0;
    rep(k, left, right) {
        if (a1[i] <= a2[j]) {
            a[k] = a1[i];
            i++;
        } else {
            a[k] = a2[j];
            j++;
            cnt += n1 - i;
        }
    }
    return cnt;
}

ll mergeSort(vll &a, ll n, ll left, ll right) {
    if (left + 1 < right) {
        ll mid = (left + right) / 2;
        ll v1 = mergeSort(a, n, left, mid);
        ll v2 = mergeSort(a, n, mid, right);
        ll v3 = merge(a, n, left, mid, right);
        return v1 + v2 + v3;
    } else return 0;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n; cin >> n;
    vll a(n); REP(i, n) cin >> a[i];
    if (n == 1) {
        cout << a[0] << '\n';
        return 0;
    }
    ll low = 1, high = HIGHINF / 2 + 1;
    ll bound = (((1 + n) * n / 2) + 1) / 2;  // bound 個以上あれば OK
    while (low < high) {
        ll mid = (low + high) / 2;
        vll acca(n + 1, 0);
        REP(i, n) acca[i + 1] = acca[i] + (a[i] >= mid ? 1 : -1);
        ll sw = mergeSort(acca, n + 1, 0, n + 1);
        cout << mid << ' ' << sw << '\n';
        if (bound >= sw) low = mid + 1;
        else high = mid;
    }
    cout << low - 1 << '\n';
    return 0;
}

