struct S {
  std::multiset<size_t> set;
  std::multiset<size_t>::const_iterator it;

  S(size_t a)
    : set({a})
    , it(set.cbegin()) {}

  void insert(size_t a) {
    set.insert(a);

    if (set.size() % 2 == 0) {
      if (a >= *it)
        std::advance(it, 1);
    } else {
      if (a < *it)
        std::advance(it, -1);
    }
  }

  size_t median() const {
    return *it;
  }
};

int main() {
  size_t N;

  std::cin >> N;

  std::vector<S> Sets;
  Sets.reserve(N);

  size_t a;
  std::cin >> a;

  Sets.push_back(S(a));

  S Meds(a);

  for (size_t i=1; i<N; i++) {
    std::cin >> a;
    for (auto& s: Sets) {
      s.insert(a);
      Meds.insert(s.median());
    }

    Sets.push_back(S(a));
    Meds.insert(a);
  }

  std::cout << Meds.median() << std::endl;

  return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define rep(i, n) for (ll i = 0; i < ll(n); i++)

struct BIT {
    vector<ll> bit;
    int N;

    BIT(int N) : bit(vector<ll>(N + 1, 0)), N(N) {}

    // return sum in [0, `i`] in log(n)
    ll sum(int i) {
        if (!i) return 0;
        return bit[i] + sum(i - (i & -i));
    }

    // add `x` at `i`
    void add(int i, ll x) {
        if (i > N) return;
        bit[i] += x;
        add(i + (i & -i), x);
    }
};

int main() {
    int n;
    cin >> n;
    vector<ll> a(n);
    rep(i, n) cin >> a[i];

    ll l = 1, r = 1e9 + 7;
    ll threshold = n * (n + 1) / 2;
    threshold = (threshold + 1) / 2;
    while (r - l > 1) {
        ll mid = (r + l) / 2;
        ll score = 0;
        BIT fwt(200200);

        // to prevent a negative index
        ll pref_sum = 1e5;
        // the pref_sum of an empty array is always 0
        fwt.add(pref_sum, 1);

        rep(i, n) {
            pref_sum += (mid <= a[i] ? 1 : -1);
            score += fwt.sum(pref_sum);
            fwt.add(pref_sum, 1);
        }
        if (score >= threshold) {
            l = mid;
        } else {
            r = mid;
        }
    }
    cout << l << endl;
}

