template<class T>
class BIT{
  ll N;
  std::vector<T> bit;
public:
  BIT(ll n){
    N=n;
    bit.resize(N+1,0);
  }

  //i番目の要素にwを追加
  void add(ll i,T w){
    for(ll x=i;x<=N;x+=x&-x){
      bit[x]+=w;
    }
  }

  //[1,i]の和を求める
  T sum(ll i){
    ll ret=0;
    for(ll x=i;x>0;x-=x&-x){
      ret+=bit[x];
    }
    return ret;
  }
};


