    for(ll i=0;i<N;i++){
      tree.add(sum.at(i)+N+1,1);
      count+=tree.sum(sum.at(i)+N+1);
    }

    if(count>=((ll)N*((ll)N+1)/2-1)/2+1){
      ok=x;
    }else{
      ng=x;
    }
  }

  cout<<ok<<endl;
}

