struct BIT {
    ll N;
    vector<ll> bit;
    BIT(ll N):N(N) {
        /* BITは[1..N]で扱う */
        bit.resize(N + 1, 0);
    }

    void add(int x, ll val){
        while (x <= N) {
            bit[x] += val;
            x += x & -x;
        }
    }

    ll sum(int x){
        ll ret = 0;
        while (x) {
            ret += bit[x];
            x &= (x - 1);
        }
        return (ret);
    }
};
ll solve(){
    ll res = 0;
    ll N; cin >> N;
    vector<ll> a(N); for(auto& in:a) cin >> in;

    vector<ll> ta = a;
    sort(ta.begin(),ta.end());
    ll l = 0,r = N;

    ll M = N*(N+1)/2;
    ll HM = (M+1)/2;
    while(r-l>1){
        ll m = (r+l)/2;
        ll ma = ta[m];
        vector<ll> cusum(N+1);
        for(int i = 0; i < N;i++){
            cusum[i+1] = cusum[i];
            if(a[i]>=ma) cusum[i+1]++;
            else cusum[i+1]--;
        }

        ll sum = 0;
        BIT bit(2*N);

        for(int i = 0; i <= N;i++){
            sum += bit.sum(cusum[i]+N);
            bit.add(cusum[i]+N,1);
        }
        if(sum >= HM){
            l = m;
        }else{
            r = m;
        }
    }
    res = ta[l];
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    cout << solve() << endl;
    return 0;
}

