bool cond(const int v, const int N) {
    vector<int> bs(N);
    for (int i = 0; i < N; i++) {
        if (as[i] < v) {
            bs[i] = 0;
        } else {
            bs[i] = 1;
        }
    }

    vector<int> ss(N + 1, 0);
    for (int i = 0; i < N; i++) {
        ss[i + 1] = ss[i] + bs[i];
    }

    auto f = [](int x, int y) {
        return x + y;
    };
    SegmentTree<int, int> *st = new SegmentTree<int, int>(2 * N, 0, f);
    ll acc = 0;
    for (int i = 0; i <= N; i++) {
        int x = 2 * ss[i] - i + N; // 0 <= ss[i] - i + N <= N
        // printf("x: %d, += %d\n", x, st->query(0, x + 1));
        acc += st->query(0, x + 1);

        int cnt = st->query(x, x + 1);
        st->update(x, cnt + 1);
    }

    const ll lim = ((ll(N) * (ll(N) + 1LL) / 2LL) + 2LL - 1LL) / 2LL;
    // printf("v: %d, cnt: %d, lim: %d\n", v, acc, lim);
    return acc >= lim;
}

int solve(const int N) {
    int left = 0, right = MAX_A + 1, mid;
    while (right - left > 1) {
        mid = left + (right - left) / 2;
        if (cond(mid, N)) {
            left = mid;
        } else {
            right = mid;
        }
    }
    return left;
}

