    void init(ll n_input)
    {
        n = n_input + 1;
        v.resize(n + 1, 0);
    }
    // 0番目からk-1番目までの和
    ll sum(ll k)
    {
        ll res = 0;
        for (ll i = k - 1; i >= 0; i = (i & (i + 1)) - 1)
        {
            res += v[i];
        }
        return res;
    }
    // i番目からj番目までの区間の和
    ll sum_between(ll i, ll j)
    {
        return i <= j ? sum(j) - sum(i - 1) : 0;
    }
    // k番目の要素にxを足す
    void add(ll k, ll x)
    {
        for (ll i = k; i < n; i |= i + 1)
        {
            v[i] += x;
        }
    }
};

