#define MAX_N 400010
class BIT_for_inversion {
	// Implementation of a Binary Indexed Tree (Fennwick Tree)
public:
	/*BIT(std::vector<int> list) {
		// Initialize BIT with list in O(n*log(n))
		m_array = std::vector<int>(list.size() + 1, 0);
		for (int idx = 0; idx < list.size(); idx++) {
			update(idx, list[idx]);
		}
	}*/

	BIT_for_inversion(std::vector<int> list) {
		// Initialize BIT with list in O(n)
      array_for_inversion = vector<int>(MAX_N,0);
      default_array = vector<int> (list.size(),0);
		for (int idx = 0; idx < list.size(); idx++) {
			default_array[idx] = list[idx];
		}
	}

	int prefix_query(int idx) const {
		// Computes prefix sum of up to the element at index idx
		int result = 0;
		for (++idx; idx > 0; idx -= idx & -idx) {
			result += array_for_inversion[idx];
		}
		return result;
	}

	int range_query(int from_idx, int to_idx) const {
		// Computes the range sum between two indices (both inclusive)
        if (from_idx == 0)
            return prefix_query(to_idx);
        else
            return prefix_query(to_idx) - prefix_query(from_idx - 1);
	}

	void update(int idx, int add) {
		// Add a value to the element at index idx
		for (++idx; idx < MAX_N; idx += idx & -idx) {
			array_for_inversion[idx] += add;
		}
	}
   long long inversion(){
      long long ans = 0;
      for(int j = 0;j < default_array.size();j++){
         ans += (long long)((j) - prefix_query(default_array[j]));
         update(default_array[j],1);
      }
      return ans;
   }
private:
   vector<int> array_for_inversion;
   vector<int> default_array;
};

