namespace Fenw {
	int f[N];

	void init() {
		fill(f, f + N, 0);
	}

	int get(int x) {
		int ans = 0;
		for (int i = x; i >= 0; i = (i & (i + 1)) - 1) {
			ans += f[i];
		}
		return ans;
	}

	void add(int x) {
		for (int i = x; i < N; i = i | (i + 1)) {
			f[i]++;
		}
	}
}

int solve_01(int n, vector<int> a) {
	vector<int> ps(n + 1);
	for (int i = 0; i < n; i++) {
		ps[i + 1] = ps[i] + a[i];
	}
	for (int i = 0; i <= n; i++) {
		ps[i] += n;
	}
	int ans = 0;
	Fenw::init();
	for (int i = 0; i <= n; i++) {
		ans += Fenw::get(ps[i] - 1);
		Fenw::add(ps[i]);
	}
	return ans;
} 

