ll merge_sort(const int l, const int r) {
	if(r <= l+1)return 0;
	ll cnt = 0;
	const int m = (l+r)/2;
	cnt += merge_sort(l, m) + merge_sort(m, r);
	// merge
	int i = l, j = m, k = 0, c = 0;
	while(i < m && j < r) {
		if(S[j] <= S[i]) {
			T[k++] = S[j++];
			c++;
		}else {
			T[k++] = S[i++];
			cnt += c;
		}
	}

	while(i < m) {
		T[k++] = S[i++];
		cnt += c;
	}
	while(j < r)T[k++] = S[j++];

	for(int t = l; t < r; ++t) S[t] = T[t-l];

	return cnt;
}

