bool check(const vector<ll>& a,ll v){
    ll n = a.size();

    // v以上のものが、半数以上あるか
    // bの部分列で、和が0以上になるなら半数以上
    vector<ll> b(a.size() + 1);
    rep(i, a.size()) b[i + 1] = a[i] >= v ? 1 : -1;

    vector<ll> c(a.size() + 1);
    rep(i, a.size()) c[i + 1] = c[i] + b[i + 1];

    //c[i] <= c[j] となるような(i,j) の組み合わせ. BITで求められる
    fenwick_tree<ll> fw(2 * n + 1);

    //中央値がv以上になるi,jの組み合わせ
    ll sum = 0;
    rep(j,n+1){
        sum += fw.sum(0,c[j] + n + 1);
        fw.add(n + c[j], 1);
    }
    // cout << sum << endl;

    bool ok = sum >= n * (n + 1) / 4;
    // ok = 1: medianはv以上が確実
    // ok = 0: medianはv未満が確実
    return ok;
}

