template <typename Tp>
class fenwick{
    std::vector<Tp> tree;
    std::size_t n;

public:
    fenwick(size_t _n) : n(_n) {
        tree.resize(n);
    }

    void add(size_t pos, Tp val){
        while(pos < n) {
            tree[pos] += val;
            pos |= (pos + 1);
        }
    }

    Tp get(size_t pos) {
        Tp v{};
        do{
            v += tree[pos];
            pos &= pos + 1;
        }while(pos-- > 0);

        return v;
    }

    Tp get(size_t left, size_t right){
        if(left == right) return {};
        else if(left == 0) return get(right - 1);
        else return get(right - 1) - get(left - 1);
    }

    Tp operator[](size_t pos){
        if(pos == 0) return get(pos);
        else return get(pos) - get(pos-1);
    }

    void modify(size_t pos, Tp val){
        Tp diff = val - this->operator[](pos);
        this->add(pos, diff);
    }
};

int64_t inv(int* begin, size_t n){
    set<int> s;
    for(int i=0;i<n;++i) s.insert(*(begin+i));
    map<int,int> mp;
    int ord = 0;
    for(int v: s){
        mp[v] = ord;
        ++ord;
    }
    vector<int> x(n), tp(n);
    for(int i=0;i<n;++i) x[i] = mp[*(begin+i)];

    fenwick<int> fw(n);
    int64_t r = 0;
    for(int i=0;i<n;++i){
        tp[i] = fw.get(0, x[i]+1);
        fw.add(x[i], 1);
        r += i - tp[i];
    }
    return r;
}

