// coordinate compression
template <typename T> struct Compress {
    map<T, int> zip;
    vector<int> unzip;

    Compress(vector<T> v) {
        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());
        for (int i = 0; i < v.size(); ++i) {
            zip[v[i]] = i;
            unzip.push_back(v[i]);
        }
    }

    int size() { return unzip.size(); }
};

// Binary Indexed Tree 1D (SumAddQuery)
template <class Abel> struct BIT1D_SumAdd {
    size_t n;
    vector<Abel> d;

    BIT1D_SumAdd(size_t n) : n(n), d(n + 1, 0) {}

    // d[1] + ... + d[i] (i : 1-indexed)
    Abel sum(size_t i) {
        Abel res = 0;
        while (i > 0) {
            res += d[i];
            i -= i & -i;
        }
        return res;
    }
    // d[i] + ... + d[j] (i,j : 1-indexed)
    Abel sum(size_t i, size_t j) { sum(j) - sum(i - 1); }

    // d[i] += x
    void add(size_t i, Abel x) {
        while (i <= n) {
            d[i] += x;
            i += i & -i;
        }
    }
};

// count the number of pair (i, j) s.t. i < j and a[i] > a[j] (or a[i] >= a[j])
int inversion_number(const vector<int>& a, bool equal = false) {
    Compress<int> comp(a);
    const size_t n = a.size();
    BIT1D_SumAdd<int> bit(comp.size());
    int res = 0;
    for (int i = 0; i < n; ++i) {
        res += i - bit.sum(comp.zip[a[i]] + 1 - equal);
        bit.add(comp.zip[a[i]] + 1, 1);
    }
    return res;
}

bool check(const vector<int>& a, int x) {
    const int N = a.size();
    vector<int> b(N + 1, 0);
    REP (i, N) {
        if (a[i] < x) b[i + 1] = -1;
        else b[i + 1] = 1;
        b[i + 1] += b[i];
    }
    int inv = inversion_number(b);
    return 4 * inv <= N * (N + 1);
}

