struct BIT {
    vector<LL> bit;
    int M;

    BIT(int M) : bit(vector<LL>(M + 1, 0LL)), M(M) {}

    LL sum(int i) {
        if (!i) return 0;
        return bit[i] + sum(i - (i & -i));
    }

    void add(int i, LL x) {
        if (i > M) return;
        bit[i] += x;
        add(i + (i & -i), x);
    }
};


void solve(long long N, std::vector<long long> a){
    VLL sort_a(a.size(), 0LL);
    copy(ALL(a), sort_a.begin());
    sort(ALL(sort_a));

    int l = 0;
    int r = a.size()-1;
    LL t = ceil((N * (N - 1)) / 2LL / 2.0);
    while(l<r){
        int m = (l+r) / 2;
        bool ok = false;

