        int diff = 0;
        BIT bit(N*2+1);
        LL cnt = 0;
        bit.add(N,1);
        REP(i, a.size()) {
            if(a[i] < now) diff--;
            else diff++;
            cnt += bit.sum(diff+N-1);
            bit.add(diff+N, 1);
        }

        if(t <= cnt) {
            l = m + 1;
        } else {
            r = m;
        }
    }

