struct BIT{

  const ll UNITY_SUM = 0;
  vector<ll> dat;

  BIT(int n) : dat(n+1, UNITY_SUM){}
  void init(int n) {
    dat.assign(n+1, UNITY_SUM);
  }

  inline void add(int a, ll x){
    for(int i = a; i < (int)dat.size(); i+=i & -i){
      dat[i] = dat[i] + x;
    }
  }

  inline ll sum(int a){
    ll res = UNITY_SUM;
    for(int i = a; i > 0; i -= i & -i){
      res = res + dat[i];
    }
    return res;
  }

  inline ll sum(int a, int b){
    return sum(b - 1) - sum(a - 1);
  }
};


