void solve(){
    sort(a, a + n);
    long long r = n;
    long long l = 0;
    while(r - l > 1){
        long long mid = (l + r) >> 1;
        if(check(mid) <= (n * (n - 1) / 2 + n) / 2)
            l = mid;
        else
            r = mid;
    }
