    witex();
    int sum = 0;
    for(long long i = 0; i < n; i++)
        chiz[i] = -1;
    for(long long i = 0; i < x; i++){
        chiz[a[i].s] = 1;
        sum++;
    }
    sum += getinv();
    return sum;
}

void witex(){
    for(long long i = 1; i < 2 * maxn; i++)
        f[i] = 0;
}

void add(long long x, long long v){
    for(; x <= 2 * maxn; x += x & -x)
        f[x] += v;
}

long long get(long long x){
    long long ans = 0;
    for(; x > 0; x -= x & -x)
        ans += f[x];
    return ans;
}

long long getinv(){
    long long parsum = 0;
    long long ans = 0;
    for(long long i = 0; i < n; i++){
        parsum += chiz[i];
        ans += get(parsum + maxn - 1);
        add(parsum + maxn, 1);
    }
    return ans;
}

