};

int inversion(const vector<int> &v){
    int N = v.size();
    vector<int> w(N);
    REP(i,N) w[i]=v[i];
    sort(all(w));
    w.erase(unique(all(w)),w.end());
    vector<int> v2(N);
    REP(i,N) {
        v2[i] = lower_bound(all(w),v[i]) - w.begin();
    }
    BIT<int> bit(w.size()+1);
    int res = 0;
    REP(i,N) {
        res += bit.sum(v2[i]+1);
        bit.add(v2[i]+1,1);
    }
    return res;
}

bool check(int K, const vector<int> &v){
    int N = v.size();
    vector<int> w(N+1,0);
    REP(i,N) w[i+1] = (v[i]>=K ? 1:-1);
    REP(i,N) w[i+1] += w[i];
    return 2LL*(ll)inversion(w) >= (ll)N*(N+1)/2;
}

