int n;

int quick(int l,int r,vector<int> v,int pm){
  if(l < r){
    int piv = v[(l+r+1)/2];
    int pvb = (l+r+1)/2;
    int lp=l,rp=r;
    while(1){
      while(v[lp]<piv) lp++;
      while(v[rp]>piv) rp--;
      if(lp>=rp) break;
      int tmp = v[lp];v[lp]=v[rp];v[rp]=tmp;
      if(lp == pvb) pvb = rp;
      else if(rp == pvb) pvb = lp;
      lp++;
      rp--;
    }
    if(pvb == pm) return v[pm];
    else if(pvb>pm) return quick(l,lp - 1,v,pm);
    else return quick(rp + 1,r,v,pm);
  }
  return v[pm];
}

