    void add(ll i,ll x){
      if(i==0){ return;}
      for(ll k=i;k<=size;k+=(k & -k)){
        bit[k] += x;
      }
    }

    ll sum(ll i){
      ll s = 0;
      if(i==0){ return s;}
      for(ll k=i;k>0;k-=(k & -k)){
