lld query( int p ) {
	lld ret = 0;
	while ( p ) {
		ret += bit[ p ];
		p -= p & (-p);
	}
	return ret;
}
void add( int p, int x ) {
	while ( p < N + N ) {
		bit[ p ] += x;
		p += p & (-p);
	}
