lld calc( int m, int n ) {
	for ( int i = 1 ; i <= n ; ++ i )
		if ( a[ i - 1 ] >= m ) s[ i ] = s[ i - 1 ] + 1;
		else s[ i ] = s[ i - 1 ] - 1;
	memset( bit, 0, sizeof( bit ) );
	lld ret = 0;
	for ( int i = 0 ; i <= n ; ++ i ) {
		ret += query( s[ i ] + N );
		add( s[ i ] + N, 1 );
	}
	return ret;
}

