ll d(int n, vector<ll> a) {
  vector<ll> b(n);
  copy(a.begin(), a.end(), b.begin());
  sort(b.begin(), b.end());

  int low = -1;
  int high = 1<<30;
  int offset = n+1;
  int total_pairs = (n*(n-1)/2) + n;
  //cout << "total pair " << total_pairs << endl;
  while(high - low > 1) {
    int mid = (low + high) / 2;
    //cout << "low " << low << " mid " << mid << " high: " << high << endl;
    vector<int> acc(n);
    Bit bit = Bit(2*n+10);
    acc[0] = (mid > a[0] ? -1 : 1);
    int num = 0;
    if(mid <= a[0]) {
      num++;
    }
    for(int i=1;i<n;i++) {
      acc[i] += acc[i-1] + (mid > a[i] ? -1 : 1);
      if(mid <= a[i]) {
	num++;
      }
    }
    //cout << "num : " << num << endl;
    for(int j=0;j<n;j++) {
      //cout << j << " -> num " << num << " " << bit.sum(offset + acc[j]) << endl;
      num += bit.sum(offset + acc[j]);
      bit.add(offset + acc[j], 1);
    }
    if( total_pairs - num > num) {
      //cout << "see left" << endl;
      high = mid;
    } else {
      //cout << "see right" << endl;
      low = mid;
    }
  }
  return low;
}
