struct Node
{
	int l,r,sum;
};
Node tree[1600401];
int push_up(int p)
{
	tree[p].sum=tree[p<<1].sum+tree[p<<1|1].sum;
}
void build(int p,int l,int r)
{
	if(l==r)
	{
		tree[p].sum=0;
		tree[p].l=l;
		tree[p].r=r;
		return;
	}
	tree[p].l=l;
	tree[p].r=r;
	int mid=(l+r)>>1;
	build(p<<1,l,mid);
	build(p<<1|1,mid+1,r);
	push_up(p);
}
int update(int p,int pos)
{
	if(pos==tree[p].l&&pos==tree[p].r)
	{
		tree[p].sum++;
		return 0;
	}
	int mid=(tree[p].l+tree[p].r)>>1;
	if(pos<=mid) update(p<<1,pos);
	else update(p<<1|1,pos);
	push_up(p);
}
int query(int p,int l,int r)
{
	if(l>r) return 0;
	if(l<=tree[p].l&&tree[p].r<=r) return tree[p].sum;
	int mid=(tree[p].l+tree[p].r)>>1;
	if(r<=mid) return query(p<<1,l,r);
	else
	{
		if(l>mid) return query(p<<1|1,l,r);
		else return query(p<<1,l,mid)+query(p<<1|1,mid+1,r);
	}
}
