long long check( int num, vector<int>& a, vector<int>& ps )
{
    int N = a.size();
    long long ret = 0, now = 0;
    unordered_map<int,int> count;

    count[0] = 1;
    for( int i = 0; i < N; ++i ){
        ps[i] = (i? ps[i-1]: 0) + (a[i]<=num? 1: -1);
        if( a[i] <= num ) now += count[ps[i]-1];
        else now -= count[ps[i]];
        ++count[ps[i]];
        ret += now;
    }

    return ret;
}


int main()
{
    int N;
