    long long l = 0, r = INF;
    long long want = 1LL*(N+1)*N/4 + 1;
    while(r-l > 1){
        int c = (l+r)/2;
        if( check(c, a, ps) >= want ) r = c;
        else l = c;
    }
    cout << r << endl;
    return 0;
}

