BIT::BIT(ll n){

	bit.resize(n+1);

	b=1;

	while(b<=n){
		b<<=1;
	}
}
ll BIT::sum(ll i){
	ll s=0ll;

	for(i+=1ll;i>0;i -= i & -i){
		s+=bit[i];
	}
	return s;
}
void BIT::add(ll i,ll x){
	for(i+=1ll;i<bit.size();i += i & -i){
		bit[i]+=x;
	}
}

