	BIT bt((2ll * N) + 5ll);

	ll i;


	for(i=0ll;i<N;i+=1ll){
		if(a[i]>=c){a[i]=1ll;}
		else{a[i]=-1ll;}
		if(i>0ll){
			a[i]+=a[i-1];
		}
	}

	bt.add(N,1ll);

	ll sum=0ll;

	for(i=0ll;i<N;i+=1ll){
		sum+=bt.sum(a[i]+N);
		bt.add(a[i]+N,1ll);
	}
	return sum;

}

