ll segget(ll l, ll r) {
  ll s = 0;
  l += ofst, r += ofst + 1;
  while (l < r) {
    if (l % 2 == 1) {
      s += seg[l];
      l++;
    }
    l /= 2;
    if (r % 2 == 1) {
      s += seg[r - 1];
      r--;
    }
    r /= 2;
  }
  return s;
}

