struct BIT {
    vector<LL> bit;
    int M;

    BIT(int M) : bit(vector<LL>(M + 1, 0LL)), M(M) {}

    LL sum(int i) {
        if (!i) return 0;
        return bit[i] + sum(i - (i & -i));
    }

    void add(int i, LL x) {
        if (i > M) return;
        bit[i] += x;
        add(i + (i & -i), x);
    }
};


void solve(long long N, std::vector<long long> a){
    VLL sort_a(a.size(), 0LL);
    copy(ALL(a), sort_a.begin());
    sort(ALL(sort_a));

    int l = -1;
    int r = a.size();
    LL t = ceil((N * (N - 1)) / 2LL / 2.0);
    while (r - l > 1) {
        int m = l + (r - l) / 2;
        bool ok = false;

        int now = sort_a[m];
        int diff = 0;
        BIT bit(N*2+1);
        LL cnt = 0;
        bit.add(N,1);
        REP(i, a.size()) {
            if(a[i] < now) diff--;
            else diff++;
            cnt += bit.sum(diff+N);
            bit.add(diff+N, 1);
        }

        //cout << cnt << " " << l << "," << r << "  " << m << " " << now << endl;

        if(t <= cnt) {
            l = m;
        } else {
            r = m;
        }
    }

    cout << sort_a[(l+r)/2] << endl;
}

