class BITree {//1-index
	int N;
	vector<LL> bit;
public:
	BITree(int n) {
		N = n;
		bit = vector<LL>(N + 1, 0);//1-index
	}
	void add(int a, LL w) {//aにwを足す
		if (a <= 0 || N < a) return;//a:[1,N]
		for (int i = a; i <= N; i += i & -i) {
			bit[i] += w;
		}
	}
	LL sum(int a) {//[1,a]の和,a:[1,N]
		/*
		1番目からa番目までの和、1-index
		*/
		LL ret = 0;
		if (a > N) a = N;
		for (int i = a; i > 0; i -= i & -i) {
			ret += bit[i];
		}
		return ret;
	}
};
LL N;
vector<int>C;
bool test(LL K) {
	for (int i = 0; i < N; ++i) {
		if (C[i] >= K) {
			C[i] = 1;
		}
		else {
			C[i] = -1;
		}
		if (i) {
			C[i] += C[i - 1];
		}
	}
	int base = N;

	BITree bit(2 * base + 20);
	LL res = 0;
	for (int i = 0; i < N; ++i) {
		LL temp = bit.sum(C[i] + base);
		bit.add(C[i] + base, 1);
		res += temp;
	}

	if (res >= N * (N - 1) / 4) {
		return true;
	}
	else {
		return false;
	}
}
void solve() {

	cin >> N;
	vector<int>A(N), B;
	for (int i = 0; i < N; ++i) {
		cin >> A[i];
	}
	B = A;
	sort(B.begin(), B.end());
	int L = 0;
	int R = N - 1;
	C = A;
	if (test(B[N-1])) {
		cout << B[N - 1] << endl;
		return;
	}

	while (L + 1 < R) {
		int mid = (L + R) / 2;
		int K = B[mid];
		C = A;
		bool res = test(K);
		if(res){
			L = mid;
		}
		else {
			R = mid;
		}
	}
	cout << B[L] << endl;
}

