template <class It>
long long merge(It l, It m, It r) {
	long long cnt = 0;
	vector<int> tmp(r - l);
	It it = tmp.begin(), it1 = l, it2 = m;
	while (it1 != m && it2 != r) {
		if (*it1 < *it2)
			*it++ = *it1++;
		else
			*it++ = *it2++, cnt += m - it1;
	}
	while (it1 != m) *it++ = *it1++;
	while (it2 != r) *it++ = *it2++;
	move(tmp.begin(), tmp.end(), l);
	return cnt;
};
template <class It>
ll mergecnt(It l, It r) {
	if (r - l <= 1) return 0;
	ll cnt = 0;
	It m = l + (r - l) / 2;
	cnt += mergecnt(l, m);
	cnt += mergecnt(m, r);
	cnt += merge(l, m, r);
	return cnt;
}

