const int MAX = 100000;

class BIT {
public:
	BIT(int n) {
		size = n + 1;
		bit = new int[size];

		for (int i = 0; i < size; i++)bit[i] = 0;
	}
	~BIT() {
		delete[] bit;
	}

	void add(int i, int n) {
		i += 1;
		while (i < size) {
			bit[i] += n;
			i += i & -i;
		}
	}

	int sum(int i) {
		i += 1;
		int ret = 0;
		while (i) {
			ret += bit[i];
			i -= i & -i;
		}
		return ret;
	}
	int size;
	int* bit;
};

int N;
int a[MAX];

bool solve(int x) {
	pair<int,int> sum[MAX];

	for (int i = 0; i < N; i++) {
		int n = a[i] <= x ? 1 : -1;

		if (i)sum[i].first = sum[i - 1].first + n;
		else sum[i].first = n;

		sum[i].second = i;
	}

	sort(sum, sum + N);

	int cnt = 0;
	BIT bit(N);

	for (int i = 0; i < N; i++) {
		cnt += bit.sum(sum[i].second);
		bit.add(sum[i].second, 1);
	}

	if (cnt < (N * (N + 1) / 2 + 1) / 2)return false;
	return true;
}

int main() {
	cin >> N;
	int begin = 0;
	int end = 0;
	int ans = 0;

	for (int i = 0; i < N; i++) {
		cin >> a[i];
		end = max(end, a[i] + 1);
	}

	while (begin < end) {
		int mid = (begin + end) / 2;

		if (solve(mid)) {
			ans = mid;
			end = mid;
		}
		else {
			begin = mid + 1;
		}
	}

	cout << ans << endl;

	return 0;
}

