int main() {
  cin >> N;
  for (int i = 0; i < N; i++)  {
    ll tmp; cin >> tmp; A.push_back(tmp);
  }

  // 二分探索の目標値。 #{ m[i] | x <= m[i]} = objective となる最大の x を探す
  const ll comb = (N + 1) * N / 2;
  const ll objective = (comb + 1) / 2;

  ll left = 0;
  ll right = (ll)1e9;

  while (left < right) {
    ll mid = (left + right + 1) / 2;

    vector<ll> s(N + 1);
    s[0] = 0;

    for (int i = 0; i < N; i++) {
      ll inc = A[i] < mid ? - 1 : 1;
      s[i + 1] = s[i] + inc;
    }

    BIT<ll> bit(2 * N + 2);

    ll invs = 0;
    for (int i = 0; i <= N; i++) {
      ll idx = s[i] + N + 1;
      invs += bit.sum(idx);
