const int INF = 1e+9;

// num より大きい数がいくつあるかを求める
// 転倒数 (i<j かつ a[i]>a[j] となる組の数) の求め方とほぼ同じ
long long check( int num, vector<int>& a )
{
    int N = a.size();
    long long ret = 0, now = 0;
    unordered_map<int,int> count;  // count[i]: iが現れた回数
    vector<int> ps(N);

    count[0] = 1;
    for( int i = 0; i < N; ++i ){
        // a[i] > num となる数を求める
        ps[i] = (i? ps[i-1]: 0) + (a[i]<=num? 1: -1);
        if( a[i] <= num ) now += count[ps[i]-1];
        else now -= count[ps[i]];
        ++count[ps[i]];
        ret += now;
    }

    return ret;
}


int main()
