      int sum = 0; 
      for (int i=0; i < N ; i++ ){
      sum = sum + C.at(i);  
      H.at( N + sum )++ ;  
      } 

      int S= 0; 
      for (int i = N ; i < 2*N+1; i++) {
        S = S + H.at(i);  
      }   


      int T=0;  // total number that is larger than or equals to x
      int U=0;  // U current level 

