#define IDX 131072
using namespace std;
int ans;
int N;
int m[111111],t[111111];
int main(){
  cin>>N;
  for(int i=0;i<N;i++){
    cin>>m[i];
    t[i]=m[i];
  }
  sort(t,t+N);
  int a=0,b=N;
  while(a<b){
    int c=(a+b)/2;
    int d=t[c];
    vector<pair<int,int>>v(N+1);
    vector<int>dp(IDX*2);
    for(int i=1;i<=N;i++){
      if(m[i]<d)v[i].first=-1;
      else v[i].first=1;
      v[i].first += v[i-1].first;
      v[i].second=i;
    }
    sort(v.begin(),v.end());
    long long sum = 0LL;
    for(auto& p:v){
      int from = IDX;
      int to = p.second + IDX;
      while(from<=to){
        if(to%2==0||to==1){
          sum += dp[to--];
        } else {
          to/=2;
          from/=2;
        }
      }
      int idx = p.second + IDX;
      while(idx){
        dp[idx]++;
        idx/=2;
      }
    }
    if(sum<1LL*N*(N+1)/2/2+1){
      b = c;
    } else {
      ans = max(ans, d);
      a = c + 1;
    }
  }
  cout<<ans<<'\n';
