  low = *min_element(a,a+N)-1;
  high = *max_element(a,a+N)+1; // 初期値は最小最大の外側に取る

  while(high - low > 1  ) {
    ll mid = (low + high)/2;
    if (check(mid,a,N)) low = mid;
    else high = mid;
  }

  cout << low << endl;

  return 0;
}

