int n;

ll BIT[N];
void update(int id,ll val) {
	for(;id < N;id += id&-id) {
		BIT[id] += val;
	}
}
ll query(int id) {
	ll sum = 0;
	for(;id > 0;id -= id&-id) {
		sum += BIT[id];
	}
	return sum;
}

ll calc_ans(int m) {
	int i;
	for(i = 1;i <= n;i++) {
		a[i] = (b[i] >= m ? 1 : 0);
	}
	memset(BIT,0,sizeof(BIT));
	update(0 + SHIFT,1);
	cnt[0] = cnt[1] = 0;
	ll ans = 0;
	for(i = 1;i <= n;i++) {
		cnt[a[i]]++;
		ans += (query(cnt[1] - cnt[0] + SHIFT));
		update(cnt[1] - cnt[0] + SHIFT,1);
		// trace(a[i]);
		// trace(ans);
	}
	return ans;
}

