template<typename T>
struct BIT {
    vector<T> array;
    int n;

    BIT(int n) : array(n+1, 0), n(n) {}

    T sum(int i) {
        T s = 0;
        while (i > 0) {
            s += array[i];
            i -= i&-i;
        }
        return s;
    }

    T sum(int l, int r) {
        T ls = sum(l-1);
        T rs = sum(r);
        return rs - ls;
    }

    void add(int i, T x) {
        while (i <= n) {
            array[i] += x;
            i += i&-i;
        }
    }

};

