template <typename T>
class BIT {
    long long sz;
public:
    std::vector<T> node;
    BIT(long long sz): sz(sz+1), node(std::vector<T>(sz+1, 0)) {}
    void add(long long idx, T val) {
        ++idx;
        assert(0 < idx && idx < sz);
        while(idx < sz) {
            node[idx] += val;
            idx += idx & -idx;
        }
    }
    T sum(long long idx) {
        ++idx;
        assert(0 < idx && idx < sz);
        T res = 0;
        while(idx > 0) {
            res += node[idx];
            idx -= idx & -idx;
        }
        return res;
    }
};
