class BIT
{
public:
    vector<ll> bit;
    int M;

    BIT(int M):
        bit(vector<int>(M + 1, 0)), M(M + 1) {}

    int sum(int i)
    {
        if(!i)return 0;
        return bit[i] + sum(i - (i & -i));
    }

    void add(int i, int x)
    {
        if(i > M)return;
        bit[i] += x;
        add(i + (i & -i), x);
    }
};

bool judge(int mid)
{
    ll mem[100010] = {0};
    for(int i = 0; i < N; i++)
    {
        if(A[i] <= mid)mem[i] = 1;
        else mem[i] = -1;
    }

    vector<pii> v;
    ll tmp = 0;
    for(int i = 0; i < N; i++)
    {
        tmp += mem[i];

        v.push_back(mk(tmp, -i - 1));
    }
    v.push_back(mk(0,0));

    sort(v.begin(), v.end());

    BIT bit(N + 10);
    ll sum = 0;
    for(int i = 0; i < v.size(); i++)
    {
        sum += bit.sum(-v[i].se + 1);
        bit.add(-v[i].se + 1, 1);
    }

    if(N * (N + 1) / 2 < sum * 2)return true;
    return false;
}

