template<typename T>
class BinaryIndexedTree {
    int N;
    vector<T> data;
public:
    BinaryIndexedTree(int N) : N(N) {
        data.resize(N + 1, 0);
    }

    T sum(int k) {
        T res = 0;
        for (; k > 0; k -= k & -k) {
            res += data[k];
        }
        return res;
    }

    void add(int k, T x) {
        for (; k <= N; k += k & -k) {
            data[k] += x;
        }
    }

    /**
     * v1 + v2 + ⋯ + vx ≧ W となる最小の 𝑥 を求める
     */
    int lowerBound(int w) {
        if (w <= 0) return 0;
        int x = 0;
        int k = 1;
        while (k * 2 <= N) k *= 2;
        for (; k > 0; k /= 2) {
            if (x + k <= N && data[x + k] < w) {
                w -= data[x + k];
                x += k;
            }
        }
        return x + 1;
    }
};

int main(){
    ll N;
    cin>>N;
    vector<ll> a(N);
    REP(i,N) cin>>a[i];

    ll l=-1;
    ll r=INF;
    while(r-l>1){
        ll k=(l+r)/2;
        vector<ll> b(N,0);
        REP(i,N){
            if(a[i]<=k) b[i]=1;
        }
        vector<ll> s(N+1,0);
        REP(i,N){
            s[i+1]=s[i]+b[i];
        }
        vector<ll> d(N+1,0);
        REP(i,N+1){
            d[i]=2*s[i]-i;
        }
        reverse(ALL(d));

        BinaryIndexedTree<ll> bit(N+10);
        ll num=0;
        ll m=MIN(d);
        REP(i,N+1){
            d[i]+=(1-m);
        }
        REP(i,N+1){
            num+=i-bit.sum(d[i]);
            bit.add(d[i],1);

        }

        if(num>(N+1)*N/4) r=k;
        else l=k;
    }
    cout<<r<<endl;
}

