  vector<ll> a(n);
  rep(i, n) cin >> a[i];

  ll left = 1, right = MAX, cnt = (n * (n + 1) / 2 + 1) / 2;
  while (right - left > 1) {
    ll mid = (left + right) / 2;
    vector<ll> s(n + 1, 0);
    rep(i, n) {
      s[i + 1] += s[i];
      if (a[i] >= mid) s[i + 1]++;
      else s[i + 1]--;
    }
    ll res = n * (n + 1) / 2 - merge_cnt(s);
    if (res >= cnt) left = mid;
    else right = mid;
  }
  cout << left << endl;



  return 0;
}

