ll seg[524288];

ll rsq(int s, int t, int k = 1, int l = 0, int r = 262143) {
	if (t < l || r < s)return 0;
	if (s <= l && r <= t)return seg[k];
	ll lv = rsq(s, t, k * 2, l, (l + r) / 2);
	ll rv = rsq(s, t, k * 2 + 1, (l + r) / 2 + 1, r);
	return lv + rv;
}

void upd(ll x) {
	x += 262144;
	seg[x]++;
	while (x) {
		x /= 2;
		seg[x] = seg[x * 2] + seg[x * 2 + 1];
	}
}

