#include "bits/stdc++.h"
using namespace std;
struct BIT {
	long long n;
	vector<long long> dat;

	void init(long long n_input) {
		n = n_input + 1;
		dat.resize(n + 1);
		for (int i = 0; i <= n; i++) dat[i] = 0;
	}

	long long sum(long long i) {
		long long s = 0;
		while (i >= 0) {
			s += dat[i];
			i = (i & (i + 1)) - 1;
		}
		return s;
	}

	void add(long long i, long long x) {
		while (i <= n) {
			dat[i] += x;
			i |= i + 1;
		}
	}
};

int main() {
	int N;
	cin >> N;
	vector<int>A(N);
	vector<int>A_Sort(N);
	for (int i = 0; i < N; ++i) {
		cin >> A[i];
		A_Sort[i] = A[i];
	}
	sort(A_Sort.begin(), A_Sort.end());
	int l = 0;
	int r = N;
	long long border = ((N * (N + 1) / 2) + 1) / 2;
	while (l + 1 < r) {
		int c = (l + r) / 2;
		vector<int>B(N);
		for (int i = 0; i < N; ++i) {
			B[i] = (A[i] < A_Sort[c]) ? -1 : 1;
		}
		vector<int>S(N);
		for (int i = 0; i < N; ++i) {
			S[i] = (i == 0) ? B[i] : S[i - 1] + B[i];
		}
		long long cnt = 0;
		BIT bit;
		bit.init(2 * N + 1);
		bit.add(N, 1); 
		for (int i = 0; i < N; ++i) {
			cnt += bit.sum(S[i] + N);
			bit.add(S[i] + N, 1);
		}
		if (cnt >= border) {
			l = c;
		}
		else {
			r = c;
		}
	}
	cout << A_Sort[l] << endl;
	return 0;
}

