    }

    while (high - low > 1) {
        BIT<int> bit(3e5);
        ll mid = (high + low) / 2;
        ll ans = 0;
        ll sum = 0;
        bit.add(sum + geta, 1);
        REP(j, N) {
            ll val;
            if (a[j] >= mid) {
                val = 1;
            } else {
                val = -1;
            }
            sum += val;
            ans += bit.sum(sum + geta);
            bit.add(sum + geta, 1);
            // cout << sum << " ";
        }
        // cout << low << " " << high << " " << ans << endl;
        if (ans >= ((((N + 1LL) * N) / 2LL) + 1LL) / 2LL) {
