    ll i = le, j = mid+1, k = le;
    while (i <= mid && j <= ri){
        if (sum[i] <= sum[j]){
            tmp[k++] = sum[i++];
            ret += ri-j+1;
        }
        else
            tmp[k++] = sum[j++];
    }
    while (i <= mid)
        tmp[k++] = sum[i++];
    while (j <= ri)
        tmp[k++] = sum[j++];
    for (ll o = le; o <= ri; o++)
        sum[o] = tmp[o];
    return ret;
}

