    for(auto &x : mp){
      x.second = i;
      i++;
    }
  }

  BIT<ll> bit(n);
  int inv = 0;
  rep(i,n){
    inv += bit.query(mp[pii(s[i+1],i+1)]);
    bit.update(mp[pii(s[i+1],i+1)], 1);
  }

  int tmp = (n+1) * n / 2;
