void solve(std::istream &in, std::ostream &out) {
  int n;
  in >> n;
  vector<int> a(n);
  for (int &i : a) in >> i;

  vector<int> fenwick(2 * n + 1, 0);
  function<int(int)> get = [&](int r) {
    int ans = 0;
    for (; r >= 0; r = (r & (r + 1)) - 1) {
      ans += fenwick[r];
    }
    return ans;
  };
  function<void(int)> inc = [&](int pos) {
    for (; pos < 2 * n + 1; pos |= pos + 1) {
      ++fenwick[pos];
    }
  };

  function<int64_t(int)> check = [&](int x) {
    fill(fenwick.begin(), fenwick.end(), 0);
    vector<int> b = a;
    for (int &i : b) {
      i = i >= x ? 1 : -1;
    }
    for (int i = 1; i < n; ++i) {
      b[i] += b[i - 1];
    }
    int64_t count = 0;
    inc(n);
    for (int i = 0; i < n; ++i) {
      count += get(n + b[i]);
      inc(n + b[i]);
    }
    return count;
  };
  int64_t count = ((int64_t) n * (n + 1) / 2 + 1) / 2;
  int lo = 0, hi = 1'000'000'001;
  while (hi - lo > 1) {
    int mid = lo + hi >> 1;
    if (check(mid) >= count) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  out << lo << '\n';
}

