        dat.assign(++sz,0);
    }
    void add(int k,T x){
        for (;k<=dat.size();k+=k&-k) dat[k]+=x;
    }
    T sum(int k){
        T ret=0;
        for (;k>0;k-=k&-k) ret+=dat[k];
        return ret;
