    FenwickTree(int _n = 0) : n(_n), x(n + 1, 0) {}
    int size() const { return n; }
    T Sum(int r) const {
        T S = 0;
        for (r = r - 1; r >= 0; r = (r & (r + 1)) - 1) S += x[r];
        return S;
    }
    T Sum(int l, int r) const { return Sum(r) - Sum(l); }
    void Add(int k, const T &a) {
        for (; k < n; k |= k + 1) x[k] += a;
    }
    void Set(int k, const T &a) { Add(k, a - Sum(k, k + 1)); }
};


class ProblemD {
public:
    ProblemD(ll _n) : n(_n), a(_n + 1), s(_n + 1, 0) {}
    void Input() { for (int i = 1; i <= n; ++i) cin >> a[i]; }

    int Solve() {
        const ll lim = ceil(n * (n + 1) / 4.0);

        ll lb = 0, ub = *max_element(a.begin(), a.end()) + 1;
        while (ub - lb > 1) {
//            cout << "lb = " << lb << ", ub = " << ub << endl;
            ll mid = 0.5 * (lb + ub), res = Check(mid);
//            cout << "x = " << mid << ", num = " << res << ", lim = " << lim << endl;

            if (lim <= res) lb = mid;
            else ub = mid;
        }

        return lb;
    }

private:
    ll n;
    vector<int> a;
    vector<ll> s;

    ll Check(const int x) {
        for (int i = 1; i <= n; ++i) s[i] = (x <= a[i] ? 1 : -1);
        for (int i = 1; i <= n; ++i) s[i] += s[i - 1];


        ll res = 0;
        FenwickTree<int> tree(2 * n + 1);

        tree.Add(s[0] + n, 1);
        for (int i = 1; i <= n; ++i) {
            res += tree.Sum(0, s[i] + n + 1);
            tree.Add(s[i] + n, 1);
        }

        return res;
    }
};

