	while(ng-ok>1){
		ll md = (ok + ng) / 2;
		auto b = a;
		FOR(i, 1, N+1) b[i] = ((b[i] >= md) ? 1 : -1);
		FOR(i, 1, N+1) b[i] += b[i - 1];
		Zarts Z;
        b=Z.solve(b);
