long long inversion_cnt(int l, int r) {
    if(l == r) return 0;
    long long ans = 0;
    int m = (l+r)/2;
    ans += inversion_cnt(l, m);
    ans += inversion_cnt(m+1, r);

    int i = l, j = m+1;
    for(int i = l ; i <= m ; i++) {
        while(s[i] > s[j] && j <= r) j++;
        if(j <= r) ans += r-j+1;
    }

    int k = l; i = l, j = m+1;
    while(i <= m && j <= r) {
        if(s[i] <= s[j]) t[k++] = s[i++];
        else t[k++] = s[j++];
    }
    while(i <= m) t[k++] = s[i++];
    while(j <= r) t[k++] = s[j++];
    for(int i = l ; i <= r ; i++) s[i] = t[i];

    return ans;
}

