        return 0;
    }

    ll cnt = 0;
    vector<int> v1(v.begin(), v.begin() + n / 2);
    vector<int> v2(v.begin() + n / 2, v.end());

    cnt += mergeCnt_inversion(v1);
    cnt += mergeCnt_inversion(v2);

    int i = 0, i1 = 0, i2 = 0;

    while (i < n) {
        if (i1 < n / 2 && (i2 == n - n / 2 || v1[i1] <= v2[i2])) {
            v[i] = v1[i1];
            i1++;
        }
        else {
            cnt += n / 2 - i1;
            v[i] = v2[i2];
            i2++;
        }
        i++;


    }

    return cnt;

}

