// 1次元座圧
class CoordCompress1D {
    um<ll, ll> coord2zipped; // キーが座標値
    vll zipped2coord;        // 各要素が座標値
    ll sz;

  public:
    CoordCompress1D() {}
    CoordCompress1D(vll coords) {
        sort(ALL(coords));
        UNIQ(coords);
        sz = SIZE(coords);
        zipped2coord = coords;
        REP(i, 0, sz) coord2zipped[coords[i]] = i;
    }
    // 座標の圧縮（コンストラクタに与えた座標限定）
    ll zip(ll coord) { return coord2zipped[coord]; }
    ll unzip(ll zipped) { return zipped2coord[zipped]; }

    // coord 以上の最小の座標値を返す
    ll coord_geq(ll coord) {
        auto it = lower_bound(ALL(zipped2coord), coord);
        if (it != zipped2coord.end()) return *it;
        return INF;
    }

    // coord より大きいの最小の座標値を返す
    ll coord_gt(ll coord) {
        auto it = upper_bound(ALL(zipped2coord), coord);
        if (it != zipped2coord.end()) return *it;
        return INF;
    }

    // coord 以下の最小の座標値を返す
    ll coord_leq(ll coord) {
        auto rit = lower_bound(zipped2coord.rbegin(), zipped2coord.rend(), coord,
                               [](ll const lhs, ll const rhs) { return lhs > rhs; });
        if (rit != zipped2coord.rend()) return *rit;
        return -INF;
    }

    // coord 未満の最小の座標値を返す
    ll coord_lt(ll coord) {
        auto rit = upper_bound(zipped2coord.rbegin(), zipped2coord.rend(), coord,
                               [](ll const lhs, ll const rhs) { return lhs > rhs; });
        if (rit != zipped2coord.rend()) return *rit;
        return -INF;
    }

    ll size() { return sz; }
};

/* #endregion */

template <class tProposition> ll binarySearchIntMax(ll left, ll right, tProposition p) {
    if (right < left) return -1;
    ll mid;
    while (left + 1 < right) {
        mid = (left + right) / 2;
        if (p(mid))
            left = mid;
        else // fn > 0
            right = mid - 1;
    }

    if (p(right))
        return right;
    else if (p(left))
        return left;
    else
        return -1;
}

// Problem
void solve() {
    ll n;
    cin >> n;
    vll a(n);
    cin >> a;

    // 中央値の候補 mid を二分探索する
    // 求めたいのは「mid 以上の値が半数以上を占める区間 [l,r] の個数」が ceil(nH2/2) 個以上ある最大の mid.
    // 　↓　ある mid について，以上/未満 を 1/-1 に割り当てると...
    // 求めたいのは「区間和が 0 以上になる区間 [l,r] の個数」が ceil(nH2/2) 個以上ある最大の mid.
    // 　↓　累積和を用いると...
    // 求めたいのは「S_r - S_{l-1} >= 0 になる区間 [l,r] の個数」が ceil(nH2/2) 個以上ある最大の mid.
    // 　↓　式変形すると...
    // 求めたいのは「S_{l-1} <= S_r になる区間 [l,r] の個数」が ceil(nH2/2) 個以上ある最大の mid.
    // 　↓　l-1 = L とする（0 <= l <= r < n, -1 <= L <r < n）
    // 求めたいのは「S_L <= S_r になる区間 [L,r] (L<r) の個数」が ceil(nH2/2) 個以上ある最大の mid.
    // 　→　これを転倒数もどきで求める

    ll comb = n * (n + 1) / 2;
    ll t = (comb + 1) / 2;

    auto [itr_mi, itr_ma] = minmax_element(ALL(a));
    ll ma = binarySearchIntMax(*itr_mi, *itr_ma, [&](ll mid) {
        vll acp(n);
        REP(i, 0, n) acp[i] = (a[i] >= mid) ? 1 : -1;
        vll s(n);
        s[0] = acp[0];
        REP(i, 1, n) s[i] = s[i - 1] + acp[i];

        ll ret = 0;
        REP(i, 0, n) if (s[i] >= 0) ret++;

        CoordCompress1D cc(s);
        auto f = [](ll a, ll b) { return a + b; };
        SegmentTree<ll> seg(f, 0);
        seg.init(cc.size());

        ll rev = 0;
        REP(i, 0, n) {
            ll zi = cc.zip(s[i]);
            ll leq_cnt = seg.query(0, zi + 1);
            // 今まで i 個使用，そのうち leq_cnt 個が s[i] 以下
            rev += leq_cnt;
            seg.set_val(zi, seg.get_val(zi) + 1);
        }
        ret += rev;

        // dump(mid, t, ret, rev);
        return ret >= t;
    });
    cout << ma << endl;
}

// entry point
int main() {
    solve();
    return 0;
}

