const long SIZE=200010;  //Nの最大値*2より大
long Sum(const long BIT[], long a){
    long ans=0;
    while(a){
        ans+=BIT[a];
        long least=a&-a;  //これで最も末位の1のビットを求める
        a-=least;
    }
    return ans;
}

void Add( long BIT[], long a, long x )
{
    while(a<=SIZE){
        BIT[a]+=x;
        long least=a&-a; //sumのleastど同様
        a+=least; //leastの桁を繰り上げます。
    }
    return;
}

long st_check( long n, long* a, long tmp )
{
    std::vector<long> s(n+1);
    long i;
    s[0] = n+1;
    for(i=0; i<n; i++) {
        s[i+1] = s[i];
        if(a[i]>=tmp) {
            s[i+1] ++;
        }
        else {
            s[i+1] --;
        }
    }

    long BIT[SIZE+1] = {0};
    long ans = 0;
    for(i=0; i<=n; i++) {
        ans += Sum(BIT, s[i]);
        Add(BIT, s[i], 1);
    }

    return ans;
}

