        	sum.pb(sum[sum.size()-1]+v[i+1]);
        }
  			ll ans=mergecount(sum);
  			ans=N*(N+1)/2-ans;
        if((N*(N+1)/2+1)/2<=ans) left=mid;
        else right=mid;
    }
    return mid;
}

