// Binary Indexed Tree 1-indexed
struct BIT {
    ll n;
    vector<ll> bit;
    BIT(ll n): n(n), bit(n+1, 0) {}
    void add(ll a, ll w) {
        for(ll x = a; x <= n; x += x & -x) bit[x] += w;
    }
    ll sum(ll a) {
        ll ret = 0;
        for(ll x = a; x > 0; x -= x & -x) ret += bit[x];
        return ret;
    }
    // [a, b]
    ll sum(ll a, ll b) {
        return sum(b) - sum(a-1);
    }
};

