void merge(int l, int r) {
	// merge sort interval [l, r)
	if (r - l <= 1) return;
	int mid = l + r >> 1;
	merge(l, mid);
	merge(mid, r);
#ifdef DEBUG_MD_
	printf("[%d, %d)\n", l, r);
#endif
	int i, j, k;
	for (i = l, j = mid, k = l; i < mid && j < r; )
		if (C[i] < C[j]) {
			D[k++] = C[i++];
			tot += r - j;
		}
		else D[k++] = C[j++];
	for (; i < mid; ) D[k++] = C[i++];
	for (; j < r; ) D[k++] = C[j++];
	memcpy(C + l, D + l, sizeof(int) * (r - l));
}

