}
ll solve3dcnt(ll zl, ll zr, int l, int r) {
    if(r - l <= 0 || zr - zl <= 0)
        return 0;
    ll zmid = (zl + zr) / 2;
    ll ans = 0;
    ans += solve2dcnt(l, r, zmid);
    int mid = std::partition(d + l, d + r, [zmid](const pt &u) {
        return u.z < zmid;
    }) - d;
    ans += solve3dcnt(zl, zmid, l, mid);
    ans += solve3dcnt(zmid, zr, mid, r);
    return ans;
}

