bool f(std::vector<int> const& a, int x) {
  size_t n = a.size();
  std::vector<std::pair<int, size_t>> b(n);
  for (size_t i = 0; i < n; ++i)
    b[i] = std::make_pair((a[i] < x)? -1: +1, i+1);

  b.insert(b.begin(), std::make_pair(0, 0_zu));
  for (size_t i = 1; i <= n; ++i) b[i].first += b[i-1].first;
  std::sort(b.rbegin(), b.rend());

  uintmax_t res = 0;
  basic_segment_tree<int> st(n+1, 0);
  for (auto const& p: b) {
    int bi;
    size_t i;
    std::tie(bi, i) = p;
    res += st.fold(i+1, n+1);
    st.modify(i, st[i]+1);
  }

  uintmax_t m = n * (n+1_ju) / 2;
  return m/2 <= res;
}

