bool ok(int k, const vector<int> &A) {
    LL N = A.size();

    vector<LL> dp(N + 1, 0);
    FOR(i, 0, N) {
        LL a = A[i] <= k ? 1 : -1;
        dp[i + 1] = dp[i] + a;
    }

    FenwickTree ft(300000);
    LL base = 100000;

    // k以下の数
    long long num = 0;
    FOR(i, 0, N + 1) {
        LL v = base + dp[i];
        num += ft.sum(v);
        ft.add(v, 1);
    }

    return num > (N + 1) * N / 2 / 2;

}

