ll L[100010], R[100010];

ll merge(ll a[], int N, ll left, ll mid, ll right){
    ll cnt = 0;
    ll n1 = mid - left;
    ll n2 = right - mid;
    rep(i,0,n1){
        L[i] = a[left + i];
    }
    rep(i,0,n2){
        R[i] = a[mid + i];
    }
    L[n1] = 1e9; // sentinel
    R[n2] = 1e9;

    ll p = 0, q = 0;

    rep(k,left, right){
        if(L[p] <= R[q]){
            a[k] = L[p];
            p++;
        }else{
            a[k] = R[q];
            q++;
            cnt += n1 - p;
        }

    }
    return cnt;


}

ll mergeSort(ll a[], int N, ll left, ll right){
    ll mid;
    ll v1, v2, v3;
    if(left + 1 < right){
        mid = (left + right) / 2;
        v1 = mergeSort(a, N, left, mid);
        v2 = mergeSort(a, N, mid, right);
        v3 = merge(a, N, left, mid, right);
        return v1 + v2 + v3;
    }else{
        return 0;
    }
}

