void msort(int s,int t)
{
    if(s==t) 
    { 
        return;
    }              
    int mid=(s+t)/2;
    msort(s,mid);             
    msort(mid+1,t);      
    int i=s, j=mid+1, k=s;   
    while(i<=mid && j<=t)
    {
    	if(d[i]<=d[j])  
        {
            r[k]=d[i];
            k++; 
            i++;
        }
        else
        {
        	answer+=mid-i+1;
            r[k]=d[j]; k++; j++;
        }
    }  
    while(i<=mid)
    {
        r[k]=d[i]; k++; i++;
    }
    while(j<=t)  
    {
        r[k]=d[j]; k++; j++;
    }
    for(int i=s; i<=t; i++) d[i]=r[i];  
    return;
} 

