void merge_sort(int l,int r)
{
	if(l>=r) return;
	int mid=(l+r)/2;
	merge_sort(l,mid);
	merge_sort(mid+1,r);
	int i=l,j=mid+1,k=l;
	while(i<=mid&&j<=r)
	{
		if(sum[i]<=sum[j]) temp[k++]=sum[i++];
		else cnt+=mid-i+1,temp[k++]=sum[j++];
	}
	while(i<=mid) temp[k++]=sum[i++];
	while(j<=r) temp[k++]=sum[j++];
	for(i=l;i<=r;i++) sum[i]=temp[i];
}
