template <typename T>
int _partition(vector<T>& a, int start, int end, T pivot_value) {
    return std::partition(a.begin()+start, a.begin()+end,
                          [=](T x){ return x <= pivot_value; }) - a.begin();
}

template <typename T>
T pivot(vector<T>& a, int start, int end);

template <typename T>
T select_kth(vector<T>& a, int start, int end, int k) {
    // a[start,end) から k番目 (0-based) に小さい要素を返す
    int length = end - start;
    if (length == 1) {
        return a[start];
    } else if (length <= 10) {
        return select_kth_small(a, start, end, k-start);
    }

    int pivot_index = -1;
    while (true) {
        T pivot_value = pivot(a, start, end);
        int pivot_index = _partition(a, start, end, pivot_value)-1;
        if (pivot_index == k) {
            break;
        } else if (pivot_index < k) {
            start = pivot_index + 1;  // (pivot_index, end)
        } else if (pivot_index > k) {
            end = pivot_index;  // [start, pivot_index)
        }
    }
    return a[k];
}

