typedef long long ll;

struct BIT {
    vector<ll> x;
    BIT(ll n) : x(n, 0) {}
    ll sum(ll i){
        ll s = 0;
        while(i > 0){
            s += x.at(i - 1);
            i -= i & (-i);
        }
        return s;
    }
    void add(ll i, ll v){
        i += 1;
        while(i <= x.size()){
            x.at(i - 1) += v;
            i += i & (-i);
        }
    }
};

ll calc_inversion_number(const vector<ll>& x){
    ll maxv = *max_element(x.begin(), x.end());
    ll minv = *min_element(x.begin(), x.end());
    ll n = maxv - minv + 1;
    BIT bit(n);
    ll ret = 0;
    for(int i = 0; i < x.size(); ++i){
        ret += i - bit.sum(x.at(i) - minv + 1);
        bit.add(x.at(i) - minv, 1);
    }
    return ret;
}

bool check(const vector<ll> a, ll x){
    cerr << "check(" << x << ")" << endl;

    const ll n = a.size();
    vector<ll> b(n, 0);
    for(ll i = 0; i < n; ++i){
        if(a.at(i) >= x){
            b.at(i) = 1;
        }else{
            b.at(i) = -1;
        }
    }

    cerr << "b = ";
    for(ll bi : b){ cerr << bi << " "; }
    cerr << endl;

    vector<ll> c(n + 1, 0);
    for(int i = 1; i <= n; ++i){
        c.at(i) = c.at(i - 1) + b.at(i - 1);
    }

    cerr << "c = ";
    for(ll ci : c){ cerr << ci << " "; }
    cerr << endl;

    ll invnum = calc_inversion_number(c);
    ll total = n * (n + 1) / 2;
    ll half = total / 2;
    cerr << "total = " << total
        << ", half = " << half << ", invnum = " << invnum
        << ", ans = " << (total - invnum) << endl;
    return half <= total - invnum;
}

