//中央値がｍ以上となる区間が過半数を超えるか？
//ｍ以下の時a[i]＝１，ｍより大きい時a[i] = -1とすると
//区間[l,r]の総和が０以上と時、その区間の中央値はｍ以上であるといえる
//すべての区間[l,r]について考えるには、累積和の配列をSとすると
//S[r] - s[l] >= 0のとき中央値はｍ以上だが愚直にやるとO(n^2)になる
//そこでS[r] - S[l] >= 0 ⇔ S[l] <= S[r]と変形する。
//このような（ｌ，ｒ）は転倒（してない）数を数え上げれば求まる。
bool f(ll m){
   BIT bit(202020);
   ll rui = 0,s = 0,ofs=100000;
   bit.add(ofs, 1);
   for(int i=0; i < n; i++){
      ll v;
      if(a[i] <= m){
         v = 1;
      }
      else{
         v = -1;
      }
      rui += v;
      s += bit.sum(ofs + rui-1);
      bit.add(ofs + rui, 1);
   }
   return (n * (n + 1) / 2 / 2 < s);
}

