inline int read()
{
	int data = 0, w = 1; char ch = getchar();
	while (ch != '-' && (ch < '0' || ch > '9')) ch = getchar();
	if (ch == '-') w = -1, ch = getchar();
	while (ch >= '0' && ch <= '9') data = data * 10 + (ch ^ 48), ch = getchar();
	return data * w;
}

const int maxn(1e5 + 10), N(1e5 + 5);
int n, A[maxn], S[maxn], c[maxn << 1], sum[maxn]; long long MID;
void Add(int x) { for (x += N; x <= N + n; x += x & -x) ++c[x]; }
int Query(int x) { int ans = 0; for (x += N; x; x -= x & -x) ans += c[x]; return ans; }

int check(int mid)
{
	for (int i = 1; i <= n; i++) sum[i] = (A[i] < mid ? -1 : 1);
	for (int i = 1; i <= n; i++) sum[i] += sum[i - 1];
	long long tot = 0; Add(0);
	for (int i = 1; i <= n; i++) tot += Query(sum[i]), Add(sum[i]);
	memset (c, 0, sizeof c);
	return MID <= tot;
}

