vi count_inversion(vi arr, ll &cnt) {
  if (arr.size() == 1) {
    cnt = 0;
    return arr;
  }

  ll a, b;

  vi left = count_inversion(vi(arr.begin(), arr.begin() + arr.size() / 2), a);
  vi right = count_inversion(vi(arr.begin() + arr.size() / 2, arr.end()), b);

  vi merged;
  size_t i = 0, j = 0;
  cnt = a + b;
  while (i < left.size() || j < right.size()) {
    if (i == left.size()) {
      merged.pb(right[j++]);
    } else if (j == right.size()) {
      merged.pb(left[i++]);
    } else {
      if (left[i] <= right[j]) {
        merged.pb(left[i++]);
      } else {
        merged.pb(right[j++]);
        cnt += left.size() - i;
      }
    }
  }
  return merged;
}

