    vector<long long> a(N);
    for (int i = 0; i < N; i++)
    {
        cin >> a[i];
    }

    long long l = 1;
    long long r = 1000000001;
    while (r - l > 1)
    {
        long long c = (l + r) / 2;
        BinaryIndexedTree<long long> bit(2 * N + 1, 0);
        long long current = 0;
        long long count = 0;
        bit.update(convert_to_BIT_idx(current, N), 1);
        for (int i = 0; i < N; i++)
        {
            if (a[i] >= c)
            {
                current++;
            }
            else
            {
                current--;
            }
            count += bit.query(convert_to_BIT_idx(current, N));
            bit.update(convert_to_BIT_idx(current, N), 1);
        }

        if (count * 2 >= N * (N + 1) / 2)
        {
            l = c;
        }
        else
        {
            r = c;
        }
    }
    cout << l << endl;
}

