int a[ N ], s[ N ];
lld bit[ N << 1 ];

lld query( int p ) {
	lld ret = 0;
	while ( p ) {
		ret += bit[ p ];
		p -= p & (-p);
	}
	return ret;
}
void add( int p, int x ) {
	while ( p < N + N ) {
		bit[ p ] += x;
		p += p & (-p);
	}
}

lld calc( int m, int n ) {
	for ( int i = 1 ; i <= n ; ++ i )
		if ( a[ i - 1 ] >= m ) s[ i ] = s[ i - 1 ] + 1;
		else s[ i ] = s[ i - 1 ] - 1;
	memset( bit, 0, sizeof( bit ) );
	lld ret = 0;
	for ( int i = 0 ; i <= n ; ++ i ) {
		ret += query( s[ i ] + N );
		add( s[ i ] + N, 1 );
	}
	return ret;
}

