template<typename T>
class BIT{
  public:
    int N;
    vector<T> data;
    BIT(T _N):N(_N){
        data.assign(N+1, 0);
    };

    // a is 1-indexed
    void add(int a, T w){
        for(int x = a; x <= N; x += x & -x) data[x] += w;
    }
    // 1-indexed sum of prefix [0, a]
    T sum(int a){
        T res = 0;
        for(int x = a; x > 0; x -= x & -x) res += data[x];
        return res;
    }
    // 1-indexed sum of range [l, r]
    T sum(int l, int r){return sum(r) - sum(l-1);}

    // 0-indexed add
    void add0(int a, T w){add(a + 1, w);}
    // 0-indexed sum
    T sum0(int a){return sum(a + 1);}
    // 0-indexed sum of range
    T sum0(int l, int r){return sum0(r) - sum0(l-1);}

    //1-indexed でv1+v2+...+vx >= w となる最小のx
    T blb(T w) {
      if(w <= 0) return 0;
      int res = 0;
      int i=1;
      while(i*2 <= N) {i *= 2;}
      //i は N以下の最大の２べき
      for(int k = i; k > 0; k /= 2) {
        if(res + k <= N && data[res + k] < w) {
          w -= data[res + k];
          res += k;
        }
      }
      return res+1;
    }

    /* debug */
    void print() {
        rep(i,data.size()) cout << sum0(i,i) << ",";
        cout << endl;
    }

};


