const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n;
vl a;
ll cnt[MAX_N], total, target;

void solve(ll n){
    rep(i, n){
        a.pb(0);
        in1(a[i]);
    }
    sort(all(a));
    // the array a of length M
    // the index for median M / 2
    // the subsequence a[l:r + 1] (the length is r - l + 1)
    // the index for median (r - l + 1) / 2 + l = (r + l + 1) / 2
    // the goal is to find the median index of the set of the index above
    // here, let r + l = k (0 <= k <= 2M - 2, r >= l)
    // then k - M + 1 <= k - r = l <= k / 2 (l must be less than or equal to M - 1)
    // therefore, there are min(k, M - 1) + max(0, k - M + 1) + 1 possible candidates for l of a given value k.
    total = 0;
    rep(i, n) cnt[i] = 0;
    rep(k, 2 * n - 1) {
        ll val = k / 2 + max(0LL, k - n) + 1;
        cnt[(k + 1) / 2] += val;
        total += val;
    }
    ll hoge = 0;
    rep(i, n){
        hoge += cnt[i];
        if (hoge >= total / 2 + 1) {target = i; break;}
    }
    prl(a[target]);
}

int main(void){
    in1(n);
    solve(n);

    return 0;
}

