{
    sum[0] = 0;
    for (ll i = 1; i <= n; i++){
        sum[i] = sum[i-1];
        if (a[i] >= mid) sum[i]++;
        else sum[i]--;
    }
    if (Msort(0, n) >= lim) return true;
    return false;
}

