			tot += r - j;
		}
		else D[k++] = C[j++];
	for (; i < mid; ) D[k++] = C[i++];
	for (; j < r; ) D[k++] = C[j++];
	memcpy(C + l, D + l, sizeof(int) * (r - l));
}

