    // 上の判定をO(n)でやりたい

    // 置き換え
    // ans以下のものに-1を
    // ansより大きいものに1を置く
    // 区間の総和が負になるものはただしい

    // ただしいものが half以上になるかどうか

    ll mi = -n * 2;
    SegmentTree<int> seg(-mi + n, 0, [](int a, int b)->int {return a + b; }, [](int a, int b)->int {return a + b; });

    int left = 0; int right = 1e9 + 1;
    while (right - left > 1) {
        int mid = (right + left) / 2;

        // 置き換える
        vector<ll> ta(n);
        rep(i, n) {
            if (a[i] <= mid) ta[i] = -1;
            else ta[i] = 1;
        }

        vector<ll> sum(n + 1, 0LL);
        rep(i, n) {
            sum[i + 1] = sum[i] + ta[i];
        }

        // [i, j) において，
        // s[j] - s[i] < 0　なら正しい
        // s[i] > s[j]　となる場合の数を求める 転倒数と同じ考え
        // s[i]を見るとき，右側に地震より小さい値がいくつあるか
        ll num = 0LL;
        for (int i = n; i >= 0; --i) {
            num += seg.query(0, -mi + sum[i]);
            seg.change(-mi + sum[i], +1);
        }
        // 終わったので戻す
        rep(i, n + 1) seg.change(-mi + sum[i], -1);

        //cout << "mid : " << mid << " " << num << endl;

        if (num >= half) {
            right = mid;
        }
        else left = mid;
    }

    ans = left + 1;

    // 2分探索，簡単なアルゴリズムなのに見えづらくてかなり良い
    Cout(ans);

    // 計算量 O(nlognlog(1e9)) 危なさそう

    return 0;
}

