template<typename T>
struct BIT{
    vector<T> node;
    int n;
    int p;
    BIT(int n):n(n){ 
        node.resize(n + 1LL, 0);
        p=1;
        while(p<node.size()) p*=2;
    }
    T sum(int k) {
        T ret=0;
        for (;k>0;k-=(k & -k)) ret+=node[k];
        return ret;
    }	
    T sum(int a, int b){//[a,b)
        return sum(b)-sum(a);
    } 
    void add(int k, T x) {
        for(;k<=n;k+=(k & -k)) node[k]+=x;
    }
    int lower_bound(ll w) {
        if(w<=0)return 0;
        int x=0;
        for(int k=p/2;k>0;k/=2) {
            if(x+k<=n && node[x+k]<w){
                w-=node[x+k];
                x+=k;
            }
        }
        return x+1;
    }
};

//Compress<ll> comp(a);みたいな感じで
template <class T>
struct Compress{
    int N;
    map<T,int> idx;
    vector<T> cmp;
    Compress(vector<T> v){
        for(auto& x:v) cmp.push_back(x);
        sort(cmp.begin(),cmp.end());
        cmp.erase(unique(cmp.begin(),cmp.end()),cmp.end());
        N=cmp.size();
        for(int i=0;i<N;i++) idx[cmp[i]]=i;
    }
    int id(T val){return idx[val];}//前→後
    T val(int id){return cmp[id];}//後→前
};

