#include <functional>
template<typename T,typename F=std::function<bool(T)>>
T binarysearch(T lo,T hi,const T eps,const F &predicate){
	T r=hi+eps;
	for(;lo<hi+eps;){
		T mi=eps!=1||(lo<0)==(hi<0) ? lo+(hi-lo)/2 : (lo<-hi) ? -((-lo-hi-1)/2+1) : (lo+hi)/2;
		if(predicate(mi)){
			r=mi;
			hi=mi-eps;
		}else{
			lo=mi+eps;
		}
	}
	return r;
}

int main(){
	int T,i,N;
	scanf("%d",&N);std::vector<int>v(N);for(T=i=0;i<N;i++){scanf("%d",&v[i]);if(v[i]>T)T=v[i];}
	printf("%d\n",binarysearch(0,T,1,[&](int m){
		A[0]=0;
		for(i=1;i<=N;i++)A[i]=A[i-1]+(v[i-1]>m?1:-1);
		return merge_and_count(0,N+1)>=(long long)(N+1)*N/4+1;
	}));
}

