ll calc(ll in) {
  ll res = 0;
  memset(sum, 0, sizeof sum);
  memset(num, 0, sizeof num);
  for (int i = 1; i <= n; i++) {
    if (a[i] >= in)
      sum[i] = sum[i - 1] + 1;
    else
      sum[i] = sum[i - 1] - 1;
  }
  ll pre = 0;
  num[N] = 1;
  for (int i = 1; i <= n; i++) {
    if (sum[i] > sum[i - 1])
      pre += num[sum[i] + N] + 1;
    else
      pre -= num[sum[i - 1] + N] - 1;
    num[sum[i] + N]++;
    res += pre;
  }
  return res;
}

void solve() {
  sort(b + 1, b + n + 1);
  ll l = 1;
  ll r = unique(b + 1, b + n + 1) - b - 1;
  ll med = n * (n + 1) / 2 - n * (n + 1) / 2 / 2;
