    BIT(ll n = 0) { initialize(n); }

    void initialize(ll nin) {
        n = nin + 1;
        dat.resize(n + 1);
        fill(All(dat), 0);
    }

    T sum(ll i) {
        T s = 0;
        while(i > 0) {
            s += dat[i];
            i = i & (i - 1);
        }
        return s;
    }

    T sum_between(ll i, ll j) {
        if(i > j) return 0;
        return sum(j) - sum(i - 1);
    }

    void plus(ll i, T x) {
        while(i <= n) {
            dat[i] += x;
            i += i & -i;
        }
    }

    ll lower_bound(T x) {
        ll ret = 0;
        ll k = 1;
        while(2 * k <= n) k <<= 1;
        for(; k > 0; k >>= 1) {
            if(ret + k <= n && dat[ret + k] < x) {
                x -= dat[ret + k];
                ret += k;
            }
        }
        return ret + 1;
    }
};

bool judge(ll x) {
    VL sum(N + 1, 0);
    ll all = (N + 1) * N / 2;
    ll S = 0;
    REP(i, N) {
        sum[i + 1] += sum[i] + (a[i] >= x ? 1 : -1);
        if(a[i] >= x) S++;
    }
    FOREACH(s, sum) s += N + 1;
    auto num = BIT<ll>(2 * N);
    FOR(i, 1, N + 1) {
        S += num.sum(sum[i]);
        num.plus(sum[i], 1);
    }
    return (all % 2 ? S >= all / 2 + 1 : S >= all / 2);
}

