    else a[i] = a[i - 1] - 1;
  }
  ll t = 0;
  b[n] = 1;
  memset(b, 0, sizeof(b));
  ll have = 0;
  FOR(i, 1, n) {
    if (a[i] >= a[i - 1]) t -= b[a[i]];
    else t += b[a[i - 1]];
    b[a[i]]++;
    have += t;
  }
  ll tAns = (ll)n * (n + 1) / 2 - have;
  return have < tAns;
}
