template<typename T>
struct Compress {
  vector<T> xs;

  Compress() = default;

  Compress(const vector<T> &vs) {
    add(vs);
  }

  Compress(const initializer_list<vector<T>> &vs) {
    for(auto &p : vs) add(p);
  }

  void add(const vector<T> &vs) {
    copy(begin(vs), end(vs), back_inserter(xs));
  }

  void add(const T &x) {
    xs.emplace_back(x);
  }

  void build() {
    sort(begin(xs), end(xs));
    xs.erase(unique(begin(xs), end(xs)), end(xs));
  }

  vector<int> get(const vector<T> &vs) const {
    vector<int> ret;
    transform(begin(vs), end(vs), back_inserter(ret), [&](const T &x) {
      return lower_bound(begin(xs), end(xs), x) - begin(xs);
    });
    return ret;
  }

  int get(const T &x) const {
    return lower_bound(begin(xs), end(xs), x) - begin(xs);
  }

  const T &operator[](int k) const {
    return xs[k];
  }
};

template<typename T>
struct BinaryIndexedTree {
    int N;
    vector<T> data;

    BinaryIndexedTree(int sz) {
        N = sz;
        data.assign(++sz, 0);
    }

    T sum(int k) { // [0,k) (0-indexed) a[0] + … + a[k-1]
        T ret = 0;
        for(; k > 0; k -= k & -k) ret += data[k];
        return (ret);
    }

    T sum(int l, int r) { // [l,r) (0-indexed) a[l] + …　+ a[r-1]
        T vl = sum(l);
        T vr = sum(r);
        return vr - vl;
    }

    void add(int k, T x) { // (0-indexed) a[k] += x;
        for(++k; k <= N; k += k & -k) data[k] += x;
    }

    int lowerbound(int x) { // (0-indexed)
        int k = 1;
        int res = 0;
        while ((k<<1) <= N) k <<= 1;
        while (k > 0) {
            if (res + k <= N && data[res+k] < x) {
                x -= data[res+k];
                res += k;
            }
            k >>= 1;
        }
        return res;
    }

    int upperbound(int x) { // (0-indexed)
        ++x;
        int k = 1;
        int res = 0;
        while ((k<<1) <= N) k <<= 1;
        while (k > 0) {
            if (res + k <= N && data[res+k] < x) {
                x -= data[res+k];
                res += k;
            }
            k >>= 1;
        }
        return res;
    }
};

