inline int lowbit(int x){return x&(-x);}

void up(int pos, int val){
	for(int i = pos; i <= 2*n+2; i += lowbit(i)){
		p[i] += val;
	}
}

long long que(int pos){
	long long ans = 0;
	for(int i = pos; i; i -= lowbit(i)){
		ans += p[i];
	}
	return ans;
}

long long calc(int x){
	memset(f, 0, sizeof(f));
	memset(p, 0, sizeof(p));
	for(int i = 1; i <= n; i ++){
		if(da[i] >= x) f[i] = 1;
		else f[i] = -1; 
		f[i] += f[i-1];
	}
	long long res = 0;
	up(n+1, 1);
	for(int i = 1; i <= n; i ++){
		up(f[i]+n+1, 1);
		res += que(2*n+2) - que(f[i]+n+1);
	}
	return res;
}

int main(){
