	int l = 1, r = 1e9+1, ans = 0;
	while(l <= r){
		int mid = (l+r) >> 1;
		if(calc(mid) <= (long long)((1+n)*n/2)/2 + 1){
			l = mid + 1, ans = mid;
		}else r = mid - 1;
	} 
	printf("%d\n", ans);
	return 0;	
}

