  sort(B.begin(), B.end());
  long long ok = -1, ng = N;
  while(ng - ok > 1){
    long long m = (ok + ng)/2, b = B[m];
    vector<int> C(N);
    for(int i = 0; i < N; ++i){
      if(A[i] >= b) C[i] = 1;
      else C[i] = -1;
    }
    for(int i = 1; i < N; ++i) C[i] += C[i-1];
    //cerr << "C : "; for(int i = 0; i < N; ++i) cerr << C[i] << " "; cerr << endl;
    long long inv = count_inv(C,0,N);
    if(inv <= N*(N-1)/4) ok = m;
    else ng = m;
  }
  //cerr << ok << endl;
  cout << B[ok] << endl;
  return 0;
}

