const int maxn = 1e5+5;
int N;
int a[maxn],b[maxn],sum[maxn],bit[maxn*2+1];
int lowbit(int x){return x&-x;}
void add(int x,int v){for(;x<=2*N+1;x+=lowbit(x)) bit[x]+=v;}
int getsum(int x)
{
    int res=0;
    for(;x;x-=lowbit(x)) res+=bit[x];
    return res;
}


bool judge(int x)
{
    sum[0]=N+1; // sum最小可能是-N+1
    for(int i=1;i<=N;i++) sum[i]=sum[i-1]+(a[i]>=x?1:-1);//前缀和
    for(int i=1;i<=2*N+1;i++) bit[i]=0; //初始化树状数组
    //由于是前缀和形式，要包括所有的区间，必然要加上sum[0]
    add(sum[0],1);
    LL cnt=0; // 正序对数量，即区间和>=0
    for(int i=1;i<=N;i++)
    {
        cnt+=getsum(sum[i]);
        add(sum[i],1);
    }
    return cnt >= 1LL*(N+1)*N/4;
}



int main()
{
    scanf("%d",&N);
    for(int i=1;i<=N;i++) scanf("%d",&a[i]),b[i]=a[i];
    // n*(n-1)/2个区间
    sort(b+1,b+1+N);
    int l=1,r=N,mid,ans;
    while(l<=r)
    {
        mid = l+(r-l)/2;
        if(judge(b[mid])) ans=mid,l=mid+1;
        else r=mid-1;
    }
    printf("%d",b[ans]);
	return 0;
}

