void merge(int l,int r){
	if(r-l<=1) return;
	int mid=(l+r)/2;
	merge(l,mid), merge(mid,r);//递归子问题
	int a=l, b=mid, p=a;
	while(a<mid || b<r){
		if(b>=r || (a<mid&&num[a]<num[b])){
			tmp[p++]=num[a++];
		}else{
			tmp[p++]=num[b++];
			ans+=mid-a;
		}
	}
	rep(i,l,r){
		num[i]=tmp[i];
	}
}

