int n, a[N], ps[N];
unordered_map<int, int> cnt;

ll check(ll num) {
	ll res = 0, now = 0;
	cnt.clear();
	cnt[0] = 1;
	for (int i = 0; i < n; i++) {
		ps[i] = (i? ps[i - 1]: 0) + (a[i] <= num? 1: -1);
		if(a[i] <= num)
			now += cnt[ps[i] - 1];
		else
			now -= cnt[ps[i]];
		cnt[ps[i]]++;
		res += now;
	}
	return res;
}

