struct BIT {
    int n;
    vector<int> v;

    BIT(int n) : v(n+1) {
        this->n = n;
    }

    void add(int a, int x) {
        for (int i = a; i <= n; i += i & -i)
            v[i] += x;
    }

    int sum(int a) {
        int res = 0;
        for (int i = a; i > 0; i -= i & -i)
            res += v[i];
        return res;
    }
};

int main() {
