    for (int i = 0; i < N; i++) {
        cin >> a[i];
        maxA = max(maxA, a[i]);
    }
    long long ml = (1LL + N) * N / 2;

    int low = 0, high = maxA+1;
    while (high - low > 1) {
        int mid = (low + high) / 2;

        BIT bit(N*2+2);
        int cs = N+1;
        long long res = 0;
        bit.add(cs, 1);
        for (int i = 0; i < N; i++) {
            cs += a[i] < mid ? -1 : 1;
            res += bit.sum(cs);
            bit.add(cs, 1);
        }

        if (res >= (ml+1)/2)
            low = mid;
        else
            high = mid;
    }
