    sortInputValue(vInput, vSortedVal);

    /* 2分探索 */
    DWORD dwBound = binarySearch(isMedianOfMedians, -1, MAX_DWORD, vInput, vSortedVal) - 1;

    /* 計算結果のインデックスを idx -> unique_val -> value の順に復元 */
    DWORD dwBoundUniqueVal = vSortedVal[dwBound];
    dwAnswer = dwBoundUniqueVal;
    printf("%d\n", dwAnswer);

