ll merge(vll &a, ll n, ll left, ll mid, ll right) {
    ll cnt = 0;
    ll n1 = mid - left;
    ll n2 = right - mid;
    vll a1(n1 + 1), a2(n2 + 1);
    REP(i, n1) a1[i] = a[left + i];
    REP(i, n2) a2[i] = a[mid + i];
    a1[n1] = a2[n2] = HIGHINF;
    ll i = 0, j = 0;
    rep(k, left, right) {
        if (a1[i] <= a2[j]) {
            a[k] = a1[i];
            i++;
        } else {
            a[k] = a2[j];
            j++;
            cnt += n1 - i;
        }
    }
    return cnt;
}

ll mergeSort(vll &a, ll n, ll left, ll right) {
    if (left + 1 < right) {
        ll mid = (left + right) / 2;
        ll v1 = mergeSort(a, n, left, mid);
        ll v2 = mergeSort(a, n, mid, right);
        ll v3 = merge(a, n, left, mid, right);
        return v1 + v2 + v3;
    } else return 0;
}

