ll inversed_pair(int a[],int n) {
    if (n == 1)return 0;
    ll sum = 0;
    int mid = (n >> 1);
    sum += inversed_pair(a, mid);
    sum += inversed_pair(a + mid, n - mid);
    int *b = new int[n];
    memcpy(b, a, n * sizeof(int));
    for (int i1 = 0, i2 = mid, i = 0; i1 < mid || i2 < n; ++i) {
        if (i2 == n) {
            a[i] = b[i1];
            ++i1;
            sum += i2 - mid;
        }
        else if (i1 == mid) {
            a[i] = b[i2];
            ++i2;
        }
        else if (b[i1] < b[i2]) {
            a[i] = b[i1];
            ++i1;
            sum += i2 - mid;
        }
        else {
            a[i] = b[i2];
            ++i2;
        }
    }
    delete[] b;
    return sum;
}

