template<typename Up, typename Eval, typename T>
class SegmentTree{
private:
    const Up up; // 更新関数
    const Eval eval; // 評価関数
    vector<T> seg;
    int sz = 1;
    T unit;
public:
    explicit SegmentTree(int n,Up&& f,Eval&& g,T unit=0)noexcept: up(std::forward<Up>(f)), eval(std::forward<Eval>(g)), unit(unit){
        while (sz < n) sz <<= 1;
        seg.resize(sz * 2, unit);
    }
    constexpr void update(int k, T v) noexcept {// k 番目の値をup(seg[k],v)にする
        k += sz - 1;
        seg[k] = up(seg[k], v);
        while (k > 0) {
            k = (k - 1) / 2;
            seg[k] = up(seg[2 * k + 1], seg[2 * k + 2]);
        }
    }
    constexpr void set(const int& k, const T& x) noexcept {//左からk番目の葉にxを代入する
        seg[sz - 1 + k] = x;
    }
    constexpr T get(const int& k) noexcept {//左からk番目の葉を得る
        return seg[sz - 1 + k];
    }
    constexpr T query(int a, int b) noexcept {//[a,b)のupの合成を求める
        int k = 0, l = 0, r = sz;
        return query(a, b, k, l, r);
    }
    constexpr T query(int a, int b, int k, int l, int r) noexcept {//[a,b)のupの合成を求める(a,b,0,0,sz)のように使う
        if (r <= a || b <= l) {
            return unit;
        }
        if (a <= l && r <= b) {
            return seg[k];
        }
        else {
            T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return up(vl, vr);
        }
    }
};

template<typename Up,typename Eval,typename T>
constexpr static inline SegmentTree<Up, Eval, T>
makeSegmentTree(int n,Up&& up,Eval&& eval,T unit=0) noexcept {
    return SegmentTree<Up,Eval,T>(n,std::forward<Up>(up),std::forward<Eval>(eval),unit);
}

