int64_t inversion_number(vector<T>& a) { // i<jかつa_i>a_jとなる(i,j)の数
    auto up = [](T& a,T b){
        return b;
    };
    auto eval = [](T& a,T b){
        return a + b;
    };
    int n = (int)a.size();
    int64_t res = 0;
    using p = pair<T,int>;
    vector<p> c(n);
    for (int i = 0; i < n; ++i) {
        c[i].first = a[i];
        c[i].second = i;
    }
    sort(c.begin(), c.end());
