    auto st2 = SegmentTree<decltype(up), decltype(eval), int>(n, std::move(up),std::move(eval), 0);
    auto st = makeSegmentTree(n,move(up),move(eval),0);
    int k = 1;
    for (int i = 0; i < n; ++i) {
