void mergesort(int* A, int N0) {
	if (N0 > 2) {
		int N1 = N0 / 2;
		int N2 = N0 - N1;
		mergesort(A, N1);
		mergesort(A + N0 / 2, N2);

		int itr1 = 0;
		int itr2 = 0;
		vector<int> V;
		rep(i, N0) {
			if (N1 > itr1 && N2 > itr2) {
				if (A[itr1] > A[N1 + itr2]) {
					V.push_back(A[N1 + itr2]);
					itr2++;
					tentou += N1 - itr1;
				}
				else {
					V.push_back(A[itr1]);
					itr1++;
				}
			}
			else if (itr1 == N1) { V.push_back(A[N1 + itr2]); itr2++; }
			else { V.push_back(A[itr1]); itr1++; }
		}
		rep(i, N0) A[i] = V[i];
	}
	else if (N0 == 2) {
		if (A[0] > A[1]) {swap(A[0], A[1]);	tentou++;}
	}
}

