// Binary Indexed Tree （indexは1始まり）
// T は +-*/ と 0 を持つ
template<class T> class BIT {
private:
	int N; // 要素数
	vector<T> nodes;

public:
	BIT(int N) {
		this->N = N;
		nodes.assign(N+1, 0);
	}

	// index k の値にxを加える
	void add(int k, T x) {
		for (int i=k; i<=N; i += (i & -i)) {
			nodes[i] += x;
		}
	}

	// 半開区間 [0, k) の合計を返す
	T sum(int k) {
		T result = 0;
		for (int i=k-1; i>0; i -= (i & -i)) {
			result += nodes[i];
		}

		return result;
	}

	// 半開区間 [s, t) の合計を返す
	T sum(int s, int t) {
		return sum(t) - sum(s);
	}
};

// 反転数の数を求める
ll count_num_of_inv() {
	BIT<ll> bit(N+1);
	unordered_map<int, int> d_to_i;

	reverse(d+1, d+N+2);

	for (int i=1; i<=N+1; i++) {
		d_sorted[i] = d[i];
	}

	sort(d_sorted+1, d_sorted+N+2);

	for (int i=1; i<=N+1; i++) {
		if (d_to_i[d_sorted[i]] == 0) d_to_i[d_sorted[i]] = i;
	}

	ll result = 0;

	for (int i=1; i<=N+1; i++) {
		result += bit.sum(d_to_i[d[i]]+1, N+2);
		bit.add(d_to_i[d[i]], 1);
	}

	return result;
}

bool is_ok(int k) {
	for (int i=0; i<N; i++) {
		if (a[i] <= k) {
			b[i] = 1;
		} else {
			b[i] = 0;
		}
	}

	c[0] = 0;
	for (int i=0; i<N; i++) {
		c[i+1] = c[i] + b[i];
	}

	for (int i=0; i<=N; i++) {
		d[i+1] = 2 * c[i] - i;
	}

	return count_num_of_inv() > (ll)N * (N+1) / 4;
}

ll find_min_ok(ll lower, ll upper) {
	ll ok = upper - 1;
	ll ng = lower - 1;

	while(ok - ng > 1) {
		ll trying = (ng + ok) / 2;

		if (is_ok(trying)) {
			ok = trying;
		} else {
			ng = trying;
		}
	}

	return ok;
}

