void point_change(int now,int l,int r,int loc,int data)
{
	if(l==r)
	{
		seg[now]+=data;
		return ;
	}	
	if(loc<=mid)point_change(now*2,l,mid,loc,data);
	else point_change(now*2+1,mid+1,r,loc,data);
	update(now);
}
int ck_find(int now,int l,int r,int ll,int rr)
{
	if(ll<=l&&r<=rr)
	{
		return seg[now];
	}
	int ans=0;
	if(ll<=mid)ans+=ck_find(now*2,l,mid,ll,rr);
	if(mid+1<=rr)ans+=ck_find(now*2+1,mid+1,r,ll,rr);
	return ans;
}
int check(int ans)
{
	for(int i=1;i<=n;i++)
	  if(a[i]>ans)b[i]=1;
	  else b[i]=-1;
	sum[0]=0;
	for(int i=1;i<=n;i++)
	  sum[i]=sum[i-1]+b[i],c[i]=sum[i];
	sort(c+1,c+1+n);
	int m=unique(c+1,c+1+n)-c-1;
	for(int i=1;i<=n;i++)
	{
		sum[i]=lower_bound(c+1,c+1+m,sum[i])-c;
	}
	int bigger=0;
	int smaller=0;
	for(int i=n;i>=1;i--)
	{
		smaller+=ck_find(1,1,n,1,sum[i]-1);
		point_change(1,1,n,1,sum[i]);
	}
	for(int i=1;i<=n;i++)
	  copy_sum[i]=sum[n-i+1];
	memset(seg,0,sizeof(seg));
	for(int i=n;i>=1;i--)
	{
		bigger+=ck_find(1,1,n,1,copy_sum[i]-1);
		point_change(1,1,n,1,copy_sum[i]);
	}
	int self=(n-1)*n/2;
	if(bigger-smaller<=self||smaller-bigger<=self)return 0;
	else if(bigger-smaller>self)return -1;
	else return 1;
}
