bool kiwosorasetai(ll median)
{
	ll sum[100010];
	ll cnt = 0;
	for (int i = 0; i <= N; i++)
	{
		sum[i] = 0;
	}
	for (int i = 0; i < N; i++)
	{
		if (a[i] < median)
		{
			sum[i + 1] = sum[i] - 1;
		}
		else
		{
			sum[i + 1] = sum[i] + 1;
		}
	}

	for (int i = 0; i <= N; i++)
	{
		cnt += sum_bit(sum[i] + N + 1);
		add_bit(sum[i] + N + 1, 1);
	}

	return cnt * 2 >= (N + 1) * N / 2;
}

void solve()
{
