	ll lb = -1, ub = vec.size();
	while (lb + 1 < ub)
	{
		ll mid = (lb + ub) / 2;
		if (kiwosorasetai(vec[mid]))
		{
			lb = mid;
		}
		else
		{
			ub = mid;
		}
	}

	ans = vec[lb];
}

