          for (int64_t i=0; i < N ; i++ ){
          sum = sum + C.at(i);  
          H.at( N + sum )++ ;  
          } 

          int64_t S= 0; 
          for (int64_t i = N ; i < 2*N+1; i++) {
            S = S + H.at(i);  
