inline int lowbit(const int x){
    return x & (-x);
}

void add(vector<int> &c, const int p, const int d){
    for(int i = p; i < (int)c.size(); i += lowbit(i)){
        c[i] += d;
    }
}

int prf(const vector<int> &c, const int p){
    int foo = 0LL;
    for(int i = p; i; i -= lowbit(i)){
        foo += c[i];
    }
    return foo;
}

int check(const vector<int> &a, const int threshold){
    int n = a.size();
    lld foo = 0LL;
    vector<int> c(n + n + 1, 0);
    add(c, 0 + n, 1);
    int cur = 0;
    for(int i = 0; i < n; ++i){
        if(a[i] >= threshold){
            cur++;
        }else{
            cur--;
        }
        foo += prf(c, cur + n) * 1LL;
        add(c, cur + n, 1);
    }
    return foo >= (((1LL + n) * 1LL * n) / 2LL + 1LL) / 2LL;
}

int solution(const vector<int> &a, const vector<int> &b){
    int lef = 0, rig = b.size() - 1;
    while(lef < rig){
        const int mid = (lef + rig) >> 1;
        if(check(a, b[mid + 1])){
            lef = mid + 1; 
        } else {
            rig = mid;
        }
    }
    return b[lef];
}

