////////// 1-d BIT implementation //////////

// default constructor
template <class T> BIT<T>::BIT() : BIT(0) {}

// constructor. input is max-value of the data you want to deal
template <class T> BIT<T>::BIT(int n) : data(n + 1, (T)0), maxid{ n } {}

// initializer
template <class T> void BIT<T>::init(int n) { data.resize(n + 1, (T)0); this->maxid = n; }

template <class T> void BIT<T>::add(int idx, T val) { for (++idx; idx <= maxid; idx += idx & (-idx)) data[idx] += val; }

// sum up to idx (close-end)
template <class T> T BIT<T>::sum(int idx) { T ret{ 0 }; for (; idx > 0; idx -= idx & (-idx)) ret += data[idx]; return ret; }

// sum for [l, r)
template <class T> T BIT<T>::sum(int left, int right) { return sum(right - 1) - sum(left - 1); }

template <class T> T BIT<T>::operator[](int i) { return sum(i) - sum(i - 1); }

////////// END of 1-d BIT implementation //////////

