inline bool chk(li x) {
    li base = n + 1;
    Segtree<li> cnt(base * 2 + 1, 0, 0, [](li a, li b) {return a + b;});
    li all = n * (n + 1) / 2;
    li res = 0;
    li now = base;
    cnt.update(base, 1);
