typedef long long ll;
ll n, a[100005], b[100005], p[100005], pp[100005];

ll cdq(ll l, ll r)
{
	if (l == r) return 0;
	ll mid = (l + r) / 2;
	ll ret = cdq(l, mid) + cdq(mid + 1, r);
	ll i = l;
	ll now = l - 1;
	for (ll j = mid + 1; j <= r; j++)	
	{
		while (p[i] <= p[j] && i <= mid)
		{
			pp[++now] = p[i];
			i++;
		}
		pp[++now] = p[j];
		if (i > mid) 
		{
			for (ll k = j + 1; k <= r; k++) pp[++now] = p[k];
			break;
		}
		ret += (mid - i + 1);
	}
	for (ll k = i; k <= mid; k++) pp[++now] = p[k];
	for (ll i = l; i <= r; i++) p[i] = pp[i];
	return ret;
}

ll erfen(ll l, ll r)
{
	memset(p, 0, sizeof(p));
	if (l == r) return l;
	ll mid = (l + r) / 2;
	ll rel = b[mid];
	for (ll i = 1; i <= n; i++)
	{
		p[i] = p[i - 1];
		if (a[i] > rel) p[i]++;
		else p[i]--;
	}
	ll num = cdq(0, n);
	if (num >= ((n + 1) * n / 2) / 2 + 1) return erfen(l, mid);
	else return erfen(mid + 1, r);
}

