// フェンウィックツリー(バイナリーインデクスドツリー)
//sum(l,r) = [l, r)の和, add(i, a) = 0-indexedでi番目の要素にaを足す
template <class T>
struct fenwick_tree {
    int n;
    vector<T> x;
    fenwick_tree(int n_ = 0) : n(n_), x(n + 1, 0) {}
    int size() const { return n; }
    T sum(int r) const {
        T S = 0;
        for (r = r - 1; r >= 0; r = (r & (r + 1)) - 1) S += x[r];
        return S;
    }
    T sum(int l, int r) const { return sum(r) - sum(l); }
    void add(int k, const T &a) {
        for (; k < n; k |= k + 1) x[k] += a;
    }
    void set(int k, const T &a) { add(k, a - sum(k, k + 1)); }
};

// 判定関数 f(x): T → bool ( x∈[s,t) ) が false から true に変わる
// 広義単調増加であるとき f(x) = true となる最小の x を求める
// 返り値が t のときは任意の x について false ということ
template <class Function>
int binary_search_int (int s, int t, Function f) {
    int ng = s - 1, ok = t;
    while (ok - ng > 1) {
        int mid = (ng + ok) / 2;
        (f(mid) ? ok : ng) = mid;
    }
    return ok;
}

int main(void) {
