        //lint k = 5;
        vector<int> b(n+1, 0), c(n+1, 0);
        const lint SFT = 1e6;
        fenwick_tree<lint> ft(n+SFT);

        // 中央値が k 以下か？　⇔　k 以下の数が N/2 より大
        repeat (i, n) {
            b[i+1] = (a[i+1] <= k) ? -1 : +1;
        }

        repeat (i, n) {
            c[i+1] = c[i] + b[i+1];
        }
        lint cnt = 0;

        repeat (i, n+1) {
            //dump(i); dump(c[i]); dump(cnt); el;
            cnt += ft.sum(c[i]+SFT+1, n+SFT);
            ft.add(c[i]+SFT, 1);
        }
        //dump(cnt); el;
