class BIT {
  public:
    void init(ll size) {
      bit.resize(size + 1, 0);
    }
    ll sum(ll i) {
      if (!i) {
        return 0;
      }
      return bit[i] + sum(i - (i & -i));
    }

    void add(ll i, ll x) {
      if (i >= (ll)bit.size()) {
        return;
      }
      bit[i] += x;
      add(i + (i&-i), x);
    }
    std::vector<ll> bit;
};

