    FOREACH(s, sum) s += N + 1;
    auto num = BIT<ll>(2 * N);
    FOR(i, 1, N + 1) {
        S += num.sum(sum[i]);
        num.plus(sum[i], 1);
    }
    return 2 * S >= all;
}

