int binary(){
  int L = 0,R = 1000000010; // [L,R]の範囲内に解
  int mid = (L+R)/2;

  while(L<R){
    if(check(mid)) {
      R = mid;
    }
    else {
      L = mid+1;
    }
    mid = (L+R)/2;
  }

  return mid-1;
}

