typedef pair<ll, ll> p_ll;

struct SegTree {
  int n_count;
  vector<ll> pos;

  SegTree(int N) {
    n_count = 1; while(n_count<N) n_count<<=1;
    pos.resize(2*n_count, 0);
  }

  ll operator[](const int &k) const { return pos[k+n_count]; }

  void set(int k, const ll x) { pos[k+n_count] = x; }
  void build() { for (int i=n_count-1; i>=0; i--) pos[i] = pos[i*2] + pos[i*2+1]; }
  void update(int k, const ll x) { set(k,x); k += n_count; while(k >>= 1) pos[k] = pos[k*2] + pos[k*2+1]; }
  ll query(int a,int b) {
    ll L = 0, R = 0;
    for ( a+=n_count, b+=n_count; a<b; a>>=1, b>>=1 ) {
      if (a&1) { L+=pos[a]; a++; }
      if (b&1) { b--; R+=pos[b]; }
    }
    return L + R;
  }

};

int main() {
  ll N; cin >> N;
  int a[N]; rep(i,N) cin >> a[i];

  ll choice = N*(N+1)/2;
  int l = 0, r = pow(10,9);
  while(l!=r) {
    ll m = (l+r+1)/2;
    p_ll sum[N+1]; sum[0] = make_pair(0,0);
    rep(i,N) {
      int tmp = sum[i].second;
      tmp += (a[i]>=m) ? 1 : -1;
      sum[i+1] = make_pair(i+1, tmp);
    }
    sort(sum, sum+N+1, [](const p_ll &x, const p_ll &y) {return x.second<y.second;});
    rep(i,N+1) sum[i].second = i;
    sort(sum, sum+N+1, [](const p_ll &x, const p_ll &y) {return x.first<y.first;});

    SegTree tree(N+1);
    ll count = 0;
    rep(i,N+1) {
      count += tree.query(0,sum[i].second);
      tree.update(sum[i].second,1);
    }
    // rep(i,N+1) cout << sum[i].second << "-"; cout << endl;
    // cout << count << " " << l << " " << m << " " << r << endl; cout << endl;
    if (count>=(choice+1)/2) l = m;
    else r = m-1;
  }
  int result = l;
  cout << result << endl;
  return 0;
}

