#define mod 1000000007

struct segtree {
    long long int N;
    vector<long long int> v;

    segtree(long long int n) {
        N = 1;
        while(N < n) N *= 2;
        v = vector<long long int>(2 * N, 0);
    }
    // update k th element
    void update(long long int k, long long int a) {
        k += N-1; // leaf
        v[k] = a;
        while(k > 0) {
            k = (k - 1) / 2;
            v[k] = v[k*2+1] + v[k*2+2];
        }
    }
    // sum [a, b)
    long long int query(long long int a, long long int b) { return query(a, b, 0, 0, N); }
    long long int query(long long int a, long long int b, long long int k, long long int l, long long int r) {
        if(r <= a or b <= l) return 0;
        if(a <= l and r <= b) return v[k];
        long long int m = (l + r) / 2;
        return query(a, b, k*2+1, l, m) + query(a, b, k*2+2, m, r);
    }
};

