		cout << a[0] << endl;
		return 0;
	}

	long long int l = 0, r = mod;
	while(r - l > 1){
		long long int mid = (l + r) / 2;
		// ある区間において中央値はmid以上になるか？
		// <-> ある区間において、mid以上の値の個数はmid未満の値の個数より大きいか？
		// cnt[i] = a[0]からa[i - 1]までの(mid以上の個数 - mid未満の個数)とすると、
		// 区間[l, r)において(mid以上の個数 - mid未満の個数)はcnt[r] - cnt[l]となる
		// (mid以上の個数 > mid未満の個数)より cnt[r] - cnt[l] >= 0となればよい
		// つまりcnt[r] >= cnt[l]となるような[l, r)の個数を求め、これが(n * (n + 1) / 2) / 2より大きければ
		// 中央値の中央値はmid以上であるとわかる
		vector<pair<long long int, long long int> > cnt;
		cnt.push_back(make_pair(0, 0));
		long long int rangenum = 0;
		for(long long int i = 1; i <= n; i++){
			cnt.push_back(make_pair(cnt[i - 1].first + ((a[i - 1] >= mid) ? 1 : -1), i));
			if(a[i - 1] >= mid) rangenum++;
		}
		auto itr = cnt.begin();
		itr++;
		sort(itr, cnt.end());
		segtree st(n + 1);
		for(long long int i = 1; i < n + 1; i++){
			// cout << cnt[i].first << " " << cnt[i].second << endl;
			st.update(cnt[i].second, 1);
			rangenum += st.query(0, cnt[i].second);
		}
		// cout << mid << " " << rangenum << endl;
		if(rangenum >= (n * (n + 1) / 2) / 2) l = mid;
		else r = mid;
	}
	cout << l << endl;
}

