            add(c[i], 1, 2 * n + 1);
        }
        tmp = n * (n + 1) / 2 - tmp;
        if(tmp >= n * (n + 1) / 4 + 1) {
            r = m;
        } else {
            l = m;
        }
    }
    cout << r << endl;
}

