inline int gi() {
    register int data = 0, w = 1;
    register char ch = 0;
    while (!isdigit(ch) && ch != '-') ch = getchar(); 
    if (ch == '-') w = -1, ch = getchar(); 
    while (isdigit(ch)) data = 10 * data + ch - '0', ch = getchar(); 
    return w * data; 
} 
const int MAX_N = 1e5 + 5; 
int N, MAX, a[MAX_N], b[MAX_N]; 
long long goal_rank;
int c[MAX_N << 2]; 
inline int lb(int x) { return x & -x; } 
void add(int x, int v) { while (x <= MAX) c[x] += v, x += lb(x); } 
int sum(int x) { int res = 0; while (x) res += c[x], x -= lb(x); return res; } 
bool check(int mid) { 
	static int s[MAX_N]; 
	for (int i = 1; i <= N; i++) { 
		int op; 
		if (a[i] > mid) op = 1; 
		if (a[i] <= mid) op = -1; 
		s[i] = s[i - 1] + op; 
	} 
	long long res = 0; 
	MAX = N << 2; 
	int T = N << 1; 
	for (int i = 1; i <= N; i++) { 
		int pos = s[i] + T; 
		res += sum(MAX) - sum(pos); 
		add(pos, 1); 
	} 
	memset(c, 0, sizeof(c)); 
	return res >= goal_rank; 
} 
bool cheque(int mid) { 
	static int s[MAX_N]; 
	for (int i = 1; i <= N; i++) { 
		int op; 
		if (a[i] > mid) op = 1; 
		if (a[i] < mid) op = -1; 
		if (a[i] == mid) op = 0; 
		s[i] = s[i - 1] + op; 
	} 
	long long res = 0; 
	MAX = N << 2; 
	int T = N << 1;
	add(T, 1); 
	for (int i = 1; i <= N; i++) { 
		int pos = s[i] + T; 
		res += sum(MAX) - sum(pos); 
		add(pos, 1); 
	} 
	memset(c, 0, sizeof(c)); 
	return res >= goal_rank; 
} 

int main () {
	N = gi(); for (int i = 1; i <= N; i++) a[i] = b[i] = gi(); 
	sort(&b[1], &b[N + 1]); 
	goal_rank = 1ll * N * (N - 1) / 2 + N; 
	goal_rank = goal_rank / 2; 
	int l = 1, r = N, ans = 1; 
	while (l <= r) {
		int mid = (l + r) >> 1;  
		if (check(b[mid])) r = mid - 1, ans = mid; 
		else l = mid + 1; 
	}
	l = 1, r = N;
	int res = 1; 
	while (l <= r) { 
		int mid = (l + r) >> 1;  
		if (cheque(b[mid])) r = mid - 1, res = mid; 
		else l = mid + 1; 
	} 
	printf("%d\n", b[min(ans, res)]); 
    return 0; 
}

