    int mid=(l+r)/2;
    ll ans=0;
    if(mid<=L) ans+=ask(rt<<1,L,R,l,mid);
    if(mid>R) ans+=ask(rt<<1|1,L,R,mid+1,r);
    return ans;
}

void update(int rt,int l,int r,int k){
    if(l==r){
        sum[rt]++;
        return;
    }
    int mid=(l+r);
    if(k<=mid) update(rt<<1,l,mid,k);
    if(k>mid) update(rt<<1|1,mid+1,r,k);
    sum[rt]=sum[rt<<1|1]+sum[rt<<1];
}

