int main() {

  lint n; cin >> n;
  vector<lint> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }

  lint m = (n + 1) * n / 2;

  lint ok = 1;
  lint ng = 1e9 + 1;
  while (ng - ok > 1) {
    lint mid = (ok + ng) / 2;

    // mid 以上の要素を半分以上含む区間の個数を計算
    vector<lint> acc(n + 1, 0);
    for (int i = 1; i <= n; i++) {
      if (a[i - 1] >= mid) acc[i] = 1;
      else acc[i] = -1;
      acc[i] += acc[i - 1];
    }

    using T = int;  // type T
    using E = int;  // type E
    auto f = [](T a, T b){ // return type T value
      return a + b;
    };
    auto g = [](T a, E b){ // return type T value
      return b;  // return b;
    };
    T ti = 0;  // identity element
    SegmentTree<T, E, decltype(f), decltype(g)> sg(f, g, ti);  // don't change
    sg.build(vector<int> (n + 1, 0));

    vector<pair<int, int>> info;
    for (int i = 0; i <= n; i++) {
      info.push_back({acc[i], i});
    }

    sort(RALL(info));
    lint cnt = 0;
    for (auto i : info) {
      int id = i.second;
      cnt += sg.query(id, info.size() + 1);
      sg.update(id, 1);
    }

    if (cnt >= (m - 1 + 2) / 2) ok = mid;
    else ng = mid;
  }

  cout << ok << endl;
  return 0;
}

