typedef long long LL;

const int MAXN = 1e5;
int n, a[MAXN + 5], ord[MAXN + 5];

struct BinaryIndexTree {
	int siz, val[MAXN * 2 + 5];
	inline int lowbit ( const int x ) { return x & -x; }
	inline void init ( const int s ) {
		siz = s;
		for ( int i = 0; i <= siz; ++ i ) val[i] = 0;
	}
	inline void update ( const int x, const int k ) {
		for ( int i = x; i <= siz; i += lowbit ( i ) ) {
			val[i] += k;
		}
	}
	inline int presum ( const int x ) {
		int ret = 0;
		for ( int i = x; i; i -= lowbit ( i ) ) {
			ret += val[i];
		}
		return ret;
	}
} bit;

inline bool check ( const int x ) {
	static int lim = n * ( n + 1ll ) >> 2, tmp[MAXN + 5], s[MAXN + 5]; s[0] = 0;
	for ( int i = 1; i <= n; ++ i ) tmp[i] = a[i] >= x ? -1 : 1;
	for ( int i = 1; i <= n; ++ i ) s[i] = s[i - 1] + tmp[i];
	LL sum = 0;
	bit.init ( n << 1 | 1 ), bit.update ( n + 1, 1 );
	for ( int i = 1; i <= n; ++ i ) {
		sum += bit.presum ( s[i] + n );
		bit.update ( s[i] + n + 1, 1 );
	}
	return sum <= lim;
}

