// Rytter
long long count_inversions(vector<int> seq) {
    long long result = 0;
    const size_t n = seq.size();
    for (size_t i = 0; i < __lg(2 * n); i++) {
        auto cnt = vector<int>(n * 2 + 1, 0);
        for (auto &x : seq) {
            if (x % 2 == 1) {
                cnt[x] += 1;
            } else {
                result += cnt[x + 1];
            }
            x >>= 1; 
        }
    }

    return result;
}

