class BinaryIndexedTree {
public:
  static const int MAX_N_LIB = (int)(2e5 + 100);

  ll bit_arr[MAX_N_LIB];
  int bit_n;

  BinaryIndexedTree(int n) {
    bit_n = n;
    init();
  }

  void init() {
    for (int i = 0; i < bit_n; ++i) bit_arr[i] = 0LL;
  }

  ll sum(int i) {
    ll s = 0LL;
    while (i > 0) {
      s += bit_arr[i];
      i -= i & -i;
    }
    return s;
  }

  void add(int i, ll x) {
    while (i <= bit_n) {
      bit_arr[i] += x;
      i += i & -i;
    }
  }
};
