            else
                b[i] = -1;
        }
        for (int i = 1; i < n; ++i) {
            b[i] += b[i - 1];
        }
        BinaryIndexedTree<ll> bit(2 * n + 2);
        bit.add(n, 1); // n == 0
        ll sum = 0;
        for (int i = 0; i < n; ++i) {
            sum += bit.query(0, n + b[i] + 1);
            bit.add(n + b[i], 1);
        }
        return sum >= (n * (n + 1) / 2 + 1) / 2;
    };
