    int i;
    for (i=x;i<=2*n+1;i+=lowbit(i)) c[i]+=val;
}

long long sum(int x)
{
    x+=(n+1);
    int i;
    long long ans=0;
    for (i=x;i>0;i-=lowbit(i)) ans+=c[i];
    return ans;
}

long long work(int num)
{
    int i,tmp=0;long long ans=0;
    for (i=1;i<=n;i++)
    {
        if (a[i]<=num) tmp++; else tmp--;
        ans+=sum(tmp-1);
        add(tmp,1);
    }
    tmp=0;
    for (i=1;i<=n;i++)
    {
        if (a[i]<=num) tmp++; else tmp--;
        add(tmp,-1);
    }
    return ans;
}

