    rep(i, n) cin >> a[i];

    ll l = 1, r = 1e9 + 7;
    ll threshold = n * (n + 1) / 2;
    threshold = (threshold + 1) / 2;
    while (r - l > 1) {
        ll mid = (r + l) / 2;
        ll score = 0;
        BIT fwt(200200);

        // to prevent a negative index
        ll pref_sum = 1e5;
        // the pref_sum of an empty array is always 0
        fwt.add(pref_sum, 1);

        rep(i, n) {
            pref_sum += (mid <= a[i] ? 1 : -1);
            score += fwt.sum(pref_sum);
            fwt.add(pref_sum, 1);
        }
        if (score >= threshold) {
            l = mid;
        } else {
            r = mid;
        }
    }
    cout << l << endl;
}

