template <typename T>
struct BIT{
	vector<T> v;
	int n;

	const T init_value = 0;

	BIT(int sz){
		n=sz+1;
		v.resize(n,init_value);
	}

	BIT(vector<T> &x){
		n=x.size()+1;
		v.resize(n,init_value);

		for(int i=0;i<x.size();i++){
			add(i,x[i]);
		}

	}

	void add(int x,T val){
		x++;
		while(x < n){
			v[x] = func(v[x],val);
			x += x & (-x);
		}
	}

	//区間[0,r)におけるクエリ処理
	T query(int r){
		T ret = init_value;

		while(r>0){
			ret = func(v[r],ret);
			r -= r & (-r);
		}

		return ret;
	}

	T query(int l,int r){
		return query(r) - query(l);
	}

	T func(T a,T b){
		return a+b;
	}

};

int main(){

	long long N;
	cin>>N;

	long long need = (N*(N+1)/2 +1)/2;//need以上要る

	vector<long long> a(N);
	for(int i=0;i<N;i++)cin>>a[i];

	long long ok = 0;
	long long ng = Inf;

	while(ng-ok>1){
		long long mid = (ok+ng)/2;
		long long offset = N;
		BIT<long long> B(2*N+1);
		B.add(offset,1);
		long long S = 0;
		long long cnt = 0;
		for(int i=0;i<N;i++){
			if(mid<=a[i])S++;
			else S--;
			cnt += B.query(0,offset+S+1);
			B.add(offset+S,1);
		}
		if(cnt>=need)ok = mid;
		else ng = mid;
	}

	cout<<ok<<endl;

	return 0;
}

