#include <bits/stdc++.h>
typedef long long ll; 

using namespace std;

template <class T>
struct BIT {
	vector<T> data;
	BIT(int n) {
		data.assign(n, 0);
	}

	T sum (int i) {
		T res = 0;
		while (i > 0) {
			res += data[i];
			i -= i & -i;
		}
		return res;
	}

	void add(int i, T x) {
		while (i < data.size()) {
			data[i] += x;
			i += i & -i;
		}
	}
};

int main() {
	int N;
	cin >> N;
	vector<ll> a(N + 1);
	vector<ll> x(N);
	for (int i = 1; i <= N; ++i) { 
		cin >> a[i];
		x[i - 1] = a[i];
	}
	sort(x.begin(), x.end());
	x.erase(unique(x.begin(), x.end()), x.end());

	ll Mlen = (1 + N) * N / 2;
	ll Mlenc = (Mlen + 1) / 2;

	int l = 0, r = x.size();
	while (r - l > 1) {
		int mid = (r + l) / 2;

		vector<ll> d(N + 1, 0);
		for (int i = 1; i <= N; ++i) {
			if (a[i] >= x[mid]) { d[i] += d[i - 1] + 1; }
			else { d[i] += d[i - 1] - 1; }
		}

		BIT<ll> bit(2 * N + 2);
		ll inv = 0;
		for (int i = 0; i < N + 1; ++i) {
			inv += bit.sum(2 * N + 1) - bit.sum(d[i] + N + 1);
			bit.add(d[i] + N + 1, 1);
		}

		ll wl = (1 + N) * N / 2 - inv;
		if (wl >= Mlenc) { l = mid; }
		else { r = mid; }
	}

	cout << x[l] << endl;
	return 0;
}

