void MergeSort(int le, int ri) {//归并排序求 区间内多少序列和为正数 即s[r] >s[l]且r>l  
    if( le == ri ) return ;
    int mid = (le + ri) >> 1;
    MergeSort(le, mid);
    MergeSort(mid+1, ri);
    int p = le, q = mid+1, r = le;
    while( p <= mid && q <= ri ) {
        if( sum[p] < sum[q] ) {  
            temp[r++] = sum[p++];
        }
        else {    //当s[p]>=s[q]时 说明P前面的数是小于S[Q]的 
            tot1 += (p-le);
            temp[r++] = sum[q++];
        }
    }
    while( p <= mid ) {
        temp[r++] = sum[p++];
    }
    while( q <= ri ) {   //P已经排结束 说明  剩下的Q 都比P前面的数大
        tot1 += (p-le);
        temp[r++] = sum[q++];
    }
    for(int i=le;i<=ri;i++)
        sum[i] = temp[i];
}
