    int mid=(s+t)/2;
    msort(s,mid);             
    msort(mid+1,t);      
    int i=s, j=mid+1, k=s;   
    while(i<=mid && j<=t)
    {
    	if(d[i]<=d[j])  
        {
            r[k]=d[i];
            k++; 
