            r[k]=d[j]; k++; j++;
        }
    }  
    while(i<=mid)
    {
        r[k]=d[i]; k++; i++;
    }
    while(j<=t)  
    {
        r[k]=d[j]; k++; j++;
    }
    for(int i=s; i<=t; i++) d[i]=r[i];  
    return;
} 

