int N;
int bit[200003], n;

int sum(int i) {
    int s = 0;
    while (i > 0) {
        s += bit[i];
        i -= i & -i;
    }
    return s;
}
void add(int i, int x) {
    while (i <= n) {
        bit[i] += x;
        i += i & -i;
    }
}

bool f(int x, vector<int> a) {
    vector<int> b, S(N,0);
    for (int i = 0; i < a.size(); i++) {
        if (a[i] >= x) b.push_back(1);
        else b.push_back(-1);
    }
    S[0] = b[0];
