typedef long long ll;

struct fenwick_tree {
    typedef int T;
    T n;
    vector<T> bit;
    fenwick_tree(T num) : bit(num+1, 0) { n = num; }
    void add(T i, T w) {
        for (T x = i; x <= n; x += x & -x) {
            bit[x] += w;
        }
    }
    T sum(T i) {
        T ret = 0;
        for (T x = i; x > 0; x -= x & -x) {
            ret += bit[x];
        }
        return ret;
    }
};

ll a[100005];

bool judge(ll mid, ll n) {
    // offset => 履かせる下駄
    int offset = n+1;
    ll num_inverse = 0;
    fenwick_tree bit(n*2+10);

    int sum_v = 0;
    bit.add(offset, 1);

    for (int i = 0; i < n; i++) {
        int s = (a[i] <= mid) ? 1 : -1;
        sum_v += s;
        num_inverse += (bit.sum(sum_v-1+offset));
        bit.add(sum_v+offset, 1);
    }
    return num_inverse > (n+1)*n/2/2; 
}

