vector<ll> d(N,0);

ll cnter(ll x, ll y){
	map<ll,ll> BIT;
	b[0]=0; d[0]=1;
	REP(i,y){
		if (a[i]<x) b[i+1]=b[i]-1;
		else b[i+1]=b[i]+1;
		c[i+1]=b[i+1];
	}
	sort(c.begin(),c.begin()+y+1);
	FOR(i,1,y){
		if (c[i]==c[i-1]) d[i]=d[i-1];
		else d[i]=d[i-1]+1;
	}
	REP(i,y+1) b[i]=d[lower_bound(c.begin(),c.begin()+y+1,b[i])-c.begin()];
	ll ans = 0;
	REP(i,y+1){
		ll p = b[i];
		ll q = b[i];
		while(p>0){
			ans+=BIT[p];
			p-=p&-p;
		}
		while(q<d[y]+1){
			BIT[q]++;
			q+=q&-q;
		}
	}
	return ans;
}

