ll n,s[100500];
ll solve(ll p) {
    vector<ll> k(2*n+1);
    ll sum=n;
    k[sum]=1;
    ll add=1;
    ll res=0;
    for(int i=1;i<=n;i++) {
        if(s[i]<p) {
            add-=k[sum];
            sum--;
        }
        else {

            sum++;
            add+=k[sum];

        }
        res+=add;
        k[sum]++;
        add++;    
    }
    return res;
}


