const int N = 1e5 + 5;
const int MAX = (1 << 18);

int n, med;
ll z;
ll tab[N + 5], tree[2 * MAX + 5], pref[N + 5], tab1[N + 5];

void Update(int x){
	x += MAX;
	while(x >= 1){
		tree[x] ++;
		x /= 2;
	}
}

int Query(int x, int y){
	x += MAX;
	y += MAX;
	int res = tree[x];
	if(x != y){
		res += tree[y];
	}
	while(x / 2 != y / 2){
		if(x % 2 == 0){
			res += tree[x + 1];
		}
		if(y % 2 == 1){
			res += tree[y - 1];
		}
		x /= 2;
		y /= 2;
	}
	return res;
}

void Prep(const int &v){
	fill(tree, tree + MAX + MAX + 2, 0);
	fill(pref, pref + n + 1, 0);
	pref[0] = N;
	for(int i=1; i<=n; i++){
		if(tab[i] <= v){
			pref[i] --;
		}else{
			pref[i] ++;
		}
		pref[i] += pref[i - 1];
	}
}

bool Check(const int &v){
	Prep(v);
	int res = 0;
	for(int i=1; i<=n; i++){
		res += Query(pref[i] + 1, n + 1);
		Update(pref[i]);	
	}
	return res >= z;
}

