typedef long long int ll;

class BIT {
private:
  int N; // Number of nodes
  vector<int> tree; // array which represents the tree

public:
  BIT(int n) {
    N = n;
    tree = vector<int>(N+1,0);
  }

  void add(ll a, ll v) {
    for (int i=a; i<=N; i += i & -i) tree[i] += v;
  }

  int sum(ll a) {
    ll ret = 0;
    for (int i=a; i>0; i -= i & -i) ret += tree[i];
    return ret;
  }
};

void convert(ll arr[], int n) {
  ll temp[n];
  for (int i=0; i<n; ++i) {
    temp[i] = arr[i];
  }
  sort(temp,temp+n);

  for (int i=0; i<n; ++i) {
    arr[i] = lower_bound(temp, temp+n, arr[i]) - temp + 1; //arr[i]をソート値のインデックス(ただし1開始)に置き換え
  }
}

// aの転倒数を計算
int invCount(int a[], int n) {
  ll temp[n];
  for (int i=0; i<n; ++i) temp[i] = a[i];
  convert(temp, n);

  BIT bit = BIT(n);
  int count = 0;
  for (int i=n-1; i>=0; --i) { //右側から走査
    count += bit.sum(temp[i]-1); //現在値よりも小さい値で，右側（走査済み）にあった値の個数を追加
    bit.add(temp[i],1); //現在値の観測数を追加
  }

  return count;
}

// xが求めるmedianの候補であるか判定
bool check(ll x, ll a[], int n) {
  ll b[n];
  for (int i=0; i<n; ++i) {
    b[i] = (a[i] >= x) ? 1 : -1; //x以上の要素を1，他を-1に変換
  }

  //bの累積和を計算
  int S[n+1];
  S[0] = 0;
  for (int i=1; i<=n; ++i) {
    S[i] = S[i-1] + b[i-1];
  }

  return (n*(n+1)/2 - invCount(S,n+1)) >= (n*(n+1)/2 + 1)/2; //左辺はSのS[r]-S[l]>0である(l,r)(l<r)の組み合わせ数
}

