int sum(int i, int *bit)
{
    //printf("sum i:%lld\n", i);
    int s = 0;
    while(i > 0){
        //printf("sum::s += bit[%lld] %lld = %lld + %lld\n", i, s + bit[i], s, bit[i]);
        s += bit[i];
        i -= (i & (-i));
    }
    return s;
}

void add(int i, int x, int *bit)
{
    //printf("add i:%lld x:%lld\n", i, x);
    while(i <= N * 2 + 1){
        bit[i] += x;
        //printf("add::bit[%lld] = %lld\n", i, bit[i]);
        i += (i & (-i));
    }
}

bool C(int x)
{
    int bit[200010] = {0};
    int s[N + 1] = {0};
    int res = 0;
    for(int i = 0; i < N; i++){
        if(a[i] >= x){
            s[i] = 1;
            res++;
        }
        else s[i] = -1;
        if(i > 0)s[i] += s[i - 1];
    }
    for(int i = 0; i < N; i++){
        res += sum(N + 1 + s[i], bit);
        add(N + 1 + s[i], 1, bit);
    }
    return (res >= (N * (N + 1) / 2 + 1) / 2);
}

int binary(int lb, int ub)
{
    while(ub - lb > 1){
        int mid = (ub + lb) / 2;
        //printf("lb:%lld ub:%lld mid:%lld\n", lb, ub, mid);
        if(C(mid))lb = mid;
        else ub = mid;
    }
    return lb;
}

