void qsort(int a[],int L,int R)
{
	int i=L,j=R,x=a[(L+R)/2];
	while(i<=j)
	{
		while(a[i]<x)i++;
		while(a[j]>x)j--;
		if(i<=j)
		{
			swap(a[i],a[j]);
			i++;j--;
		}
	}
	if(L<j)qsort(a,L,j);
	if(i<R)qsort(a,i,R);
}
