	ll ng = *max_element(ALL(a))+1;
	ll th = ((N*(N+1))/2)%2?(N*(N+1))/4+1:(N*(N+1))/4;
	while(ng-ok>1){
		ll md = (ok + ng) / 2;
		auto b = a;
		FOR(i, 1, N+1) b[i] = ((b[i] >= md) ? 1 : -1);
		FOR(i, 1, N+1) b[i] += b[i - 1];
		Zarts Z;
        b=Z.solve(b);
		ll sum = 0;
		Binary_Indexed_Tree_Range_Sum_Query BIT(*max_element(ALL(b))+1);
		REP(i, N+1) {
			sum += BIT.getvar(b[i]);
			BIT.update(b[i], 1);
		}
		(sum>=th?ok:ng)=md;
	}
	print(ok);
}

