using namespace std;
using i64 = long long;
using vi64 = vector<i64>;

i64 n;
vi64 a;

i64 cnt;
vi64 merge(vi64 &v, int l, int r) {
  vi64 ret;
  if (l + 1 == r) {
    ret.push_back(v[l]);
    return ret;
  }
  vi64 a = merge(v, l, (l + r) / 2);
  vi64 b = merge(v, (l + r) / 2, r);
  int ai = 0, bi = 0;
  rep(i, r - l) {
    if (bi == b.size()) {
      ret.push_back(a[ai++]);
      cnt += bi;
    } else if (ai == a.size()) {
      ret.push_back(b[bi++]);
    } else {
      if (a[ai] <= b[bi]) {
        ret.push_back(a[ai++]);
        cnt += bi;
      } else {
        ret.push_back(b[bi++]);
      }
    }
  }
  return ret;
}

bool check(i64 md) {
  vi64 v(n), s(n + 1);
  cnt = 0;
  rep(i, n) {
    if (a[i] >= md) v[i] = 1;
    else v[i] = -1;
  }
  rep(i, n) {
    s[i + 1] += s[i] + v[i];
  }
  merge(s, 0, n + 1);
  return n * (n + 1) / 4 >= cnt;
}

