        {
            bit[i] = 0;
        }
    }
    // v[0] + ... + v[k-1]
    ll sum(ll k)
    {
        ll res = 0;
        for (ll i = k - 1; i >= 0; i = (i & (i + 1)) - 1)
        {
            res += bit[i];
        }
        return res;
    }
