inline void msort(int l,int r)
{
    if(l==r) return;
    int m=(l+r)>>1;
    msort(l,m);
    msort(m+1,r);

    int i=l,j=m+1;
    vector<int> v;
    while(i<=m&&j<=r)
    {
        if(a[i]<=a[j]) v.push_back(a[i++]),ans+=(j-m-1);
        else v.push_back(a[j++]);
    }

    while(i<=m) v.push_back(a[i++]),ans+=(j-m-1);
    while(j<=r) v.push_back(a[j++]);
    for(i=0;i<v.size();i++) a[l+i]=v[i];
}

