const int cmp(const int i, const int j) {
    return f[j] == f[i] ? i < j : f[i] < f[j];
}

ll inversed_pair() {
    memset(c, 0, sizeof(c));
    for (int i = 1; i <= n; ++i)r[i] = i;
    sort(r + 1, r + 1 + n, cmp);
    ll tot = 0;
    for (int i = 1; i <= n; ++i) {
        tot += read(r[i]);
        add(1, r[i]);
    }
    return tot;
}

bool check(int x) {
