int f(int k){
  RSQ v(200010); // 100005が基準

  int now = 100005;
  rep(i,0,n){
    if(a[i] < k) now++;
    else now--;
    v.update(now,1);
  }

  now = 100005;
  int ct = 0;

  rep(i,0,n){
    ct += v.rsum(now+1,200008);
    if(a[i] < k) {
      now++;
    }
    else {
      now--;
    }
    v.update(now,-1);
  }

  return ct;
}

bool check(int mid){ // ([...,0,0,0,"1",1,1,...])
  if(model <= f(mid)) return true;
  else return false;
}

int binary(){
  int L = 0,R = 1000000010; // [L,R]の範囲内に解
  int mid = (L+R)/2;

  while(L<R){
    if(check(mid)) {
      R = mid;
    }
    else {
      L = mid+1;
    }
    mid = (L+R)/2;
  }

  return mid-1;
}

