struct BIT{
   int sz;
   vector<int>nd;

   BIT(int n):nd(vector<int>(n+1,0)),sz(n){}

   int sum(int i){
      if(!i) return 0;
      return nd[i]+sum(i-(i&-i));
   }

   void add(int i,int x){
      if(i>sz)return;
      nd[i]+=x;
      add(i+(i&-i),x);
   }

};

