int nibutanL(int size) {// LEFTグループに属するうち最も右側のindexを得る
	int L = -1;
	int R = size;
	while (abs(R - L) > 1) {
		int mid = (L + R) / 2;
		if (judgeLR(mid) == RIGHT) R = mid;
		else L = mid;
	}
	return L;
}
int nibutanR(int size) {//RIGHTグループに属するうち最も左側のindexを得る
	return nibutanL(size) + 1;
}

