bool judgeLR(int x) {
	ll M = (ll)N * (ll)(N + 1) / 2;
	M = (M + 1) / 2;

	int offset = 100;
	for (int i = 0; i < N; i++) {
		if (A[i] >= x) {
			B[i] = 1;
		}
		else {
			B[i] = -1;
		}
		if (i > 0) {
			B[i] += B[i - 1];
		}

		offset = min(offset, B[i]);
	}

	offset -= 2;

	for (int i = 0; i < N_MAX; i++) {
		bit[i] = 0;
	}

	ll ans = 0;
	add(0 - offset, 1);
	for (int i = 0; i < N; i++) {
		B[i] -= offset;
		ans += (ll)sum(B[i]);
		add(B[i], 1);
	}

	if (ans >= M) { return LEFT; }
	else { return RIGHT; }
}

