	for (; x < N; x += lowbit(x)) {
		bit[x] += val;
	}
}

LL sum(LL x) {
	LL val = 0;
	x += n + 1;
	for (; x > 0; x -= lowbit(x)) {
		val += bit[x];
	}
	return val;
