LL sol(LL x) {
	LL tmp = 0, ans = 0;
	for (int i = 1; i <= n; i++) {
		if (a[i] <= x) {
			tmp++;
		} else {
			tmp--;
		}
		ans += sum(tmp - 1);
		add(tmp, 1);
	}
	tmp = 0;
	for (int i = 1; i <= n; i++) {
		if (a[i] <= x) {
			tmp++;
		} else {
			tmp--;
		}
		add(tmp, -1);
	}
	return ans;
}

