lli lower_med(const std::vector<lli>& a_arr, lli t){
  lli lower_count = 0, count_l = 0;
  for(lli i = 0; i < a_arr.size(); i++){
    if(a_arr[i] <= t){
      lower_count++;
      if(lower_count > 0){
        count_l++;
      }
    }
    else{
      lower_count--;
    }
  }
  return count_l*(count_l+1)/2;
}

