long long int merge_sort(int N, int a[]){
  int pivot=N/2;
  long long int merge=0;
  int left=0,right=0;
  int b[pivot+1],c[N-pivot+1];
  if(N==1) return 0;
  for(int i=0;i<pivot;i++) b[i]=a[i];
  for(int i=0;i<N-pivot;i++) c[i]=a[i+pivot];
  merge+=merge_sort(pivot,b);
  merge+=merge_sort(N-pivot,c);
  b[pivot]=c[N-pivot-1]+1;
  c[N-pivot]=b[pivot-1];
  while(left<pivot || right<N-pivot)
    if(b[left]<=c[right]){
      a[left+right]=b[left];
      left++;
    } else {
      a[left+right]=c[right];
      right++;
      merge+=pivot-left;
    }
  return merge;
}

