long long int merge_sort(int N, int a[]){
  int pivot=N/2;
  long long int merge=0;
  int left=0,right=0;
  int b[100001];
  if(N==1) return 0;
  for(int i=0;i<N;i++) b[i]=a[i];
  merge+=merge_sort(pivot,b);
  merge+=merge_sort(N-pivot,b+pivot);
  b[N+1]=b[pivot-1];
  while(left<pivot && right<N-pivot)
    if(b[left]<=b[right+pivot]){
      a[left+right]=b[left];
      left++;
    } else {
      a[left+right]=b[pivot+right];
      right++;
      merge+=pivot-left;
    }
  while(left<pivot){
      a[left+right]=b[left];
      left++;
  }
  while(right<N-pivot) {
      a[left+right]=b[pivot+right];
      right++;
      merge+=pivot-left;
    }
  return merge;
}

