#include <stdio.h>

int merge_sort(int N, int a[]){
  int pivot=N/2;
  int merge=0;
  int progress=0;
  int b[100000];
  if(N==1) return 0;
  for(int i=0;i<N;i++) b[i]=a[i];
  merge+=merge_sort(pivot,b);
  merge+=merge_sort(N-pivot,b+pivot);
  for(int i=0;i<N-pivot;i++){
    while(progress<pivot && b[progress]<=b[pivot+i]){
      a[i+progress]=b[progress];
      progress++;
    }
    merge+=pivot-progress;
    a[i+progress]=b[pivot+i];
  }
  while(progress<pivot){
    a[N-pivot+progress]=b[progress];
    progress++;
  }
  return merge;
}

int main(){
  // input
  int N;
  int a[100000];
  // binary_search
  int left=1,right=1000000000,pivot;
  // element_number
  int b[100000];
  int S[100001];
  int inverse;

  // input
  scanf("%d",&N);
  for(int i=0;i<N;i++)
    scanf("%d",&a[i]);

  // binary_search
   while(right-left){
    pivot=(left+right+1)/2;
    // element_number
    for(int i=0;i<N;i++) b[i]=(a[i]>=pivot)*2-1;
    S[0]=0; for(int i=0;i<N;i++) S[i+1]=S[i]+b[i];
    //  for(int i=0;i<=N;i++) printf(" %d",S[i]); printf("\n");
    inverse = N*(N+1)/2-merge_sort(N+1,S);
    //    printf("[%10d %10d] pivot %10d inverse %10d\n",left,right,pivot,inverse);
    if(inverse >= (N*(N+1)/2+1)/2)
      left =pivot;
    else
      right=pivot-1;
  }

  printf("%d\n",left);

  return 0;
}

