{
	if (left == right)return;
	int mid = (left + right) / 2;
	mergesort(left, mid);
	mergesort(mid + 1, right);
	int p = left, r = left, q = mid + 1;
	while (p <= mid && q <= right)
	{
		if (sum[p] < sum[q])
			temp[r++] = sum[p++];
