void msort_inner(const int size, char (*a)[size], char (*b)[size], const int count, int (*comp)(const void*, const void*)){
	if(count<=1) return;
	const int lr=count/2, rr=count;
	int ll=0, rl=count/2;
	int k=0;
	msort_inner(size, a+ll, b+ll, lr-ll, comp);
	msort_inner(size, a+rl, b+rl, rr-rl, comp);
	while(ll<lr && rl<rr){
		if(comp(a[ll], a[rl])<=0){
			memcpy(b[k], a[ll], size);
			k++; ll++;
		}else{
			memcpy(b[k], a[rl], size);
			k++; rl++;
		}
	}
	while(ll<lr){
		memcpy(b[k], a[ll], size);
		k++; ll++;
	}
	while(rl<rr){
		memcpy(b[k], a[rl], size);
		k++; rl++;
	}
	memcpy(a, b, size*count);
}

void msort(void *base, const int count, const int size, int (*comp)(const void*, const void*)){
	char (*a)[size] = (char(*)[size])base;
	char (*b)[size] = (char(*)[size])malloc(count*size);
	msort_inner(size, a, b, count, comp);
	free(b);
}

int comp(const void *a, const void *b){return (*(int*)a>*(int*)b)-(*(int*)a<*(int*)b);}

