//昇順
int asc(const void* a, const void* b){
    return *(int*)a-*(int*)b;
}

int main(void){
    int N;
    scanf("%d",&N);

    //A[0]~A[N-1]に格納する
    int* A;
    NEW(A,N);
    for(int i=0;i<N;i++){
        scanf("%d",&A[i]);
    }
    qsort(A,N,sizeof(int),asc);

    //数列mの中央値は、左からmiddle番目
    int middle=N*(N+1)/4+1;
    int cnt=0;
    int ans;
    for(int i=0;i<N;i++){
        cnt+=MIN(i+1,N-i);
        if(cnt>=middle){
            ans=A[i];
            break;
        }
    }
    printf("%d\n",ans);

    return 0;
}

