static int tmpCalcMedians[MAX_DATAS];  /* 中央値計算用 */
static int medians[MAX_DATAS];  /* 中央値 */
static int N = 0;
static int count = 0;

int compare_int(const void *a, const void *b)
{
    return *(int*)a - *(int*)b;
}

void calcMedian(int startNum, int endNum)
{
    int j = 0;
    for (int i = startNum; i <= endNum; i++) {
        tmpCalcMedians[j++] = data[i];
        //printf("%d\n", tmpCalcMedians[j - 1]);
    }
    int num = endNum - startNum + 1;
    qsort(tmpCalcMedians, num, sizeof(int), compare_int);
    medians[count++] = tmpCalcMedians[num / 2];

    //printf("start:%d, end:%d, median%d\n", startNum, endNum, medians[count-1]);
}

void getInput(char *pstr)
{
    fgets(pstr, sizeof(str), stdin);
}

int main() {
    char *pstr = &str[0];
    /* Nを読み込む */
    getInput(pstr);
    N = atoi(pstr);
    //printf("%d\n", N);

    /* 数列を読み出す */
    getInput(pstr);
    data[0] = atoi(strtok(pstr, " "));
    for (int i = 1; i < N; i++) {
        data[i] = atoi(strtok(NULL, " "));
    }

    /* 中央値の配列を作る */
    for (int i = N - 1; i >= 0; i--) {
        for (int j = 0; j <= i; j++) {
            calcMedian(j, i);
            //printf("%d,%d\n", j, i);
        }
    }

    /* 結果を出力 */
    qsort(medians, count, sizeof(int), compare_int);
    printf("%d\n", medians[count / 2]);

    return 0;
}

