#include <stdio.h>

typedef struct {
	int key, id;
} data;

void merge_sort(data x[], int n)
{
	static data y[100001] = {};
	if (n <= 1) return;
	merge_sort(&(x[0]), n/2);
	merge_sort(&(x[n/2]), (n+1)/2);

	int i, p, q;
	for (i = 0, p = 0, q = n/2; i < n; i++) {
		if (p >= n/2) y[i] = x[q++];
		else if (q >= n) y[i] = x[p++];
		else y[i] = (x[p].key < x[q].key)? x[p++]: x[q++];
	}
	for (i = 0; i < n; i++) x[i] = y[i];
}

void add_BIT(int N, int BIT[], int i, int k)
{
	while (i <= N) {
		BIT[i] += k;
		i += (i & -i);
	}
}

int sum_BIT(int BIT[], int r)
{
	int sum = 0;
	while (r > 0) {
		sum += BIT[r];
		r -= (r & -r);
	}
	return sum;
}

int main()
{
	int i, N, a[100001];
	data d[100001];
	scanf("%d", &N);
	for (i = 1; i <= N; i++) {
		scanf("%d", &(a[i]));
		d[i-1].key = a[i];
		d[i-1].id = i;
	}
	merge_sort(d, N);

	int l = 0, r = N - 1, m, zero, BIT[200001];
	long long n = ((long long)N * (N + 1) + 2) / 4, sum;
	while (l < r) {
		m = (l + r + 1) / 2;
		for (i = 0, zero = N, sum = 0; i <= N * 2; i++) BIT[i] = 0;
		for (i = 1; i <= N; i++) {
			if (a[i] >= d[m].key) add_BIT(N * 2 + 1, BIT, zero++, 1);
			else add_BIT(N * 2 + 1, BIT, zero--, 1);
			sum += sum_BIT(BIT, zero);
		}
		if (sum >= n) l = m;
		else r = m - 1;
	}
	printf("%d\n", d[l].key);
	fflush(stdout);
	return 0;
}

