fun sortAndGetMid(list: MutableList<Int>): Int {
    for (i in 0 until list.size - 1) {
        var j = i

        for (k in i + 1 until list.size) {
            if (list[k] < list[j]) {
                j = k
            }
        }

        if (i < j) {
            val tmp = list[j]
            list[j] = list[i]
            list[i] = tmp
        }
    }

    return list[list.size / 2]
}

fun getMid(list: MutableList<Int>): Int = sortAndGetMid(if (list.size < 6) {
    list
} else {
    val m = mutableListOf<Int>()

    for (i in 0 until list.size / 5) {
        m.add(getMid(list.subList(5 * i, 5 * (i + 1))))
    }

    m
})

