fun f(m: Int, n: Int, a: List<Int>): Boolean {
  var s = IntArray(n + 1) { 0 }
  for (i in 0 until n) {
    s[i + 1] = s[i] + if (a[i] >= m) 1 else -1
  }
  val mn = s.min()!!
  s = s.map { it - mn + 1 }.toIntArray()

