        var ng = a.min()!! - 1
        var ok = a.max()!!
        val all = n.toLong() * (n + 1) / 2
        while (ok - ng > 1) {
            val med = (ok + ng) / 2
            var sum = 0
            val bit = FenwickTree(2 * n + 1)
            bit.add(n, 1)
            var cnt = 0L
            for (i in 0 until n) {
                sum += if (a[i] <= med) 1 else -1
                cnt += bit.sum(sum + n)
                bit.add(sum + n, 1)
            }

            if (cnt > all - cnt) {
                ok = med
            } else {
                ng = med
            }
        }

        println(ok)
    }
}

class FenwickTree(private val size: Int) {
    private val tree = Array(size + 1) { 0 }

    // a[i]にnを加算
    fun add(i: Int, n: Int) {
        var t = i + 1
        while (t <= size) {
            tree[t] += n
            t += (t and (-t))
        }
    }

    // [0,i)の合計を求める
    fun sum(i: Int): Int {
        var result = 0
        var t = i
        while (t > 0) {
            result += tree[t]
            t -= (t and (-t))
        }
        return result
    }
}

