class Program {
    fun solve() {
        val sc = FastScanner()
        val n = sc.nextInt()
        val a = (1..n).map { sc.nextInt() }

        // 中央値
        /*
            i以下の要素が floor(M/2)+1個以上で最小
            中央値以下 - 中央値強 > 0
         */

        val all = (n + 1).toLong() * n / 2
        //中央値以上か?
        var ng = a.min()!! - 1
        var ok = a.max()!!
        while (ok - ng > 1) {
            val med = (ok + ng) / 2
            // med以下を 1 中央値強を -1
            val st = SegmentTree({ l, r -> l + r }, 0)
            var sum = 0
            st[100000] = 1
            var cnt = 0L
            for (i in 0 until n) {
                // med以下を1, medより大きければ-1
                sum += if (a[i] <= med) 1 else -1
                cnt += st.query(0, sum + 100000).toLong()
                st[sum + 100000] += 1
            }

            // med以下が中央値になる cnt
            if (cnt > all - cnt) {
                ok = med
            } else {
                ng = med
            }
        }

        println(ok)
    }
}

class SegmentTree<T>(private val op: (T, T) -> T, private val id: T) {
    companion object {
        const val size = 1 shl 15
    }

    @Suppress("UNCHECKED_CAST")
    private val array = Array<Any?>(size * 2) { id } as Array<T>

    operator fun get(i: Int) = array[i + size]
    operator fun set(i: Int, n: T) = update(i, n)

    fun update(i: Int, n: T) {
        var index = i + size
        array[index] = n
        while (index > 1) {
            index /= 2
            array[index] = op(array[index * 2], array[index * 2 + 1])
        }
    }

    private fun query(left: Int, right: Int, k: Int, l: Int, r: Int): T {
        if (left <= l && r <= right) {
            return array[k]
        }

        if (r <= left || right <= l) {
            return id
        }

        return op(query(left, right, k * 2, l, (l + r) / 2), query(left, right, k * 2 + 1, (l + r) / 2, r))
    }

    fun query(left: Int, right: Int) = query(left, right, 1, 0, size)
}

