public final class Main {

    private static class SegTree {
        int leftMost, rightMost;
        SegTree left, right;
        long sum;

        SegTree(int leftMost, int rightMost) {
            this.leftMost = leftMost;
            this.rightMost = rightMost;
            if (leftMost != rightMost) {
                final int mid = leftMost + rightMost >>> 1;
                left = new SegTree(leftMost, mid);
                right = new SegTree(mid + 1, rightMost);
            }
        }

        private void recalc() {
            if (leftMost == rightMost) {
                return;
            }
            sum = left.sum + right.sum;
        }

        private long query(int l, int r) {
            if (r < leftMost || l > rightMost) {
                return 0;
            }
            if (l <= leftMost && rightMost <= r) {
                return sum;
            }
            return left.query(l, r) + right.query(l, r);
        }

        private void update(int idx, int val) {
            if (leftMost == rightMost) {
                sum = val;
            } else {
                final int mid = leftMost + rightMost >>> 1;
                if (idx <= mid) {
                    left.update(idx, val);
                } else {
                    right.update(idx, val);
                }
                recalc();
            }
        }
    }

    public static void main(String[] args) {
        final FastScanner fs = new FastScanner();
        final int n = fs.nextInt();
        final int[] arr = new int[n];
        if (n == 1) {
            System.out.println(arr[0]);
            return;
        }
        long target = 0;
        for (int i = 0; i < n; i++) {
            target += i;
            arr[i] = fs.nextInt();
        }
        target = target / 2 + 1;

        int lo = 0;
        int hi = (int) (1e9 + 5);
        while (lo < hi) {
            final int mid = (1 + lo + hi) >>> 1;
            long check = check(arr, mid);
//            System.out.println(check + " " + mid + " " + target);
            if (check >= target) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        System.out.println(lo);
    }

    private static long check(int[] arr, int mid) {
        final int n = arr.length;
        final int[] s = new int[n];
        for (int i = 0; i < n; i++) {
            s[i] = (i > 0 ? s[i - 1] : 0) + (arr[i] < mid ? -1 : 1);
        }
//        System.out.println(Arrays.toString(s));
        final int[] freq = new int[2 * n + 1];
        final SegTree st = new SegTree(0, 2 * n);
        long score = 0;
        for (int i = 0; i < n; i++) {
//            System.out.print(st.query(0, s[i] + n) + " ");
            score += st.query(0, s[i] + n);
            st.update(s[i] + n, ++freq[s[i] + n]);
        }
//        System.out.println();

        return score;
    }

    static final class Util {
        public static void shuffleSort(int[] x) {
            shuffle(x);
            Arrays.sort(x);
        }

        public static void shuffleSort(long[] x) {
            shuffle(x);
            Arrays.sort(x);
        }

        public static void shuffle(int[] x) {
            final Random r = new Random();

            for (int i = 0; i <= x.length - 2; i++) {
                final int j = i + r.nextInt(x.length - i);
                swap(x, i, j);
            }
        }

        public static void shuffle(long[] x) {
            final Random r = new Random();

            for (int i = 0; i <= x.length - 2; i++) {
                final int j = i + r.nextInt(x.length - i);
                swap(x, i, j);
            }
        }

        public static void swap(int[] x, int i, int j) {
            final int t = x[i];
            x[i] = x[j];
            x[j] = t;
        }

        public static void swap(long[] x, int i, int j) {
            final long t = x[i];
            x[i] = x[j];
            x[j] = t;
        }

        private Util() {}
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        private String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    //noinspection CallToPrintStackTrace
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int[] nextIntArray(int n) {
            final int[] a = new int[n];
            for (int i = 0; i < n; i++) { a[i] = nextInt(); }
            return a;
        }

        long[] nextLongArray(int n) {
            final long[] a = new long[n];
            for (int i = 0; i < n; i++) { a[i] = nextLong(); }
            return a;
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    int N = scanner.nextInt();
    int[] a = new int[N];
    for (int i = 0; i < N; i++) {
      a[i] = scanner.nextInt();
    }
    int[] sorted = Arrays.copyOf(a, a.length);
    Arrays.sort(sorted);

    int target = (int) (((long) N * (N + 1) / 2 + 1) / 2);
    int left = -1, right = N;
    while (right - left > 1) {
      int mid = (left + right) / 2;
      int count = numSubarraysWhooseMedianBiggerThan(a, sorted[mid]);
      if (target <= count) {
        left = mid;
      } else {
        right = mid;
      }
    }
    System.out.println(sorted[left]);
  }

  private static int numSubarraysWhooseMedianBiggerThan(int[] a, int t) {
    int[] b = new int[a.length + 1];
    b[0] = 0;
    int sum = 0;
    for (int i = 0; i < a.length; i++) {
      sum += a[i] >= t ? 1 : -1;
      b[i + 1] = sum;
    }
    int n = a.length;
    return (int) ((long) n * (n + 1) / 2 - countInversion(b, 0, b.length));
  }

  private static int countInversion(int[] a, int left, int right) {
    if (left + 1 >= right) return 0;
    int mid = (left + right) / 2;
    int count = countInversion(a, left, mid) + countInversion(a, mid, right);
    int[] b = new int[right - left];
    int i = 0;
    int li = left;
    int ri = mid;
    while (li < mid && ri < right) {
      if (a[li] <= a[ri]) {
        b[i++] = a[li++];
      } else {
        b[i++] = a[ri++];
        count += mid - li;
      }
    }
    while (li < mid) b[i++] = a[li++];
    while (ri < right) b[i++] = a[ri++];
    System.arraycopy(b, 0, a, left, b.length);
    return count;
  }
}

