public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DMedianOfMedians solver = new DMedianOfMedians();
        solver.solve(1, in, out);
        out.close();
    }

    static class DMedianOfMedians {
        Random random = new Random(543534151132L + System.currentTimeMillis());
        private int[] ft;
        private int n;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            int a[] = new int[n];
            for (int i = 0; i < n; ++i) a[i] = in.nextInt();
            int[] sorted = a.clone();
            mySort(sorted);

            int l = 0;
            int r = n;
            int cmp[] = new int[n];
            int presum[] = new int[n];
            ft = new int[n + 1];
            while (r - l > 1) {
                int mid = (l + r) / 2, cur = sorted[mid];
                for (int i = 0; i < n; ++i) {
                    if (a[i] >= cur) cmp[i] = 1;
                    else cmp[i] = -1;
                }
                presum[0] = cmp[0];
                int offset = cmp[0];
                for (int i = 1; i < n; ++i) {
                    presum[i] = presum[i - 1] + cmp[i];
                    offset = Math.min(offset, presum[i]);
                }
                offset = 1 - offset;

                for (int i = 0; i <= n; ++i) ft[i] = 0;
                long cnt = 0;
                for (int i = 0; i < n; ++i) {
                    cur = presum[i] + offset;
                    cnt += sum(cur);
                    if (presum[i] >= 0) ++cnt;
                    update(cur, 1);
                }

                if (cnt >= ((long) (1 + n) * n / 2 + 1) / 2) l = mid;
                else r = mid;
            }
            out.println(sorted[l]);
        }

        private int lowbit(int x) {
            return x & (-x);
