    public long calc(int[] sign, int n, int m) {
        Fenwick fen = new Fenwick(2 * n);
        fen.update(n + 1, 1);
        int sum = 0;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            sum += sign[i];
            ans += fen.get(sum + n + 1);
            fen.update(sum + n + 1, 1);
        }
        return ans;
    }

    static class Fenwick {
        private int n;
        private int[] sum;

        public Fenwick(int n) {
            this.n = n + 10;
            this.sum = new int[n + 10];
        }

        public void update(int i, int v) {
            for (; i < n; i += i & -i) {
                sum[i] += v;
            }
        }

        public int get(int i) {
            int res = 0;
            for (; i > 0; i -= i & -i) {
                res += sum[i];
            }
            return res;
        }

        public int get(int i, int j) {
            return get(j) - get(i);
        }
    }

