    public static boolean calc(long va) {
        //貪欲にギリギリセーフを選んでいく。
        int v = B[(int) va];
        int[] rui = new int[N + 1];
        for (int i = 1; i < N + 1; i++) {
            rui[i] = A[i - 1] >= v ? 1 : -1;
        }
        for (int i = 0; i < N; i++) {
            rui[i + 1] += rui[i];
        }
        BIT t = new BIT(N * 2 + 10000);
        for (int i = 0; i < N + 1; i++) {
            rui[i] += N + 1000;
        }
        long cou = 0;
        for (int i = 0; i < N + 1; i++) {
            cou += t._sum(rui[i] + 1);
            t.add(rui[i], 1);
        }
        return cou * 2 >= (N + 1) * (long) N / 2;
    }

    //条件を満たす最大値、あるいは最小値を求める
    static int mgr(long ok, long ng) {
        //int ok = 0; //解が存在する
        //int ng = N; //解が存在しない
        while (Math.abs(ok - ng) > 1) {
            long mid;
            if (ok < 0 && ng > 0 || ok > 0 && ng < 0) mid = (ok + ng) / 2;
            else mid = ok + (ng - ok) / 2;

            if (calc(mid)) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        if (calc(ok)) return B[(int) ok];
        else return -1;
    }

    static class BIT {
        long[] dat;
        int N;

        BIT(int n) {
            N = n;
            dat = new long[n + 1];
