        // 0 index
        void add(int i, int v) {
            i++;
            while (i < dat.length) {
                dat[i] += v;
                i = i + (i & -i);
            }
        }

        //開区間
        long _sum(int i) {
            if (i <= 0) return 0;
            return dat[i] + _sum(i - (i & -i));
        }

        //半開区間
        long sum(int l, int r) {
            return _sum(r) - _sum(l);
        }
