import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    int N = scanner.nextInt();
    int[] a = new int[N];
    for (int i = 0; i < N; i++) {
      a[i] = scanner.nextInt();
    }
    int[] sorted = Arrays.copyOf(a, a.length);
    Arrays.sort(sorted);
    int i = 0;
    int j = sorted.length - 1;
    while (i < j) {
      int tmp = sorted[i];
      sorted[i] = sorted[j];
      sorted[j] = tmp;
      i++;
      j--;
    }

    int target = (N * (N + 1) / 2 + 1) / 2;
    int left = -1, right = N;
    while (right - left > 1) {
      int mid = (left + right) / 2;
      int count = numSubarraysWhooseMedianBiggerThan(a, sorted[mid]);
      if (target <= count) {
        right = mid;
      } else {
        left = mid;
      }
    }
    System.out.println(sorted[right]);
  }

  private static int numSubarraysWhooseMedianBiggerThan(int[] a, int t) {
    int[] b = new int[a.length + 1];
    b[0] = 0;
    int sum = 0;
    for (int i = 0; i < a.length; i++) {
      sum += a[i] >= t ? 1 : -1;
      b[i + 1] = sum;
    }
    int n = a.length;
    int num = n * (n + 1) / 2 - countInversion(b, 0, b.length);
    return num;
  }

  private static int countInversion(int[] a, int left, int right) {
    if (left + 1 >= right) return 0;
    int mid = (left + right) / 2;
    int count = countInversion(a, left, mid) + countInversion(a, mid, right);
    int[] b = new int[right - left];
    int i = 0;
    int li = left;
    int ri = mid;
    while (li < mid && ri < right) {
      if (a[li] <= a[ri]) {
        b[i++] = a[li++];
      } else {
        b[i++] = a[ri++];
        count += mid - li;
      }
    }
    while (li < mid) b[i++] = a[li++];
    while (ri < right) b[i++] = a[ri++];
    System.arraycopy(b, 0, a, left, b.length);
    return count;
  }
}

import java.io.BufferedInputStream;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(new BufferedInputStream(System.in));
        int N = scan.nextInt();
        int[] arr = new int[N];
        for (int i=0;i<N;i++) arr[i] = scan.nextInt();
        Task tsk = new Task();
        System.out.println(tsk.solve(arr));
    }

    static class Task{
        public int solve(int[] arr){
            int n = arr.length;
            long total = n* (n-1) / 2 + n;
            int[] sorted = Arrays.copyOf(arr, n);
            Arrays.sort(sorted);
            int l = 0, r = n-1;
            while (l < r) {
                int mid = l + (r-l)/2;
                int target = sorted[mid];

                int se = 0;
                long cnt = 0;
                int[] bit = new int[2*n+2];
                for (int i=0;i<n;i++) {
                    se += arr[i] <= target? 1: -1;
                    for (int x=se+n+1;x<bit.length;x+=x&-x) bit[x]++;
                    for (int x=se+n;x>0;x-=x&-x) cnt += bit[x];
                }
                if (cnt >= total/2 + 1) r = mid;
                else l = mid+1;
            }
            return sorted[l];
        }
    }
}

