    static long mod = 1000000007;

    void solve() {
        int n = in.nextInt();
        int[] a = in.nextIntArray(n);
        int left = 0, right = 1000000001;
        while (right - left > 1) {
            int mid = (left + right) / 2;
            int[] s = new int[n + 1];
            for (int i = 0; i < n; i++) {
                s[i + 1] = s[i] + (a[i] < mid ? -1 : 1);
            }
            Bit bit = new Bit(3 * n + 1);
            long score = 0;
            for (int i = 0; i <= n; i++) {
                score += bit.getSum(0, s[i] + n + 1);
                bit.add(s[i] + n, 1);
            }
            if (score >= (n * (n + 1) / 2 + 1) / 2) {
                left = mid;
            } else {
                right = mid;
            }
        }
        out.println(left);
    }

