//BIT
class BIT {
	int n;
	long bit[];

	public BIT(int n) {
		this.n = n;
		bit = new long[n + 1];
	}

	int sum(int i) {
		int s = 0;
		while (i > 0) {
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}

	void add(int i, long x) {
		while (i <= n) {
			bit[i] += x;
			i += i & -i;
		}
	}
}

