		int sum[] = new int[n+1];
		for(int i=0;i<n;i++) sum[i+1] = sum[i] + b[i];
		int min = inf;

		//BITで扱うために、sumの要素を1-indexにする
		for(int i=0;i<n+1;i++) {
			min = min(min, sum[i]);
		}
		for(int i=0;i<n+1;i++) {
			sum[i] -= min;
			sum[i] ++; //
		}
		BIT bit = new BIT(n+1);
		long cnt = 0;
		for(int i=0;i<=n;i++) {
			cnt += bit.sum(sum[i]);
			bit.add(sum[i], 1);
		}
		return 2 * cnt >= ((long)(n+1))*n /2;
	}

