public class Program
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var xs = Console.ReadLine().Split().Select(x => int.Parse(x)).ToArray();

        var ys = new SortedSet<int>(xs).ToArray();
        var m = (n + 1) * n / 4;
        int ok = 0;
        int ng = ys.Length;
        while (Math.Abs(ok - ng) > 1)
        {
            int i = (ok + ng) / 2;
            if (Test(ys[i], xs, m))
            {
                ok = i;
            }
            else
            {
                ng = i;
            }
        }
        Console.WriteLine(ys[ok]);
    }

    static bool Test(int e, int[] xs, int m)
    {
        var s = 0;
        var ys = xs.Select(x => s += x < e ? -1 : 1).ToArray();
        var js = E.Range(0, xs.Length).ToArray();
        Array.Sort(ys, js);

        var k = 0;
        for (int i = 0; i < js.Length; i++)
        {
            if (js[i] < i)
            {
                k += i - js[i] + 1;
                if (k >= m)
                {
                    return false;
                }
            }
        }
        return true;
    }
}

