    public void Proc()
    {
        int itemCount = int.Parse(Reader.ReadLine());
        long[] list = Reader.ReadLine().Split(' ').Select(a => long.Parse(a)).ToArray();

        int totalCount = itemCount * (itemCount + 1) / 2;
        int targetIndex = totalCount / 2 + 1;

        SortedList<long, long> cnt = new SortedList<long, long>();

        for (int i = 0; i < itemCount; i++) {
            long mid = -1;
            int total = 1;
            SortedList<long, int> smaller = new SortedList<long, int>();
            SortedList<long, int> bigger = new SortedList<long, int>();
            int smallerCount = 0;
            int biggerCount = 0;
            for (int j = i; j < itemCount; j++) {
                long num = list[j];
                if(mid < 0) {
                    mid = num;
                }
                if (num < mid)
                {
                    if (smaller.ContainsKey(num))
                    {
                        smaller[num]++;
                    }
                    else
                    {
                        smaller[num] = 1;
                    }
                    smallerCount++;
                }
                else
                {
                    if(bigger.ContainsKey(num)) {
                        bigger[num]++;
                    } else {
                        bigger[num] = 1;
                    }
                    biggerCount++;
                }
                while(biggerCount - smallerCount > 1) {
                    long key = bigger.Keys.First();
                    if(smaller.ContainsKey(key)) {
                        smaller[key]++;
                    } else {
                        smaller[key] = 1;
                    }
                    bigger[key]--;
                    if(bigger[key] <= 0) {
                        bigger.Remove(key);
                    }
                    biggerCount--;
                    smallerCount++;
                }
                while(smallerCount - biggerCount > 1 ) {
                    long key = smaller.Keys.Last();
                    if(bigger.ContainsKey(key)) {
                        bigger[key]++;
                    } else {
                        bigger[key] = 1;
                    }
                    smaller[key]--;
                    if(smaller[key]<=0) {
                        smaller.Remove(key);
                    }
                    biggerCount++;
                    smallerCount--;
                }
                mid = bigger.Keys.First();
                if(cnt.ContainsKey(mid)) {
                    cnt[mid]++;
                } else {
                    cnt[mid] = 1;
                }
                total++;
            }
        }
        long tmp = 0;
        long ans = 0;
        foreach(long key in cnt.Keys) {
            if(targetIndex >= tmp && targetIndex <= tmp + cnt[key]) {
                ans = key;
                break;
            }
            tmp += cnt[key];
        }
        Console.WriteLine(ans);
    }


    private void AddNum(List<long> list, long target) {
        if(list[0] >= target) {
            list.Insert(0, target);
            return;
        } else if(list.Last() <= target) {
            list.Add(target);
            return;
        }
        int idx = getIdx(0, list.Count - 1, list, target);
        list.Insert(idx, target);
    }


    private int getIdx(int min, int max, List<long> list, long target) {
        if(max-min <= 1) {
            if(list[max] >= target) {
                return min;
            } else if(list[max] >= target ) {
                return max;
            }
            return max + 1;
        }

        int mid = (max + min) / 2;
        if(list[mid] >= target) {
            return getIdx(min, mid, list, target);
        } else {
            return getIdx(mid, max, list, target);
        }             
    }



