    bool calc(int u, int[] A)
    {
        int N = A.Length;
        var B = new int[N];
        for (int i = 0; i < N; i++)
        {
            if (A[i] >= u)
            {
                B[i] = 1;
            }
            else
            {
                B[i] = -1;
            }
        }

        var S = new int[N - 1];
        for (int i = 0; i < N - 1; i++)
        {
            if (i > 0) S[i] = S[i - 1];
            S[i] += B[i];
        }

        var num = merge_count(S);
        return num + B.Count(i => i == -1) <= (long)(N + 1) * N / 2 / 2;


