            if (calc(mid, A))
            {
                ok = mid;
            }
            else
            {
                ng = mid;
            }
        }

        WriteLine(ok);
    }

    long merge_count(int[] A)
    {
        int n = A.Length;
        if (n <= 1) return 0;

        long cnt = 0;
        var B = A.Take(n / 2).ToArray();
        var C = A.Skip(n / 2).ToArray();

        cnt += merge_count(B);
        cnt += merge_count(C);

        int ai = 0, bi = 0, ci = 0;
        while (ai < n)
        {
            if (bi < B.Length && (ci == C.Length || B[bi] <= C[ci]))
            {
                A[ai++] = B[bi++];
            }
            else
            {
                cnt += n / 2 - bi;
                A[ai++] = C[ci++];
            }
        }
        return cnt;
