class Solver
{
    public void Solve(Scanner sc)
    {
        var N = sc.Int;
        var A = sc.ArrInt;
        int r = (int)1e9, l = 0;
        while (r - l > 1)
        {
            var m = (r + l) >> 1;
            var s = N+10;var ct = 0L;
            var bit = new BIT(N * 2 + 100);
            bit.add(s, 1);
            for (var i = 0; i < N; i++)
            {
                if (A[i] >= m) s++;
                else s--;
                ct += bit[s];
                bit.add(s, 1);
            }
            if (N*(N-1)/4+1 <= ct) l = m;
            else r = m;
        }
        WriteLine(l);
    }
}

public class BIT
{
    //1-indexed
    long[] data;
    public BIT(int num)
    {
        data = new long[num + 1];
    }
    public long this[int index]
    {
        get { var s = 0L; for (var i = index; i > 0; i -= i & -i) s += data[i]; return s; }
    }
    public void add(int index, long value)
    {
        for (var i = index; i < data.Length; i += i & -i) data[i] += value;
    }
}

