using System;
using System.Collections.Generic;
using System.Text;

namespace AtTest.ABC_107
{
    class D
    {
        static void Main(string[] args)
        {
            Method(args);
            Console.ReadLine();
        }

        static void Method(string[] args)
        {
            long n = ReadLong();
            int[] array = ReadInts();
            int[] sorted = new int[n];
            for (int i = 0; i < n; i++) sorted[i] = array[i];
            Array.Sort(sorted);
            Dictionary<int, int> pos = new Dictionary<int, int>();
            for(int i = 0; i < n; i++)
            {
                if (pos.ContainsKey(sorted[i])) continue;

                pos.Add(sorted[i], i);
            }

            int bottom = 0;
            int top = (int)n;
            while (bottom + 1 < top)
            {
                int mid = (bottom + top) / 2;
                int val = sorted[mid];
                int[] sums = new int[n];
                long cnt = 0;
                for (int i = 0; i < n; i++)
                {
                    if (val <= array[i])
                    {
                        sums[i] = 1;
                        cnt++;
                    }
                    else sums[i] = -1;

                    if (i > 0) sums[i] += sums[i - 1];
                }

                SegTree<int> tree = new SegTree<int>(2*100000+5, 0, (a, b) => a + b, 0);
                for(int i = (int)n - 1; i >= 0; i--)
                {
                    tree.Update(sums[i] + 100000, tree.Look(sums[i] + 100000) + 1);
                    if (val <= array[i])
                    {
                        cnt += tree.Scan(sums[i] - 1 + 100000, 2 * 100000 + 10);
                    }
                    else
                    {
                        cnt += tree.Scan(sums[i] + 1 + 100000, 2 * 100000 + 10);
                    }
                }

                long thres = n * (n + 1) / 4;
                if ((n * (n + 1) / 2) % 2 > 0) thres++;
                if (cnt >= thres) bottom = mid;
                else top = mid;
            }

            Console.WriteLine(sorted[bottom]);
        }

        class SegTree<T>
        {
            int totalLength;
            T[] tree;
            Func<T, T, T> integrate;
            T exValue;

            public SegTree(int length, Func<T, T, T> integrate, T exValue)
            {
                this.integrate = integrate;
                this.exValue = exValue;
                totalLength = 1;
                while (totalLength < length) totalLength *= 2;

                tree = new T[2 * totalLength - 1];
                for (int i = 0; i < tree.Length; i++) tree[i] = exValue;
            }

            public SegTree(int length, T initialValue,
                Func<T, T, T> integrate, T exValue)
                : this(length, integrate, exValue)
            {
                for (int i = 0; i < length; i++)
                {
                    tree[i + totalLength - 1] = initialValue;
                }
                UpdateAll();
            }

            public void AssignWithoutUpdate(int i, T value)
            {
                tree[i + totalLength - 1] = value;
            }

            public void Update(int i, T value)
            {
                int now = i + totalLength - 1;
                tree[now] = value;
                while (now > 0)
                {
                    now = (now - 1) / 2;
                    tree[now] = integrate(
                        tree[now * 2 + 1], tree[now * 2 + 2]);
                }
            }

            public void UpdateAll()
            {
                for (int i = totalLength - 2; i >= 0; i--)
                {
                    tree[i] = integrate(tree[i * 2 + 1], tree[i * 2 + 2]);
                }
            }

            public T Look(int i) { return tree[i + totalLength - 1]; }

            //[top,last)
            public T Scan(int top, int last)
            {
                return Query(top, last, 0, 0, totalLength);
            }

            T Query(int top, int last, int i, int left, int right)
            {
                if (right <= top || last <= left) return exValue;
                if (top <= left && right <= last) return tree[i];

                T leftValue = Query(top, last, i * 2 + 1,
                    left, (left + right) / 2);
                T rightValue = Query(top, last, (i + 1) * 2,
                    (left + right) / 2, right);

                return integrate(leftValue, rightValue);
            }
        }

        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }
    }
}

using System;
using System.Text;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using static System.Console;
using static System.Math;

namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            new Program().Solve(new ConsoleInput(Console.In, ' '));
#if DEBUG
            ReadLine();
#endif
        }

        void Solve(ConsoleInput cin)
        {
            int n = cin.ReadInt;
            long[] a_n = cin.ReadLongArray(n);

            Sorted parent = new Sorted();

            for (int l = 0; l < n; l++)
            {
                Sorted child = new Sorted();
                int count = 0;
                for (int r = l; r < n; r++)
                {
                    child.insert(a_n[r]);
                    count++;
                    long mid = child.sortedList[count / 2];
                    parent.insert(mid);
                }
            }

            Console.WriteLine(parent.sortedList[parent.sortedList.Count / 2]);
        }

        class Sorted
        {
            public List<long> sortedList { get; private set; }

            public Sorted()
            {
                this.sortedList = new List<long>();
            }

            public void insert(long val)
            {
                int index = BinarySearch(this.sortedList, val);
                this.sortedList.Insert(index + 1, val);
            }

            private static int BinarySearch(List<long> list, long val)
            {
                int bottom = 0;
                int top = list.Count;

                if (top == 0)
                {
                    return -1;
                }

                while (bottom + 1 < top)
                {
                    int mid = (bottom + top) / 2;
                    if (list[mid] <= val)
                    {
                        bottom = mid;
                    }
                    else
                    {
                        top = mid;
                    }
                }
                if (bottom == 0 && val < list[bottom]) return -1;
                else return bottom;
            }
        }

        class ConsoleInput
        {
            private readonly System.IO.TextReader _stream;
            private char _separator = ' ';
            private Queue<string> inputStream;

            public ConsoleInput(System.IO.TextReader stream, char separator = ' ')
            {
                this._separator = separator;
                this._stream = stream;
                inputStream = new Queue<string>();
            }

            public string Read
            {
                get
                {
                    if (inputStream.Count != 0) return inputStream.Dequeue();
                    string[] tmp = _stream.ReadLine().Split(_separator);
                    for (int i = 0; i < tmp.Length; ++i)
                        inputStream.Enqueue(tmp[i]);
                    return inputStream.Dequeue();
                }
            }

            public string ReadLine { get { return _stream.ReadLine(); } }
            public int ReadInt { get { return int.Parse(Read); } }
            public long ReadLong { get { return long.Parse(Read); } }
            public double ReadDouble { get { return double.Parse(Read); } }
            public string[] ReadStrArray(long N) { var ret = new string[N]; for (long i = 0; i < N; ++i) ret[i] = Read; return ret; }
            public int[] ReadIntArray(long N) { var ret = new int[N]; for (long i = 0; i < N; ++i) ret[i] = ReadInt; return ret; }
            public long[] ReadLongArray(long N) { var ret = new long[N]; for (long i = 0; i < N; ++i) ret[i] = ReadLong; return ret; }
        }
    }
}

