internal partial class Solver {
    public void Run() {
        var n = ni();
        var a = ni(n);

        int ans = -1;
        var pattern = 1L * n * (n + 1) / 2;
        int lower = 0, upper = a.Max() + 10;
        while (lower <= upper) {
            var mid = (lower + upper) / 2;
            if (Count(a, n, mid) >= (pattern + 1) / 2) {
                ans = mid;
                lower = mid + 1;
            } else {
                upper = mid - 1;
            }
        }
        cout.WriteLine(ans);
    }

    private long Count(int[] a, int n, int mid) {
        // median が mid 以上の区間の数
        var s = new int[n + 1];
        for (int i = 0; i < n; i++) {
            s[i + 1] = mid <= a[i] ? +1 : -1;
        }
        for (int i = 0; i < n; i++) {
            s[i + 1] += s[i];
        }
        long res = 0;
        int offset = n + 2;
        var bit = new BinaryIndexTree(2 * offset + 2);
        foreach (var x in s) {
            var p = x + offset;
            res += bit.Sum(0, p + 1);
            bit.Add(p, 1);
        }
        return res;
    }
}

public class BinaryIndexTree {
    private readonly long[] array;
    public BinaryIndexTree(int size) {
        array = new long[size];
    }
    public long Sum(int begin, int end) {
        if (begin != 0) {
            return Sum(0, end) - Sum(0, begin);
        }

        long val = 0;
        end--;
        for (; end >= 0; end = (end & (end + 1)) - 1) {
            val += array[end];
        }

        return val;
    }

    public void Add(int k, long val) {
        for (; k < array.Length; k |= k + 1) {
            array[k] += val;
        }
    }

    /// <summary>return min pos where sum(A[0] .. A[pos]) >= w</summary>
    public int LowerBound(long w) {
        if (w <= 0) {
            return 0;
        }

        int x = 0, k = 1, N = array.Length;
        while ((k << 1) <= N) {
            k <<= 1;
        }

        for (; k > 0; k >>= 1) {
            if (x + k - 1 < N && array[x + k - 1] < w) {
                w -= array[x + k - 1];
                x += k;
            }
        }
        return (x == N) ? -1 : x;
    }
}

