                long min = A.Min();
                long max = A.Max() + 1;
                long hurdle = (N * (N + 1) / 2 + 1) / 2;
                while (min + 1 < max)
                {
                    var mid = (min + max) / 2;
                    var count = D_Median(A, mid);
                    if (count < hurdle)
                    {
