public class Program
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var xs = Console.ReadLine().Split().Select(x => int.Parse(x)).ToArray();

        var ys = new SortedSet<int>(xs).ToArray();
        var m = (n + 1) * n / 2;
        int ok = 0;
        int ng = ys.Length;
        while (Math.Abs(ok - ng) > 1)
        {
            int i = (ok + ng) / 2;
            if (Test(ys[i], xs, m))
            {
                ok = i;
            }
            else
            {
                ng = i;
            }
        }
        Console.WriteLine(ys[ok]);
    }

    static bool Test(int e, int[] xs, int m)
    {
        var s = 0;
        var ys = xs.Select(x => s += x < e ? -1 : 1).ToArray();

        var a = m / 2;
        var b = m - a;
        var ok = 0;
        var ng = 0;
        for (int l = 0; l < ys.Length; l++)
        {
            for (int r = l; r < ys.Length; r++)
            {
                if (ys[l] > ys[r])
                {
                    if (++ng >= a)
                    {
                        return false;
                    }
                }
                else
                {
                    if (++ok >= b)
                    {
                        return true;
                    }
                }
            }
        }

        throw new Exception("Unexpected to reach.");
    }
}

