namespace AtCoder.ABC107.D
{
    class Program
    {
        static void Main(string[] args)
        {
            // 入力値の検証は割愛
            var N = int.Parse(Console.ReadLine());
            var list = Console.ReadLine().Split(" ").Select(long.Parse).ToList();

            var calculator = new Calculator();

            var answer = calculator.GetMedianOfMedians(list);

            Console.WriteLine(answer);
        }
    }

    public class Calculator
    {
        public long GetMedian(IEnumerable<long> list)
        {
            // 中央
            var index = (int)Math.Floor((decimal)list.Count() / 2);

            // 中央値
            return list.OrderBy(i => i).ToList()[index];
        }

        public long GetMedianOfMedians(IList<long> list)
        {
            // 部分列のコレクションを取得
            var subLists = GetSubLists(list);

            // 各部分列の中央値を取得
            var medians = subLists.Select(GetMedian);

            // その中央値を返す
            return GetMedian(medians);
        }

        public List<List<long>> GetSubLists(IEnumerable<long> list)
        {
            var subLists = new List<List<long>>();
            for (var i = 0; i < list.Count(); i++)
            {
                for (var j = i; j < list.Count(); j++)
                {
                    subLists.Add(list.Skip(i).Take(j - i + 1).ToList());
                }
            }
            return subLists;
        }
    }
}

