public class Program
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var xs = Console.ReadLine().Split().Select(x => int.Parse(x)).ToArray();

        var ys = new SortedSet<int>(xs).ToArray();
        var m = (n + 1) * n / 4;
        int ok = 0;
        int ng = ys.Length;
        while (Math.Abs(ok - ng) > 1)
        {
            int i = (ok + ng) / 2;
            if (Test(ys[i], xs, m))
            {
                ok = i;
            }
            else
            {
                ng = i;
            }
        }
        Console.WriteLine(ys[ok]);
    }

    static bool Test(int e, int[] xs, int m)
    {
        var ys = new int[xs.Length];
        ys[0] = xs[0] < e ? -1 : 1;
        var t = ys[0];
        for (int i = 1; i < ys.Length; i++)
        {
            ys[i] = ys[i - 1] + (xs[i] < e ? -1 : 1);
            if (ys[i] < t)
            {
                t = ys[i];
            }
        }

        var bit = new BinaryIndexedTree<int>(ys.Length, (x, y) => x + y);
        var k = 0;
        for (int i = 0; i < ys.Length; i++)
        {
            var x = ys[i] - t;
            bit.AddTo(x, 1);
            k += bit.GetSum(x);
            if (k > m)
            {
                return true;
            }
        }
        return false;
    }
}

class BinaryIndexedTree<T>
{
    T[] _array;
    Func<T, T, T> _op;

    public BinaryIndexedTree(int n, Func<T, T, T> op)
    {
        if (op == null)
        {
            throw new ArgumentNullException();
        }

        this._array = new T[n + 1];
        this._op = op;
    }

    public BinaryIndexedTree(T[] xs, Func<T, T, T> op)
    : this(xs.Length, op)
    {
        for (int i = 0; i < xs.Length; i++)
        {
            this.AddTo(i, xs[i]);
        }
    }

    public T GetSum(int i)
    {
        var x = default(T);
        i++;
        while (i > 0)
        {
            x = _op(x, _array[i]);
            i -= i & -i;
        }
        return x;
    }

    public void AddTo(int i, T x)
    {
        i++;
        while (i < _array.Length)
        {
            _array[i] = _op(_array[i], x);
            i += i & -i;
        }
    }

    public override string ToString() => string.Join(", ", _array);
}

