        int r = (int)1e9, l = 0;
        while (r - l > 1)
        {
            var m = (r + l) >> 1;
            var s = N+10;var ct = 0L;
            var bit = new BIT(N * 2 + 100);
            bit.add(s, 1);
            for (var i = 0; i < N; i++)
            {
                if (A[i] >= m) s++;
                else s--;
                ct += bit[s];
                bit.add(s, 1);
            }
            if ((N*(N+1)/2+1)/2 <= ct) l = m;
            else r = m;
        }
        WriteLine(l);
