    public class Calculator
    {
        public long GetMedian(IEnumerable<long> list)
        {
            // 中央
            var index = (int)Math.Floor((decimal)list.Count() / 2);

            // 中央値
            return list.OrderBy(i => i).ElementAt(index);
        }

        public long GetMedianOfMedians(IList<long> list)
        {
            // 各部分列の中央値を取得
            var medians = new List<long>();
            for (var i = 0; i < list.Count(); i++)
            {
                for (var j = i; j < list.Count(); j++)
                {
                    var subList = list.Skip(i).Take(j - i + 1);
                    medians.Add(GetMedian(subList));
                }
            }

            // その中央値を返す
            return GetMedian(medians);
        }
    }
}

