class D
{
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var a = Console.ReadLine().Split().Select(int.Parse).ToArray();

		Console.WriteLine(Last(1, a.Max(), m =>
		{
			var b = a.Select(x => x < m ? -1 : 1).ToArray();
			var s = CumSum(b);
			// 転倒数 (簡易実装)
			return Enumerable.Range(1, n).Sum(i => Enumerable.Range(0, i).Count(j => s[j] > s[i])) <= n * (n + 1) / 4;
		}));
	}

	static int Last(int l, int r, Func<int, bool> f)
	{
		int m;
		while (l < r) if (f(m = r - (r - l - 1) / 2)) l = m; else r = m - 1;
		return l;
	}

	static int[] CumSum(int[] a)
	{
		var s = new int[a.Length + 1];
		for (int i = 0; i < a.Length; i++) s[i + 1] = s[i] + a[i];
		return s;
	}
}

