using System;
using System.Linq;
using System.Collections.Generic;

using E = System.Linq.Enumerable;

public class Program
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var xs = Console.ReadLine().Split().Select(x => int.Parse(x)).ToArray();

        var ys = new int[xs.Length];
        Array.Copy(xs, ys, xs.Length);
        Array.Sort(ys);
        var m = (n * n - (n - 1) * n / 2 + 1) / 2;
        int ok = 0;
        int ng = ys.Length;
        while (ok < ng - 1)
        {
            int i = ok + (ng - ok) / 2;
            if (Test(ys[i], xs) < m)
            {
                ng = i;
            }
            else
            {
                ok = i;
            }
        }
        Console.WriteLine(ys[ok]);
    }

    static Dictionary<int, int> memo = new Dictionary<int, int>();
    static int Test(int e, int[] xs)
    {
        int k;
        if (memo.TryGetValue(e, out k))
        {
            return k;
        }

        var s = 0;
        var ys = xs.Select(x => s += x < e ? -1 : 1).ToArray();

        k = 0;
        for (int l = 0; l < ys.Length; l++)
        {
            for (int r = l; r < ys.Length; r++)
            {
                if (ys[l] <= ys[r])
                {
                    k++;
                }
            }
        }
        memo[e] = k;
        return k;
    }
}

