        class Util
        {
            public static long CountInversion_Naive(int[] array)
            {
                var min = array.Min();
                var max = array.Max();
                var bit = new BIT(max - min + 1);
                long count = 0;
                for (int i = 0; i < array.Length; ++i)
                {
                    var v = array[i] - min + 1;
                    bit.Add(v, 1);
                    count += i + 1 - bit.Sum(v);
                }
                return count;
            }
            public class BIT
            {
                int N; long[] array;
                public BIT(int m) { for (int n = 1; ; n *= 2) { if (n >= m) { N = n; array = new long[N + 1]; break; } } }
                public void Add(int idx, int v) { for (int x = idx; x <= N; x += x & -x) { array[x] += v; } }
                public long Sum(int idx) { long ret = 0; for (int x = idx; x > 0; x -= x & -x) { ret += array[x]; } return ret; }
            }
