    {
        int N = A.Length;
        var B = new int[N];
        var S = new int[N];
        int cnt = 0;
        int r = 0;
        for (int i = 0; i < N; i++)
        {
            if (A[i] >= u)
            {
                B[i] = 1;
                r++;
            }
            else
            {
                B[i] = -1;
                r--;
                cnt++;
            }
            S[i] = r;
        }

        return merge_count(S) + cnt <= sum;
    }
    void solve()
    {
        int N = cin.nextint;
        var A = cin.scanint;
        var sum = (long)(N + 1) * N / 2 / 2;
        int ok = A.Min();
        int ng = A.Max() + 1;

        while (ng - ok > 1)
        {
            int mid = (ok + ng) / 2;

            //WriteLine($"{ok} {ng} {mid}");
            if (calc(mid, A, sum))
            {
                ok = mid;
            }
            else
            {
                ng = mid;
            }
        }

        WriteLine(ok);
    }

    long merge_count(int[] A)
    {
        int n = A.Length;
        if (n <= 1) return 0;

        long cnt = 0;
        int m = n >> 1;
        var B = new int[m];
        var C = new int[n - m];
        for (int i = 0; i < B.Length; i++)
        {
            B[i] = A[i];
        }
        for (int i = 0; i < C.Length; i++)
        {
            C[i] = A[i + m];
        }

        cnt += merge_count(B);
        cnt += merge_count(C);

        int ai = 0, bi = 0, ci = 0;
        while (ai < n)
        {
            if (bi < B.Length && (ci == C.Length || B[bi] <= C[ci]))
            {
                A[ai++] = B[bi++];
            }
            else
            {
                cnt += (n >> 1) - bi;
                A[ai++] = C[ci++];
            }
        }
        return cnt;
    }
}


