func cusum(key int, arr []int) ([]int, int, int) {
	newArr := make([]int, len(arr))
	_sum := 0
	_min := len(arr)
	_max := 0
	for i, v := range arr {
		if v < key { 
			_sum -= 1 
		} else {
			_sum += 1 
		}

		newArr[i] = _sum
		if _sum > _max { _max = _sum }
		if _sum < _min { _min = _sum }
	}
	return newArr, _min, _max
}


func countFallNumber(arr []int, key int) float32 {
	ans := 0
	newArr, _min, _max := cusum(key, arr)
	n := _max - _min + 1
	b := BinaryIndexTree{BIT: make([]int, n)}
	for _, v := range newArr{
		ans += b.sum(n) - b.sum(v-_min+1)
		b.add(v-_min+1, 1)
	}
	return float32(ans)
}

func binarySearch(N int, searchList []int, nums []int) int {
	th := float32(N * (N+1) / 4)
	right := len(searchList)
	left := -1
	for (right - left) > 1 {
		mid := (right + left) / 2
		if countFallNumber(nums, searchList[mid]) > th { 
			right = mid 
		} else {
			left  = mid 
		}
	}
	return left
}

