func cusum(k int,a []int) ([]int,int,int,int) {
  var b []int = make([]int,len(a))
  var sum,neg int
  var min int = len(a)
  var max int = -len(a)
  for i:=0;i<len(a);i++ {
    if a[i] < k {
      sum -= 1 
    } else {
      sum += 1 
    }
    b[i] = sum
    if sum > max { max = sum }
    if sum < min { min = sum }
    if sum < 0 { neg += 1 }
  }
  return b,min,max,neg
}

func countFallNumber(a []int,k int) int {
  var x int
  b,min,max,neg := cusum(k,a)
  var n int = max-min+1
  bit := BinaryIndexTree{BIT:make([]int,n)}
  for _,v := range b {
    x += bit.sum(n) - bit.sum(v-min+1)
    bit.add(v-min+1,1)
  }
  return x + neg
}

