  th := float64((n*(n+1))/4)
  var r int = len(s)
  var l int = -1
  var m int
  for r-l > 1 {
    m = (r+l)/2
    if float64(countFallNumber(a,s[m])) > th { 
      r = m 
    } else {
      l = m 
    }
  }
  return l
}

