			sum[i] += 1
		} else {
			sum[i] += -1
		}
		if i-1 >= 0 {
			sum[i] += sum[i-1]
		}
	}

	min := 0
	for _, v := range sum {
		if v < min {
			min = v
		}
	}

	if min <= 0 {
		for i, v := range sum {
			sum[i] = v - min + 1
		}
	}

