	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := bufio.NewReader(fp)

	var n int

	fmt.Sscan(getNextLine(scanner), &n)
	aaa := getIntList(scanner)
	sums := make([]int, n+1)
	size := 1
	for size < 4*n {
		size <<= 1
	}

	left := 1
	right := 1000000000
	sums[0] = size>>1 + n - 1
	for left < right {
		sum := 0
		wholesum := 0
		m := (left + right) >> 1
		seg := make([]int, size)
		for i := 0; i < n; i++ {
			wholesum += n - i
			if aaa[i] >= m {
				sums[i+1] = sums[i] + 1
			} else {
				sums[i+1] = sums[i] - 1
			}
			seg[sums[i+1]]++
			for j := sums[i]; j > 0; {
				j = (j - 1) >> 1
				seg[j]++
			}
			sum += count(0, sums[i+1]-size/2+2, 0, 0, size/2, seg)
		}

		if sum*2 >= wholesum {
			left = m + 1
			continue
		}
		right = m
	}
	sort.Sort(sort.IntSlice(aaa))
	ans := aaa[0]
	for i := len(aaa) - 1; i >= 0; i-- {
		if left > aaa[i] {
			ans = aaa[i]
			break
		}
	}
	fmt.Println(ans)
}

func count(a int, b int, i int, li int, ri int, seg []int) int {
	if ri <= a || li >= b {
		return 0
	}
	if a <= li && ri <= b {
		return seg[i]
	}
	return count(a, b, i*2+1, li, (li+ri)/2, seg) + count(a, b, i*2+2, (li+ri)/2, ri, seg)
}

