type BinaryIndexTree struct { BIT []int }
func (b *BinaryIndexTree) add(idx int, val int){
	for x :=idx; x <= len(b.BIT); x+=x&-x {
		b.BIT[x-1] += val
	}
}

func (b *BinaryIndexTree) sum(idx int) int {
