type BinaryIndexedTree []int
func InitBIT(N int) BinaryIndexedTree {
  BIT := make([]int, N + 1)
  return BIT
}
func (BIT *BinaryIndexedTree) Increment(idx int) {
  N := len((*BIT))
  for i := idx; i < N; i += i & (-i) {
    (*BIT)[i]++
  }
}
func (BIT *BinaryIndexedTree) Update(idx, v int) {
  N := len((*BIT))
  d := v - BIT.Get(idx) + BIT.Get(idx - 1)
  for i := idx; i < N; i += i & (-i) {
    (*BIT)[i] += d
  }
}
func (BIT *BinaryIndexedTree) Get(idx int) int {
  if idx < 1 { return 0 }
  b := 0
  for i := idx; 0 < i; i -= i & (-i) {
    b += (*BIT)[i]
  }
  return b
}
func (BIT BinaryIndexedTree) Query(s, t int) int {
  return BIT.Get(t) - BIT.Get(s)
}

func Count(A *[]int, k int) int {
  N := len((*A))
  B := make([]int, N + 1)
  for i, a := range (*A) {
    B[i + 1] = B[i]
    if a <= k {
      B[i + 1]++
    } else {
      B[i + 1]--
    }
  }
  C := make([][]int, N + 1)
  for i, b := range B {
    C[i] = []int{i + 1, b}
  }
  sort.Sort(Items(C))
  BIT := InitBIT(N + 1)
  cnt := 0
  for _, c := range C {
    cnt += BIT.Get(c[0])
    BIT.Increment(c[0])
  }
  return cnt
}

func Solve(N int, A []int) int {
  high, low := Max(A), 0
  N2 := N * (N + 1) / 2
  B := N2 / 2 + 1
  for 1 < high - low {
    med := (high + low) / 2
    if Count(&A, med) < B {
      low = med
    } else {
      high = med
    }
  }
  return high
}

