	newArr := make([]int, len(arr))
	_sum := 0
	_nega := 0
	_min := len(arr)
	_max := -1 * len(arr)
	for i, v := range arr {
		if v < key { 
			_sum -= 1 
		} else {
			_sum += 1 
		}

		newArr[i] = _sum
		if _sum > _max { _max = _sum }
		if _sum < _min { _min = _sum }
		if _sum < 0    { _nega += 1 }
	}
	return newArr, _min, _max, _nega
}


