	ans := 0
	newArr, _min, _max, _nega := cusum(key, arr)
	n := _max - _min + 1
	b := BinaryIndexTree{BIT: make([]int, n)}
	for _, v := range newArr{
		ans += b.sum(n) - b.sum(v-_min+1)
		b.add(v-_min+1, 1)
	}
	return ans + _nega
}

