	th := float32(N * (N+1) / 4)
	right := len(searchList)
	left := -1
	for (right - left) > 1 {
		mid := (right + left) / 2
		if float32(countFallNumber(nums, searchList[mid])) > th { 
			right = mid 
		} else {
			left  = mid 
		}
	}
	return left
}

