	int sum=t[t[pr].l].cnt-t[t[pl].l].cnt,mid=(l+r)>>1;
	if(sum>=k) return query(t[pl].l,t[pr].l,l,mid,k);
	else return query(t[pl].r,t[pr].r,mid+1,r,k-sum);
}

