def judge(x, lst):

    length = len(lst)
    all_pair = (length*(length-1) // 2) + length

    lst_r = [-1 if i < x else 1 for i in lst]
    array = np.cumsum(np.array(lst_r))
    lst_accum = array - min(array) + 1

    bit = Bit(max(lst_accum))
    ans = 0
    for i, p in enumerate(lst_accum):
        bit.add(p, 1)
        ans += i + 1 - bit.sum(p)

    ans = all_pair - ans
    if ans >= (all_pair//2) + 1:
        return True
    else:
        return False


