class SegmentTree:

    def __init__(self):
        self.n = self.array_n()
        self.dat = [0] * (self.n * 2 - 1)
        self.l = [None] * (self.n * 2 - 1)
        self.r = [None] * (self.n * 2 - 1)
        self.set_range(0, 0, self.n)

    @staticmethod
    def array_n():
        n = 1
        while n < 2 * N + 1:
            n *= 2
        return n

    def clear(self):
        self.dat = [0] * (self.n * 2 - 1)

    def set_range(self, num, left, right):
        self.l[num] = left
        self.r[num] = right
        if num < self.n - 1:
            self.set_range(2 * num + 1, left, (left + right) // 2)
            self.set_range(2 * num + 2, ((left + right) // 2), right)

    def index(self, x):
        return (self.n - 1) + x + N

    def add(self, x):
        i = self.index(x)
        while i > 0:
            self.dat[i] += 1
            i = (i - 1) // 2
        self.dat[0] += 1

    def sum_recur(self, num, right):
        if self.r[num] == right:
            return self.dat[num]
        h = (self.l[num] + self.r[num]) // 2
        if right <= h:
            return self.sum_recur(num * 2 + 1, right)
        else:
            return self.dat[num * 2 + 1] + self.sum_recur(num * 2 + 2, right)

    def sum(self, x):
        right = N + x + 1
        return self.sum_recur(0, right)


