use std::io::Read;
use std::ops::AddAssign;

const MAX: i64 = 100_001;
const MOD: i64 = 1_000_000_007;

struct BinaryIndexedTree<T> {
    n: usize,
    data: Vec<T>,
}

impl<T: Default + Copy + AddAssign> BinaryIndexedTree<T> {
    fn new(n: usize) -> BinaryIndexedTree<T> {
        BinaryIndexedTree {
            n: n,
            data: vec![Default::default(); n],
        }
    }

    fn add(&mut self, i: usize, x: T) {
        let mut i = i;
        while i < self.n {
            self.data[i] += x;
            i |= i + 1;
        }
    }

    // iは1-indexed
    fn sum(&self, i: usize) -> T {
        let mut i = i;
        let mut sum = Default::default();

        loop {
            sum += self.data[i];
            i = i & (i + 1);
            if i > 0 {
                i -= 1;
            } else {
                break;
            }
        }
        return sum;
    }

    fn clear(&mut self) {
        for i in 0..self.data.len() {
            self.data[i] = Default::default();
        }
    }
}

