        for i in 0..n {
            if a[i] >= mb {
                sum += 1;
            } else {
                sum -= 1;
            }
            let pos = (sum + offset as i32) as usize;
            count += bit.sum(pos);
            bit.add(pos, 1);
        }
        //        dbg!(mb, count, target_count);
        if count >= target_count {
