fn count(m: u32, a: &[u32]) -> bool {
    let n = a.len();
    let mut bit = fenwick::Tree::new(2 * n + 2);
    let mut pos = n + 1;
    bit.add(pos, 1);
    let mut cnt = 0;
    for &a in a {
        if a >= m {
            pos += 1;
        } else {
            pos -= 1;
        }
        cnt += bit.sum(pos);
        bit.add(pos, 1);
    }
    n * (n + 1) <= 4 * cnt
}

