fn median(a: &[usize], x: usize) -> bool {
    // println!("x={}", x);

    let mut cnt = 0;
    let mut ttl = 0;
    for l in 0..a.len() {
        for r in l..a.len() {
            let lr = &a[l..(r+1)];
            let sum = lr.iter().fold(0, |sum, &a| sum + if a >= x { 1 } else { -1 });
            if sum >= 0 { cnt += 1 };
            // println!("{:?} {}", lr, sum);
            ttl += 1;
        }
    }
    // println!("x={} cnt={} ttl={}", x, cnt, ttl);

    let half = if ttl % 2 == 1 { ttl/2 + 1 } else { ttl/2 };
    if cnt >= half { true } else { false }
}

fn solve(a: &[usize], b: &[usize]) -> usize {
  let mut s = 0i32;
  let mut e = a.len() as i32 - 1;

  let mut last_x = 0;
  while s <= e {
    let i = (s + e) / 2;
    // println!("s={} e={} i={}", s, e, i);

    let x = b[i as usize];
    if median(a, x) {
        // println!("{} is ok", x);
        last_x = x;
        s = i + 1;
    } else {
        // println!("{} is ng", x);
        e = i - 1;
    }
  }
  last_x
}

