struct FenwickTree(Vec<i64>);
impl FenwickTree {
    fn new(n: usize) -> FenwickTree {
        FenwickTree(vec![0; n + 1])
    }
    fn add(&mut self, i: usize, v: i64) {
        assert!(i > 0);
        let n = self.0.len() as i64;
        let mut i = i as i64;
        while i < n {
            self.0[i as usize] += v;
            i += i & -i;
        }
    }
    fn sum(&self, i: usize) -> i64 {
        assert!(i > 0);
        let mut i = i as i64;
        let mut r = 0;
        while i > 0 {
            r += self.0[i as usize];
            i -= i & -i;
        }
        r
    }
    fn lower_bound(&self, x: &i64) -> usize {
        let n = self.0.len();
        let mut k = 1;
        while k * 2 < n {
            k *= 2;
        }
        let mut i = 0;
        let mut x = *x;
        while k > 0 {
            if i + k < n && self.0[i + k] < x {
                x -= self.0[i + k];
                i += k;
            }
            k /= 2;
        }
        i + 1
    }
}

