fn main() {
    input! {n, a: [usize; n]};
    let nn = ((n + 1) * n / 2 + 1) / 2;
    let b: BTreeSet<_> = a.iter().cloned().collect();
    let b: Vec<_> = b.iter().cloned().collect();
    let (mut l, mut r) = (0, b.len());
    while r - l > 1 {
        let m = l + (r - l) / 2;
        let s: Vec<isize> = a
            .iter()
            .map(|ai| if *ai >= b[m] { 1 } else { -1 })
            .scan(0, |acc, x| {
                *acc += x;
                Some(*acc)
            })
            .collect();
        let ms = min(0, *s.iter().min().unwrap());
        let mut s: Vec<_> = s.into_iter().map(|si| si - ms + 1).collect();
        let mut t = vec![1];
        t.append(&mut s);
        let s = t;
        let cap = *s.iter().max().unwrap() as usize + 1;
        let mut c = vec![0; cap];
        let mut p = 0;
        for si in s {
            let mut i: isize = si;
            while i > 0 {
                p += c[i as usize];
                i -= i & -i;
            }
            let mut i: isize = si;
            while i < cap as isize {
                c[i as usize] += 1;
                i += i & -i;
            }
        }
        if p >= nn {
            l = m
        } else {
            r = m
        }
    }
    println!("{}", b[l]);
}

