}

impl<T: Default + Copy + AddAssign> BinaryIndexedTree<T> {
    fn new(n: usize) -> BinaryIndexedTree<T> {
        BinaryIndexedTree {
            n,
            data: vec![Default::default(); n],
        }
    }

    fn add(&mut self, i: usize, x: T) {
        let mut i = i;
        while i < self.n {
            self.data[i] += x;
            i |= i + 1;
        }
    }

    // iは1-indexed
    fn sum(&self, i: usize) -> T {
        let mut i = i;
        let mut sum = Default::default();

        loop {
            sum += self.data[i];
            i = i & (i + 1);
            if i > 0 {
                i -= 1;
            } else {
                break;
            }
        }
        return sum;
    }

    fn clear(&mut self) {
        for i in 0..self.data.len() {
            self.data[i] = Default::default();
        }
    }
}

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();

    let n = iter.next().unwrap().parse().unwrap();
    let a: Vec<i64> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let target_count = (n as i64 * (n + 1) as i64 / 2 + 1) / 2;
    let offset = n + 2;
    let mut bit = BinaryIndexedTree::new(offset * 2);
    let mut lb = 0;
    let mut ub = a.iter().max().unwrap() + 1;

    while ub - lb > 1 {
        let mb = (ub + lb) / 2;
        let mut count = 0;
        let mut sum = 0;
        bit.clear();
        bit.add(offset, 1);

        for i in 0..n {
            if a[i] >= mb {
                sum += 1;
            } else {
                sum -= 1;
            }
            let pos = (sum + offset as i32) as usize;
            count += bit.sum(pos);
            bit.add(pos, 1);
        }
        //        dbg!(mb, count, target_count);
        if count >= target_count {
            lb = mb;
        } else {
            ub = mb;
        }
    }
    println!("{}", lb);
}

