            .iter()
            .map(|&ai| if ai >= m { 1 } else { -1 })
            .collect::<Vec<isize>>();
        let mut acc_b = vec![0; n];
        acc_b[0] = b[0];
        for i in 1..n {
            acc_b[i] = acc_b[i - 1] + b[i];
