fn count_invs(slice: &[i32]) -> (Vec<i32>, u64) {
    let len = slice.len();
    if len == 1 {
        return (slice.to_vec(), 0);
    }

    let mid = len / 2;
    let (xs, xs_invs) = count_invs(&slice[..mid]);
    let (ys, ys_invs) = count_invs(&slice[mid..]);

    let mut result = Vec::with_capacity(len);
    let mut invs = xs_invs + ys_invs;

    let (mut i, mut j) = (0, 0);
    let (xs_len, ys_len) = (xs.len(), ys.len());
    while i < xs_len && j < ys_len {
        let (x, y) = (xs[i], ys[j]);
        if x <= y {
            result.push(x);
            i += 1;
        } else {
            result.push(y);
            j += 1;
            invs += (xs_len - i) as u64;
        }
    }

    result.extend_from_slice(&xs[i..]);
    result.extend_from_slice(&ys[j..]);

    debug!(result);

    (result, invs)
}

fn main() {
    input! {
      n: usize,
      xs: [i32; n]
    }

    let ms_len = n as u64 * (n as u64 + 1) / 2;

    let mut l = 0;
    let mut r = 1_000_000_001;
    while r - l > 1 {
        let mid = (l + r) / 2;

        let mut ts = xs
            .iter()
            .map(|&x| if mid <= x { 1 } else { -1 })
            .collect::<Vec<i32>>();
        for i in 1..n {
            ts[i] += ts[i - 1];
        }

        let invs = count_invs(&ts).1;
        if ms_len / 2 > invs {
            l = mid;
        } else {
            r = mid;
        }

        debug!(mid, invs);
    }

    println!("{}", l);
}

use std::collections::{BTreeMap, BTreeSet};
use std::ops::{AddAssign, Sub};

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };

    let n = sc.read();
    let a: Vec<i32> = sc.read_vec(n);

    let mut ok = 0;
    let mut ng = std::i32::MAX / 2;
    while ng - ok > 1 {
        let x = (ok + ng) / 2;
        let a = a
            .iter()
            .map(|&a| if a < x { -1 } else { 1 })
            .collect::<Vec<_>>();
        let mut sum = vec![0; n + 1];
        for i in 0..n {
            sum[i + 1] = sum[i] + a[i];
        }

        let map = sum
            .iter()
            .map(|&s| s)
            .collect::<BTreeSet<_>>()
            .iter()
            .enumerate()
            .map(|(i, &s)| (s, i))
            .collect::<BTreeMap<_, _>>();
        let mut bit = FenwickTree::new(n, 0);
        let mut ans = 0;
        for i in sum.iter().map(|s| *map.get(s).unwrap()) {
            ans += bit.sum_one(i + 1);
            bit.add(i, 1);
        }

        let total = (n + 1) * n / 2;
        let half = (total + 1) / 2;
        if ans >= half {
            ok = x;
        } else {
            ng = x;
        }
    }
    println!("{}", ok);
}

/// `FenwickTree` is a data structure that can efficiently update elements
/// and calculate prefix sums in a table of numbers.
/// [https://en.wikipedia.org/wiki/Fenwick_tree](https://en.wikipedia.org/wiki/Fenwick_tree)
pub struct FenwickTree<T> {
    n: usize,
    data: Vec<T>,
    init: T,
}

impl<T: Copy + AddAssign + Sub<Output = T>> FenwickTree<T> {
    /// Constructs a new `FenwickTree`. The size of `FenwickTree` should be specified by `size`.
    pub fn new(size: usize, init: T) -> FenwickTree<T> {
        FenwickTree {
            n: size + 1,
            data: vec![init; size + 1],
            init: init,
        }
    }

    pub fn add(&mut self, k: usize, value: T) {
        let mut x = k;
        while x < self.n {
            self.data[x] += value;
            x |= x + 1;
        }
    }

    /// Returns a sum of range `[l, r)`
    pub fn sum(&self, l: usize, r: usize) -> T {
        self.sum_one(r) - self.sum_one(l)
    }

    /// Returns a sum of range `[0, k)`
    pub fn sum_one(&self, k: usize) -> T {
        if k >= self.n {
            panic!("");
        }

        let mut result = self.init;
        let mut x = k as i32 - 1;
        while x >= 0 {
            result += self.data[x as usize];
            x = (x & (x + 1)) - 1;
        }

        result
    }
}

pub struct Scanner<R> {
    reader: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .reader
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn read_vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

