use std::io::*;
struct IO<R: Read, W: Write, E: Write> {
    Read: R,
    Write: BufWriter<W>,
    Error: BufWriter<E>,
}
impl<R: Read, W: Write, E: Write> IO<R, W, E> {
    fn new(r: R, w: W, e: E) -> IO<R, W, E> {
        IO {
            Read: r,
            Write: BufWriter::new(w),
            Error: BufWriter::new(e),
        }
    }
    fn read<T>(&mut self) -> T
    where
        T: std::str::FromStr,
    {
        let next: String = self
            .Read
            .by_ref()
            .bytes()
            .map(|c| c.unwrap() as char)
            .skip_while(|c| c.is_whitespace())
            .take_while(|c| !c.is_whitespace())
            .collect();
        next.parse().ok().unwrap()
    }
    fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
    fn chari(&mut self) -> Vec<i64> {
        self.chars()
            .iter()
            .map(|&c| (c as u8 - b'0') as i64)
            .collect::<Vec<i64>>()
    }
    fn readn<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read::<T>()).collect::<Vec<_>>()
    }
    fn readmat<T: std::str::FromStr>(&mut self, n: usize, m: usize) -> Vec<Vec<T>> {
        (0..n).map(|_| self.readn(m)).collect()
    }
    fn write<S: ToString>(&mut self, val: S) {
        self.Write.write(val.to_string().as_bytes());
    }
    fn writeln<S: ToString>(&mut self, val: S) {
        self.Write.write(val.to_string().as_bytes());
        self.Write.write(b"\n");
    }
    fn debug<S: std::fmt::Debug>(&mut self, val: S) {
        writeln!(self.Error, "(debug) {:?}", &val);
    }
    fn debug2<S: std::fmt::Debug, T: std::fmt::Debug>(&mut self, val1: S, val2: T) {
        writeln!(self.Error, "(debug2) {:?} -> {:?}", val1, val2);
    }
    fn debug3<S: std::fmt::Debug, T: std::fmt::Debug, U: std::fmt::Debug>(
        &mut self,
        val1: S,
        val2: T,
        val3: U,
    ) {
        writeln!(
            self.Error,
            "(debug3) {:?} -> {:?} -> {:?}",
            val1, val2, val3
        );
    }
}

use std::io::Read;
use std::ops::AddAssign;

const MAX: i64 = 100_001;
const MOD: i64 = 1_000_000_007;

struct BinaryIndexedTree<T> {
    array: Vec<T>,
}

impl<T: Default + Copy + AddAssign> BinaryIndexedTree<T> {
    // N個の値のprefix sumを管理する
    fn new(n: usize) -> BinaryIndexedTree<T> {
        BinaryIndexedTree {
            array: vec![Default::default(); n],
        }
    }

    // iは1-indexed
    fn add(&mut self, i: usize, x: T) {
        assert!(1 <= i && i < self.array.len());

        // ループ内でのビット演算のためにi32にキャスト。競プロの範囲では多分問題は起こらない。
        let mut i = i as i32;
        let size = self.array.len() as i32;
        while i < size {
            self.array[i as usize] += x;
            i += i & -i;
        }
    }

    // iは1-indexed
    fn sum(&self, i: usize) -> T {
        assert!(1 <= i && i < self.array.len());

        // ループ内でのビット演算のためにi32にキャスト。競プロの範囲では多分問題は起こらない。
        let mut i = i as i32;
        let mut sum = Default::default();
        while i > 0 {
            sum += self.array[i as usize];
            i -= i & -i;
        }
        return sum;
    }

    fn clear(&mut self) {
        for i in 0..self.array.len() {
            self.array[i] = Default::default();
        }
    }
}

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();

    let n = iter.next().unwrap().parse().unwrap();
    let a: Vec<i64> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let target_count = (n as i64 * (n + 1) as i64 / 2 + 1) / 2;
    let offset = n + 2;
    let mut bit = BinaryIndexedTree::new(offset * 2);
    let mut lb = 0;
    let mut ub = a.iter().max().unwrap() + 1;

    while ub - lb > 1 {
        let mb = (ub + lb) / 2;
        let mut count = 0;
        let mut sum = 0;
        bit.clear();
        bit.add(offset, 1);

        for i in 0..n {
            if a[i] >= mb {
                sum += 1;
            } else {
                sum -= 1;
            }
            let pos = (sum + offset as i32) as usize;
            count += bit.sum(pos);
            bit.add(pos, 1);
        }
        //        dbg!(mb, count, target_count);
        if count >= target_count {
            lb = mb;
        } else {
            ub = mb;
        }
    }
    println!("{}", lb);
}

use std::collections::{BTreeMap, BTreeSet};
