fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };

    let n = sc.read();
    let a: Vec<i32> = sc.read_vec(n);

    let mut ok = 0;
    let mut ng = std::i32::MAX / 2;
    while ng - ok > 1 {
        let x = (ok + ng) / 2;
        let a = a
            .iter()
            .map(|&a| if a < x { -1 } else { 1 })
            .collect::<Vec<_>>();
        let mut sum = vec![0; n + 1];
        for i in 0..n {
            sum[i + 1] = sum[i] + a[i];
        }

        let map = sum
            .iter()
            .map(|&s| s)
            .collect::<BTreeSet<_>>()
            .iter()
            .enumerate()
            .map(|(i, &s)| (s, i))
            .collect::<BTreeMap<_, _>>();
        let m = map.len();
        let mut bit = FenwickTree::new(m, 0);
        let mut ans = 0;
        for i in sum.iter().map(|s| *map.get(s).unwrap()) {
            ans += bit.sum_one(i + 1);
            bit.add(i, 1);
        }

        let total = (n + 1) * n / 2;
        let half = (total + 1) / 2;
        if ans >= half {
