fn calc(x: usize, arr: &[usize]) -> usize {
    let converted = arr.iter().map(|val| if *val >= x { 1 } else { -1 } ).collect::<Vec<_>>();
    let mut cumsum = vec![0; arr.len() + 1];
    for i in 0..converted.len() {
        cumsum[i + 1] = cumsum[i] + converted[i];
    }
    let values = cumsum.iter().cloned().collect::<BTreeSet<_>>();
    let converter = values.into_iter().enumerate().map(|(i, val)| (val, i + 1)).collect::<HashMap<_, _>>();
    let mut bit = BinaryIndexedTree::new(converter.len());
    let mut count = 0;
    for val in cumsum.iter() {
        count += bit.query(converter[val]);
        bit.add(converter[val], 1);
    }
    count
}

struct BinaryIndexedTree {
    len: usize,
    values: Vec<usize>,
}

impl BinaryIndexedTree {
    fn new(len: usize) -> BinaryIndexedTree {
        BinaryIndexedTree{ len: len, values: vec![0; len + 1] }
    }
    fn add(&mut self, mut x: usize, val: usize) {
        assert!(x > 0);
        while x <= self.len {
            self.values[x] += val;
            x += x & ((!x) + 1);
        }
    }
    fn query(&self, mut x: usize) -> usize {
        assert!(x > 0);
        let mut sum = 0;
        while x > 0 {
            sum += self.values[x];
            x -= x & ((!x) + 1);
        }
        sum
    }
}

