            c[i as usize] += 1;
            i += i & -i;
        }
        for si in s {
            let mut i: isize = si;
            while i > 0 {
                p += c[i as usize];
                i -= i & -i;
            }
            let mut i: isize = si;
            while (i as usize) < cap {
                c[i as usize] += 1;
                i += i & -i;
            }
        }
