fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let a: Vec<i64> = sc.vec(n);
    let mut ok = 0;
    let mut ng = 1e10 as i64;
    while ng - ok > 1 {
        let x = (ng + ok) / 2;
        let b = a
            .iter()
            .map(|&a| if a >= x { 1 } else { -1 })
            .collect::<Vec<_>>();
        let mut acc = vec![0; n + 1];
        for i in 0..n {
            acc[i + 1] = acc[i] + b[i];
        }

        let map = acc
            .iter()
            .cloned()
            .collect::<BTreeSet<_>>()
            .into_iter()
            .enumerate()
            .map(|(i, acc)| (acc, i))
            .collect::<BTreeMap<_, _>>();
        let indices = acc
            .iter()
            .map(|acc| *map.get(acc).unwrap())
            .collect::<Vec<_>>();

        let m = map.len();
        let mut bit = FenwickTree::new(m, 0);
        let mut bigger = 0;
        for i in 0..(n + 1) {
            let v = indices[i];
            bigger += bit.sum(v + 1, m);
            bit.add(v, 1);
        }

        let total = n * (n - 1) / 2 + n;
        if bigger * 2 > total {
            ng = x;
        } else {
            ok = x;
        }
    }

    println!("{}", ok);
}

