fn count(m: u32, a: &[u32]) -> bool {
    let n = a.len();
    let mut bit = fenwick::Tree::new(2 * n + 2);
    let mut pos = n + 1;
    bit.add(pos, 1);
    let mut cnt = 0u64;
    for &a in a {
        if a >= m {
            pos += 1;
        } else {
            pos -= 1;
        }
        cnt += bit.sum(pos);
        bit.add(pos, 1);
    }
    let n = n as u64;
    n * (n + 1) <= 4 * cnt
}

fn run() {
    input! {
        n: usize,
        a: [u32; n],
    }
    let mut l = 0;
    let mut r = 1_000_000_000 + 1;
    while r - l > 1 {
        let m = (l + r) / 2;
        if count(m, &a) {
            l = m;
        } else {
            r = m;
        }
    }
    println!("{}", l);
}

fn main() {
    run();
}

