use std::collections::{BTreeMap, BTreeSet};
use std::ops::{AddAssign, Sub};

fn main() {
    input!(n: usize, a: [i64; n]);

    let mut ok = 0;
    let mut ng = 1e10 as i64;
    while ng - ok > 1 {
        let x = (ng + ok) / 2;
        let a = a
            .iter()
            .map(|&a| if a < x { -1 } else { 1 })
            .collect::<Vec<_>>();
        let mut sum = vec![0; n + 1];
        for i in 0..n {
            sum[i + 1] = sum[i] + a[i];
        }
        let mut set = BTreeSet::new();
        for i in 0..(n + 1) {
            set.insert(sum[i]);
        }
        let mut map = BTreeMap::new();
        for (i, &x) in set.iter().enumerate() {
            map.insert(x, i);
        }
        let mut compact = vec![0; n + 1];
        for i in 0..(n + 1) {
            compact[i] = *map.get(&sum[i]).unwrap();
        }

        let m = map.len();
        let mut ans = 0;
        let mut bit = FenwickTree::new(m, 0);
        for i in 0..(n + 1) {
            ans += bit.sum_one(compact[i] + 1);
            // println!("+{}", bit.sum_one(compact[i] + 1));
            bit.add(compact[i], 1);
        }

        // println!("x={}", x);
        // println!("a={:?}", a);
        // println!("sum={:?}", sum);
        // println!("compact={:?}", compact);
        // println!("ans={}", ans);

        let total = n * (n - 1) / 2 + n;
        let half = (total + 1) / 2;
        if ans >= half {
            ok = x;
        } else {
            ng = x;
        }
    }
    println!("{}", ok);
}

