use std::cmp::Ord;

fn count_invs<T: Ord + Copy>(seq: &[T]) -> u64 {
    fn merge<T: Ord + Copy>(left: &[T], right: &[T]) -> (Vec<T>, u64) {
        let mut result = Vec::new();
        let mut count = 0;
        let mut index_l = 0;
        let mut index_r = 0;

        while index_l < left.len() && index_r < right.len() {
            let l = left[index_l];
            let r = right[index_r];
            if l <= r {
                result.push(l);
                index_l += 1;
            } else {
                result.push(r);
                index_r += 1;
                count += (left.len() - index_l) as u64;
            }
        }

        if index_l < left.len() {
            result.extend_from_slice(&left[index_l..]);
        } else if index_r < right.len() {
            result.extend_from_slice(&right[index_r..]);
        }

        (result, count)
    }

    fn sub<T: Ord + Copy>(seq: &[T]) -> (Vec<T>, u64) {
        if seq.len() <= 1 {
            (seq.to_vec(), 0)
        } else {
            let mid = seq.len() / 2;
            let (left, n_l) = sub(&seq[..mid]);
            let (right, n_r) = sub(&seq[mid..]);
            let (merged, n) = merge(&left, &right);
            (merged, n_l + n_r + n)
        }
    }

    sub(seq).1
}

use std::ops::Add;
use std::default::Default;

fn cumulate_with_sentinel<T: Add<Output = T> + Default + Copy>(seq: &[T]) -> Vec<T> {
    let mut result = vec![T::default()];
    for x in seq {
        let next = *result.last().unwrap() + *x;
        result.push(next);
    }
    result
}

fn is_ans_ge(x: u32, aa: &[u32]) -> bool {
    let signs: Vec<i64> = aa.iter().map(|&a| if x <= a { 1 } else { -1 }).collect();
    let ss = cumulate_with_sentinel(&signs);
    let n = aa.len() as u64;
    // println!("{}: {}", x, count_invs_and_eqs(&ss));
    count_invs(&ss) <= n * (n+1) / 4
}

fn main() {
    readls!(_ = (), aa = Vec<u32>);
    let mut l = 0;
    let mut r = 1_000_000_001;
    while r - l > 1 {
        let mid = (r+l) / 2;
        if is_ans_ge(mid, &aa) {
            l = mid;
        } else {
            r = mid;
        }
    }
    println!("{}", l);
}

