struct Fenwick {
    n: usize,
    bit: Vec<i64>,
}
impl Fenwick {
    fn new(n: usize) -> Fenwick {
        Fenwick {
            n: n,
            bit: vec![0i64; n + 1],
        }
    }
    fn update(&mut self, a: usize, w: i64) {
        let mut x = a as isize;
        while x as usize <= self.n {
            self.bit[x as usize] += w; //  -> SUM
                                       // self.bit[x as usize] = max(self.bit[x as usize], w);
            x += 1 << x.trailing_zeros();
        }
    }
    fn query(&mut self, a: usize) -> i64 {
        let mut ret = 0;
        let mut x = a as isize;
        while x > 0 {
            ret += self.bit[x as usize]; // -> SUM QUERY
                                         // ret = max(self.bit[x as usize], ret);
            x -= 1 << x.trailing_zeros();
        }
        ret
    }
}
