fn calc(seq: &Vec<i64>, v: i64) -> usize {
    let n = seq.len();
    let mut total_cnts = vec![0, 0];
    let mut cnts = vec![vec![]; 2];
    let mut ret = 0;
    for i in 0..n {
        if seq[i] < v {
            let cnt1;
            if let Some(c) = cnts[1].pop() {
                total_cnts[1] -= c;
                cnt1 = 1 + c;
            } else {
                cnt1 = 1;
            }
            total_cnts[0] += cnt1;
            cnts[0].push(cnt1);
        } else {
            let cnt0;
            if let Some(c) = cnts[0].pop() {
                total_cnts[0] -= c;
                cnt0 = c;
            } else {
                cnt0 = 0;
            }
            if cnts[1].len() == 0 {
                cnts[1].push(1);
            } else {
                cnts[1][0] += 1;
            }
            total_cnts[1] += 1 + cnt0;
            cnts[1].push(cnt0);
        }
        ret += total_cnts[1];
    }
    return ret;
}

fn main() {
    let n = read::<usize>();
    let m = n * (n + 1) / 2;
    let mut seq = vec![0; n];
    for i in 0..n {
        seq[i] = read::<i64>();
    }
    let mut sort_seq = seq.clone();
    sort_seq.sort();
    let mut l = 0;
    let mut r = n;
    while r - l > 1 {
        let index = (r + l) / 2;
        let v = sort_seq[index];
        if calc(&seq, v) >= m / 2 {
            l = index;
        } else {
            r = index;
        }
    }
    println!("{}", sort_seq[l]);
}

