fn main() {
    let sc = std::io::stdin();
    let mut sc = Scanner { reader: sc.lock() };

    let n = sc.read();
    let a: Vec<i64> = sc.read_vec(n);

    let mut ng = 1e10 as i64;
    let mut ok = 0;
    while ng - ok > 1 {
        let x = (ok + ng) / 2;
        let a = a
            .iter()
            .map(|&a| if a >= x { 1 } else { -1 })
            .collect::<Vec<i64>>();
        let mut sum = vec![0; n + 1];
        for i in 0..n {
            sum[i + 1] = sum[i] + a[i];
        }

        let sum_map = sum
            .iter()
            .map(|&sum| sum)
            .collect::<BTreeSet<_>>()
            .iter()
            .enumerate()
            .map(|(i, &s)| (s, i))
            .collect::<BTreeMap<_, _>>();
        let m = sum_map.len();
        let mut bit = FenwickTree::new(m, 0);
        let mut ans = 0;
        for i in sum.iter().map(|s| *sum_map.get(s).unwrap()) {
            ans += bit.sum_one(i + 1);
            bit.add(i, 1);
        }

