    let mut r = 1_000_000_001;
    while r - l > 1 {
        let mid = (l + r) / 2;

        let ts = xs
            .iter()
            .map(|&x| if mid <= x { 1 } else { -1 })
            .collect::<Vec<i32>>();

        let mut ss = vec![0; n + 1];
        for i in 0..n {
            ss[i + 1] += ss[i] + ts[i];
        }

        let invs = count_invs(&ss).1;
        if invs <= ms_len / 2 {
            l = mid;
        } else {
            r = mid;
        }
    }

    println!("{}", l);
}

