fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let a: Vec<usize> = sc.vec(n);

    let mut ok = 0;
    let mut ng = 1 << 40;
    while ng - ok > 1 {
        let m = (ok + ng) / 2;
        if solve(&a, m) {
            ok = m;
        } else {
            ng = m;
        }
    }

    println!("{}", ok);
}

fn solve(a: &Vec<usize>, m: usize) -> bool {
    let n = a.len();
    let a: Vec<i64> = a.iter().map(|&a| if a >= m { 1 } else { -1 }).collect();
    let mut sum = vec![0; n + 1];
    for i in 0..n {
        sum[i + 1] = sum[i] + a[i];
    }

    let mut s = sum.clone();
    s.sort();
    let sum: Vec<_> = sum
        .into_iter()
        .map(|sum| s.binary_search(&sum).unwrap())
        .collect();

    let mut bit = fenwick_tree::FenwickTree::new(n + 1, 0);

    let mut count = 0;
    for sum in sum.into_iter() {
        count += bit.sum(0, sum + 1);
        bit.add(sum, 1);
    }

    let total = n * (n + 1) / 2;
    count * 2 >= total
}
